local function createBundledUI()
    local uiModule = (function()
        local TweenService = game:GetService('TweenService')
        local UserInputService = game:GetService('UserInputService')
        local GuiService = game:GetService('GuiService')
        local RunService = game:GetService('RunService')
        local HttpService = game:GetService('HttpService')
        local Players = game:GetService('Players')
        local TeleportService = game:GetService('TeleportService')
        local MarketplaceService = game:GetService('MarketplaceService')
        local StatsService = game:GetService('Stats')
        local ContextActionService = game:GetService('ContextActionService')
        local LocalPlayer = Players.LocalPlayer
        local Library = {}
        Library.Flags = {}
        Library.Windows = {}

        local function normalizeOpts(rawOpts, aliases)
            local tbl = {}
            if type(rawOpts) == 'string' then
                tbl.Name = rawOpts
            elseif type(rawOpts) == 'table' then
                for key, val in pairs(rawOpts) do
                    tbl[key] = val
                end
            end
            for key, val in pairs(aliases or {}) do
                if tbl[val] == nil and tbl[key] ~= nil then
                    tbl[val] = tbl[key]
                end
            end
            if tbl.Range then
                tbl.Min = tbl.Min or tbl.Range[1]
                tbl.Max = tbl.Max or tbl.Range[2]
            end
            return tbl
        end

        local function registerElement(container, opts, elem, frame, elemType)
            elem._type = elemType
            elem._frame = frame
            elem._window = container and container.Window
            elem._listeners = elem._listeners or {}
            local window = container and container.Window
            local name = opts.Name or opts.Text or opts.Title
            elem._searchName = type(name) == 'string' and name or ''
            elem._searchKey = string.lower(elem._searchName)
            if container and container._items then
                table.insert(container._items, elem)
            end
            if opts.Flag then
                Library.Flags[opts.Flag] = elem
                if window then
                    window:_flagCreated(opts.Flag, elem)
                end
            end
            elem._userVisible = opts.Visible ~= false

            function elem:IsVisible()
                return elem._userVisible
            end

            function elem:_isShown()
                return elem._userVisible and not elem._dependHidden and not (container and container._userVisible == false)
            end

            function elem:SetVisible(value)
                value = value and true or false
                if value == elem._userVisible or elem._destroyed then
                    return
                end
                elem._userVisible = value
                if not value then
                    if elem._onHide then
                        elem._onHide()
                    end
                    if elem.Open and type(elem.SetOpen) == 'function' then
                        elem:SetOpen(false)
                    end
                end
                if frame then
                    frame.Visible = value and not elem._dependHidden
                end
                if window then
                    window._controlsDirty = true
                end
            end

            if frame and not elem._userVisible then
                frame.Visible = false
            end

            function elem:SetDisabled(value)
                Library._setDisabled(elem, frame, value)
            end

            function elem:IsDisabled()
                return elem.Disabled == true
            end

            if opts.Disabled == true then
                elem:SetDisabled(true)
            end

            function elem:SetDependsOn(value, param)
                elem._dependsOn = value
                elem._dependsMode = param or elem._dependsMode
                elem._dependsMet = nil
                if value == nil then
                    Library._applyDepends(elem, true)
                elseif window then
                    Library._watchDepends(window, elem)
                end
            end

            if opts.DependsOn ~= nil then
                elem._dependsMode = opts.DependsMode
                elem:SetDependsOn(opts.DependsOn)
            end

            function elem:SetTooltip(value)
                elem._tooltip = value
                if frame and window and not elem._tooltipBound then
                    elem._tooltipBound = true
                    window:_attachTooltip(elem, frame)
                end
            end

            function elem:GetTooltip()
                return elem._tooltip
            end

            if opts.Tooltip ~= nil and opts.Tooltip ~= false then
                elem:SetTooltip(opts.Tooltip)
            end

            function elem:Destroy()
                if elem._destroyed then
                    return
                end
                elem._destroyed = true
                if window and window._tipOwner == elem then
                    window:_hideTooltip()
                end
                for idx, item in ipairs(elem._listeners) do
                    item()
                end
                elem._listeners = {}
                if container and container._items then
                    local foundIdx = table.find(container._items, elem)
                    if foundIdx then
                        table.remove(container._items, foundIdx)
                    end
                end
                if opts.Flag and Library.Flags[opts.Flag] == elem then
                    Library.Flags[opts.Flag] = nil
                end
                if window then
                    window._controlsDirty = true
                end
                if frame then
                    frame:Destroy()
                end
            end

            return elem
        end

