        function Library._readableMuted(param, param2, param3)
            local function luminance(col)
                local function channel(v)
                    return v <= 0.03928 and v / 12.92 or ((v + 0.055) / 1.055) ^ 2.4
                end
                return 0.2126 * channel(col.R) + 0.7152 * channel(col.G) + 0.0722 * channel(col.B)
            end

            local back = luminance(param3)
            for idx = 0, 20 do
                local lerped = param:Lerp(param2, idx / 20)
                local front = luminance(lerped)
                if (math.max(front, back) + 0.05) / (math.min(front, back) + 0.05) >= 4.6 then
                    return lerped
                end
            end

            return param2
        end

        local function getAccentContrastColor(accent)
            accent = accent or Library.Theme.Accent
            local lum = 0.2126 * accent.R + 0.7152 * accent.G + 0.0722 * accent.B
            if lum > 0.55 then
                return Color3.fromRGB(15, 15, 15)
            else
                return Color3.fromRGB(255, 255, 255)
            end
        end
