        function Library:LoadFont(opts)
            opts = normalizeOpts(opts, {})

            if type(writefile) ~= 'function' or type(isfile) ~= 'function' or typeof(getcustomasset) ~= 'function' then
                warn([[[IggyUiFork] custom fonts need writefile, isfile and getcustomasset]])
                return false
            end

            local name = opts.Name or 'CustomFont'
            local weights = opts.Weights or loadedFonts[name]

            if type(weights) ~= 'table' then
                warn('[IggyUiFork] no font weights for ' .. name)
                return false
            end

            local folder = opts.Folder or 'IggyUiFonts'

            pcall(function()
                if type(isfolder) == 'function' and type(makefolder) == 'function' and not isfolder(folder) then
                    makefolder(folder)
                end
            end)

            local tbl = {}

            for key, val2 in pairs(weights) do
                local entry = FONT_WEIGHTS[key]
                if entry then
                    local str2 = folder .. '/' .. name .. '-' .. key .. '.ttf'
                    local flag = true
                    if not isfile(str2) then
                        flag = pcall(function()
                            writefile(str2, game:HttpGet(val2))
                        end)
                    end
                    if flag then
                        table.insert(tbl, {
                            name = key,
                            weight = entry[1],
                            style = 'normal',
                            assetId = getcustomasset(str2)
                        })
                    else
                        warn('[IggyUiFork] could not download ' .. key .. ' weight of ' .. name)
                    end
                end
            end

            if #tbl == 0 then
                return false
            end

            local str = folder .. '/' .. name .. '.json'

            local ok = pcall(function()
                writefile(str, HttpService:JSONEncode({ name = name, faces = tbl }))
            end)

            if not ok then
                return false
            end

            local val = getcustomasset(str)

            local function helperFn(param, param2)
                local entry = FONT_WEIGHTS[param]
                if entry and weights[param] then
                    return Font.new(val, entry[2])
                end
                return param2
            end

            Library.Fonts.Regular = helperFn('Regular', Library.Fonts.Regular)
            Library.Fonts.Medium = helperFn('Medium', helperFn('Regular', Library.Fonts.Medium))
            Library.Fonts.SemiBold = helperFn('SemiBold', Library.Fonts.SemiBold)
            Library.Fonts.Bold = helperFn('Bold', helperFn('SemiBold', Library.Fonts.Bold))
            return true
        end

        function Library:PreloadIcons()
            return getIconMap() ~= false
        end

        local function resolveAssetId(asset)
            if type(asset) == 'number' then
                return 'rbxassetid://' .. string.format('%.0f', asset)
            end
            if type(asset) == 'string' then
                if asset:match('^%d+$') then
                    return 'rbxassetid://' .. asset
                end
                if asset:find('^rbxassetid://') or asset:find('^rbxasset://') or asset:find('^rbxthumb://') or asset:find('^http') then
                    return asset
                end
            end
            return nil
        end

        local DISCORD_ICON_B64 = ""

        local discordCustomAsset = nil
        local function getDiscordAsset()
            if discordCustomAsset then return discordCustomAsset end
            if typeof(getcustomasset) == "function" then
                if typeof(isfile) == "function" and isfile("awaui_discord.png") then
                    discordCustomAsset = getcustomasset("awaui_discord.png")
                    return discordCustomAsset
                end
                if typeof(writefile) == "function" then
                    local b64fn = (crypt and (crypt.base64_decode or crypt.base64decode or (crypt.base64 and crypt.base64.decode))) or function(data)
                        local b = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
                        data = string.gsub(data, '[^'..b..'=]', '')
                        return (data:gsub('.', function(x)
                            if (x == '=') then return '' end
                            local r,f='',(b:find(x)-1)
                            for i=6,1,-1 do r=r..(f%2^i-f%2^(i-1)>0 and '1' or '0') end
                            return r;
                        end):gsub('%d%d%d%d%d%d%d%d', function(x)
                            if (#x ~= 8) then return '' end
                            local c=0
                            for i=1,8 do c=c+(x:sub(i,i)=='1' and 2^(8-i) or 0) end
                            return string.char(c)
                        end))
                    end
                    pcall(function()
                        writefile("awaui_discord.png", b64fn(DISCORD_ICON_B64))
                    end)
                    if typeof(isfile) == "function" and isfile("awaui_discord.png") then
                        discordCustomAsset = getcustomasset("awaui_discord.png")
                        return discordCustomAsset
                    end
                end
            end
            return nil
        end

        local function resolveIcon(icon)
            if typeof(icon) == 'table' then
                return resolveAssetId(icon.Image) or icon.Image, icon.RectOffset, icon.RectSize, true, icon.Tint == true
            end
            local assetId = resolveAssetId(icon)
            if assetId then
                return assetId, nil, nil, true, false
            end
            if type(icon) ~= 'string' then
                return nil
            end
            local val = icon:gsub('^lucide:', '')
            if val == 'logo' or val == 'awalogo' or val == 'awa' or val == 'iggylogo' or val == 'iggy' then
                local logo = (Assets and Assets.Logo) or (Library and Library.Assets and Library.Assets.Logo)
                return logo, Vector2.zero, Vector2.zero, true, false
            end
            if val == 'discord' then
                local customAsset = getDiscordAsset()
                if customAsset then
                    return customAsset, Vector2.zero, Vector2.zero, true, true
                end
            end
            local val2 = getIconMap()
            if not val2 then
                return nil
            end
            local entry = (val2.Icons and val2.Icons[val]) or val2[val]
            if type(entry) == 'table' then
                local image = entry.Image
                if type(image) == 'number' then
                    image = 'rbxassetid://' .. tostring(image)
                end
                local entry2 = (val2.Spritesheets and val2.Spritesheets[tostring(image)]) or image
                return entry2, entry.ImageRectPosition, entry.ImageRectSize
            elseif type(entry) == 'string' then
                return entry
            end
            warn('[IggyUiFork] unknown lucide icon: ' .. val)
            return nil
        end

