        local function decodeBase64Bytes(b64)
            local tbl = {}
            local str = [[ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/]]
            for idx = 1, #str do
                tbl[str:byte(idx)] = idx - 1
            end
            local tbl2 = {}
            for idx = 1, #b64, 4 do
                local val, val2, val3, val4 = b64:byte(idx, idx + 3)
                local num = tbl[val] * 262144 + tbl[val2] * 4096 + (tbl[val3] or 0) * 64 + (tbl[val4] or 0)
                local num2, num3, num4 = num // 65536, num // 256 % 256, num % 256
                if val4 ~= 61 then
                    tbl2[#tbl2 + 1] = string.char(num2, num3, num4)
                elseif val3 ~= 61 then
                    tbl2[#tbl2 + 1] = string.char(num2, num3)
                else
                    tbl2[#tbl2 + 1] = string.char(num2)
                end
            end
            return table.concat(tbl2)
        end

