        local function sweepTable(tbl, decrementCount)
            for key in pairs(tbl) do
                if key.Parent == nil then
                    if orphanSweepSeen[key] then
                        tbl[key] = nil
                        orphanSweepSeen[key] = nil
                        if decrementCount then
                            themedInstanceCount -= 1
                        end
                    else
                        orphanSweepSeen[key] = true
                    end
                else
                    orphanSweepSeen[key] = nil
                end
            end
        end

        local function sweepThemedObjects()
            sweepTable(themedInstances, true)
            sweepTable(themeCallbacks, false)
            sweepThreshold = math.max(4000, themedInstanceCount * 2)
        end

        local function colorKey(col)
            return math.floor(col.R * 255 + 0.5) .. ',' .. math.floor(col.G * 255 + 0.5) .. ',' .. math.floor(col.B * 255 + 0.5)
        end

        local function rebuildThemeLookup()
            table.clear(themeColorLookup)
            for idx = #THEME_KEYS, 1, -1 do
                local entry = THEME_KEYS[idx]
                if entry ~= 'Accent2' and entry ~= 'TabStructure' then
                    themeColorLookup[colorKey(Library.Theme[entry])] = entry
                end
            end
        end

        rebuildThemeLookup()

        local function bindTheme(inst, property, themeKey)
            if not inst then return end
            local bound = themedInstances[inst]
            if not bound then
                bound = {}
                themedInstances[inst] = bound
                themedInstanceCount += 1
                if themedInstanceCount >= sweepThreshold then
                    sweepThemedObjects()
                end
            end
            bound[property] = themeKey
        end
        Library.BindTheme = bindTheme

        local function trackThemeProps(inst, props)
            if not inst or not props then return end
            for key, val in pairs(props) do
                if typeof(val) == 'Color3' then
                    local entry = themeColorLookup[colorKey(val)]
                    local entry2 = themedInstances[inst]
                    if entry then
                        if not entry2 then
                            entry2 = {}
                            themedInstances[inst] = entry2
                            themedInstanceCount += 1
                            if themedInstanceCount >= sweepThreshold then
                                sweepThemedObjects()
                            end
                        end
                        entry2[key] = entry
                    elseif entry2 then
                        entry2[key] = nil
                    end
                end
            end
        end

        local activeThemeSnapshot = table.clone(Library.Theme)
        local themeLerpConn = nil

        local function applyInstanceTheme(inst, propMap, palette)
            for key, val in pairs(propMap) do
                if (key == 'ImageColor3' or key == 'BackgroundColor3') and inst:IsA('GuiObject') then
                    local grad = inst:FindFirstChild('AccentGradient')
                    if grad and grad.Enabled then
                        continue
                    end
                end
                local entry = palette[val]
                if entry then
                    inst[key] = entry
                end
            end
        end

        local function applyThemeToAll(palette)
            for key, val in pairs(themedInstances) do
                pcall(applyInstanceTheme, key, val, palette)
            end
        end

        local function transitionTheme(duration)
            if themeLerpConn then
                themeLerpConn:Disconnect()
                themeLerpConn = nil
            end
            local tbl, tbl2 = {}, {}
            for idx, item in ipairs(THEME_KEYS) do
                local entry = Library.Theme[item]
                local entry2 = activeThemeSnapshot[item] or entry
                if entry2 ~= entry then
                    tbl[item] = entry2
                    tbl2[item] = entry2
                end
            end

            local function helperFn()
                for idx, item in ipairs(THEME_KEYS) do
                    tbl2[item] = Library.Theme[item]
                    activeThemeSnapshot[item] = Library.Theme[item]
                end
                applyThemeToAll(tbl2)
            end

            if duration <= 0 or next(tbl) == nil then
                helperFn()
                return
            end
            local num = 0
            themeLerpConn = RunService.Heartbeat:Connect(function(dt)
                num += dt
                if num >= duration then
                    themeLerpConn:Disconnect()
                    themeLerpConn = nil
                    helperFn()
                    return
                end
                local num2 = 1 - (1 - num / duration) ^ 5
                for key, val in pairs(tbl) do
                    local lerped = val:Lerp(Library.Theme[key], num2)
                    tbl2[key] = lerped
                    activeThemeSnapshot[key] = lerped
                end
                applyThemeToAll(tbl2)
            end)
        end

        local function onThemeChange(owner, fn)
            themeCallbacks[owner] = fn
            fn()
        end

        local function tween(inst, props, duration, easingStyle, easingDir, skipTrack)
            if not inst then return nil end
            duration = duration or 0.2
            if not skipTrack then
                trackThemeProps(inst, props)
            end
            if duration <= 0 then
                for key, val2 in pairs(props) do
                    inst[key] = val2
                end
                return nil
            end
            easingStyle = easingStyle or Enum.EasingStyle.Quart
            easingDir = easingDir or Enum.EasingDirection.Out
            local str = duration .. easingStyle.Name .. easingDir.Name
            local entry = tweenInfoCache[str]
            if not entry then
                entry = TweenInfo.new(duration, easingStyle, easingDir)
                tweenInfoCache[str] = entry
            end
            local val = TweenService:Create(inst, entry, props)
            val:Play()
            return val
        end

        local function create(className, props, children)
            local inst = Instance.new(className)
            for key, val in pairs(props) do
                if key ~= 'Parent' then
                    inst[key] = val
                end
            end
            trackThemeProps(inst, props)
            if children then
                for idx, item in ipairs(children) do
                    item.Parent = inst
                end
            end
            if props.Parent then
                inst.Parent = props.Parent
            end
            return inst
        end

        local SHIMMER_PERIOD = 2.4
        local globalShimmerConnection = nil

        local function ensureGlobalShimmer()
            if globalShimmerConnection then return end
            globalShimmerConnection = RunService.Heartbeat:Connect(function()
                if not Library.Shimmer or not Library.AccentGradient then
                    return
                end
                local t = os.clock()
                local phase = math.sin(t * (math.pi / SHIMMER_PERIOD)) * 0.5
                local offsetVec = Vector2.new(phase, 0)
                local list = Library._accentGradients
                for i = #list, 1, -1 do
                    local ctrl = list[i]
                    local g = ctrl.Gradient
                    if not g or not g.Parent then
                        table.remove(list, i)
                    elseif g.Enabled and ctrl.Active then
                        g.Offset = offsetVec
                    end
                end
            end)
        end

        function Library:GetAccentGradientColorSequence()
            local accent = Library.Theme.Accent or Color3.fromRGB(250, 250, 250)
            local accent2 = Library.Theme.Accent2 or Library.Theme.Muted or Color3.fromRGB(130, 130, 130)
            if self.Shimmer then
                return ColorSequence.new({
                    ColorSequenceKeypoint.new(0.0, accent),
                    ColorSequenceKeypoint.new(0.5, accent2),
                    ColorSequenceKeypoint.new(1.0, accent),
                })
            else
                return ColorSequence.new(accent, accent2)
            end
        end

        local function attachAccentGradient(parent, opts)
            opts = opts or {}
            local active = opts.Active ~= false

            local gradient = create('UIGradient', {
                Name = 'AccentGradient',
                Rotation = Library.AccentAngle or 360,
                Color = Library:GetAccentGradientColorSequence(),
                Transparency = NumberSequence.new(0),
                Offset = Vector2.zero,
                Enabled = Library.AccentGradient and active,
                Parent = parent
            })

            local controller = {
                Gradient = gradient,
                Active = active,
                Parent = parent,
                Opts = opts
            }

            local function updateParentColor()
                local isGrad = Library.AccentGradient and controller.Active
                if isGrad then
                    if parent:IsA('ImageLabel') then
                        parent.ImageColor3 = Color3.new(1, 1, 1)
                    elseif parent:IsA('GuiObject') then
                        parent.BackgroundColor3 = Color3.new(1, 1, 1)
                    end
                else
                    if parent:IsA('ImageLabel') then
                        local iconActive = parent:GetAttribute('IconActive')
                        local col
                        if iconActive ~= nil then
                            col = iconActive and (Library.Theme.Text or opts.FallbackColor or Library.Theme.Accent) or (Library.Theme.Muted or Color3.fromRGB(130, 130, 130))
                        else
                            col = opts.ThemeKey and Library.Theme[opts.ThemeKey] or opts.FallbackColor or Library.Theme.Accent
                        end
                        parent.ImageColor3 = col
                    elseif parent:IsA('GuiObject') then
                        local themeColor
                        if controller.Active then
                            themeColor = opts.ThemeKey and Library.Theme[opts.ThemeKey] or opts.FallbackColor or Library.Theme.Accent
                        else
                            themeColor = opts.InactiveThemeKey and Library.Theme[opts.InactiveThemeKey] or opts.InactiveColor or (Library.Theme.StrokeHover or Color3.fromRGB(50, 50, 50))
                        end
                        parent.BackgroundColor3 = themeColor
                    end
                end
            end

            function controller:SetActive(state, skipColor)
                controller.Active = state and true or false
                gradient.Enabled = Library.AccentGradient and controller.Active
                if not skipColor then
                    updateParentColor()
                end
                if not controller.Active or not Library.Shimmer then
                    gradient.Offset = Vector2.zero
                end
            end

            function controller:Update()
                if not parent.Parent then
                    controller:Destroy()
                    return
                end
                gradient.Rotation = Library.AccentAngle or 360
                gradient.Color = Library:GetAccentGradientColorSequence()
                gradient.Enabled = Library.AccentGradient and controller.Active
                if not Library.Shimmer or not controller.Active or not Library.AccentGradient then
                    gradient.Offset = Vector2.zero
                end
                updateParentColor()
            end

            function controller:Destroy()
                local idx = table.find(Library._accentGradients, controller)
                if idx then
                    table.remove(Library._accentGradients, idx)
                end
                if Library._accentGradControllers[parent] == controller then
                    Library._accentGradControllers[parent] = nil
                end
                pcall(function() gradient:Destroy() end)
            end

            parent.Destroying:Connect(function()
                controller:Destroy()
            end)

            Library._accentGradControllers[parent] = controller
            table.insert(Library._accentGradients, controller)
            ensureGlobalShimmer()
            updateParentColor()

            return controller
        end
        Library.AttachAccentGradient = attachAccentGradient

        function Library:SetAccentGradient(enabled)
            self.AccentGradient = enabled and true or false
            for _, grad in ipairs(self._accentGradients) do
                if not self.AccentGradient and grad.Gradient then
                    grad.Gradient.Offset = Vector2.zero
                end
                grad:Update()
            end
        end

        function Library:SetAccentAngle(angle)
            self.AccentAngle = tonumber(angle) or 360
            for _, grad in ipairs(self._accentGradients) do
                grad:Update()
            end
        end

        function Library:SetShimmer(enabled)
            self.Shimmer = enabled and true or false
            for _, grad in ipairs(self._accentGradients) do
                if not self.Shimmer and grad.Gradient then
                    grad.Gradient.Offset = Vector2.zero
                end
                grad:Update()
            end
        end

        Library.Roundness = 1
        Library._cornerBases = {}

        local function addCorner(parent, radius)
            radius = radius or UDim.new(0, 8)
            local uiCorner = create('UICorner', {
                CornerRadius = radius.Scale == 0 and UDim.new(0, math.floor(radius.Offset * Library.Roundness + 0.5)) or radius,
                Parent = parent
            })
            if radius.Scale == 0 then
                Library._cornerBases[uiCorner] = radius.Offset
            end
            return uiCorner
        end

        function Library._fixedCorner(param, param2)
            return create('UICorner', { CornerRadius = param2, Parent = param })
        end

        function Library._radius(param)
            return math.floor(param * Library.Roundness + 0.5)
        end

        local function addStroke(parent, color, transparency, thickness)
            return create('UIStroke', {
                Color = color or Theme.Stroke,
                Transparency = transparency or 0,
                Thickness = thickness or 1,
                ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                Parent = parent
            })
        end

        local function addPadding(parent, left, right, top, bottom)
            return create('UIPadding', {
                PaddingLeft = UDim.new(0, left or 0),
                PaddingRight = UDim.new(0, right or 0),
                PaddingTop = UDim.new(0, top or 0),
                PaddingBottom = UDim.new(0, bottom or 0),
                Parent = parent
            })
        end

        local function createLabel(props)
            local tbl = {
                BackgroundTransparency = 1,
                TextColor3 = Theme.Text,
                TextSize = 14,
                FontFace = Fonts.Medium,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextYAlignment = Enum.TextYAlignment.Center,
                TextTruncate = Enum.TextTruncate.AtEnd
            }
            for key, val in pairs(props) do
                tbl[key] = val
            end
            return create('TextLabel', tbl)
        end

        local function createGlow(parent, size, pos, transparency, zIndex)
            local imageLabel = create('ImageLabel', {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = pos,
                Size = size,
                BackgroundTransparency = 1,
                Image = Assets.Glow,
                ImageColor3 = Color3.fromRGB(226, 218, 230),
                ImageTransparency = 1,
                Visible = false,
                ZIndex = 0,
                Parent = parent
            })
            local uiGradient = create('UIGradient', { Rotation = zIndex or 90, Parent = imageLabel })
            onThemeChange(uiGradient, function()
                uiGradient.Color = ColorSequence.new(Color3.fromRGB(255, 255, 255), Theme.Accent)
            end)
            return imageLabel
        end

        local function createTopHighlight(parent)
            return create('Frame', {
                Position = UDim2.fromOffset(0, 0),
                Size = UDim2.new(1, 0, 0, 1),
                BackgroundColor3 = Color3.new(1, 1, 1),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ZIndex = 0,
                Parent = parent
            })
        end

        local TRANSPARENT_MULTIPLIER = 1.35

        local function applyIcon(img, icon, tintColor)
            local iconImage, rectOffset, rectSize, isAsset, shouldTint = resolveIcon(icon)
            if not iconImage then
                return
            end
            img.Image = iconImage
            img.ImageRectOffset = rectOffset or Vector2.zero
            img.ImageRectSize = rectSize or Vector2.zero
            if icon == Assets.Logo or icon == 'logo' or icon == 'awalogo' or icon == 'awa' or icon == 'iggylogo' or icon == 'iggy' then
                shouldTint = false
            end
            if img:GetAttribute('ContrastIcon') or tintColor == 'Contrast' then
                img:SetAttribute('ContrastIcon', true)
                local existing = img:FindFirstChild('AccentGradient')
                if existing then
                    existing.Enabled = false
                end
                local ctrl = Library._accentGradControllers[img]
                if ctrl then
                    ctrl:Destroy()
                end
                img.ImageColor3 = getAccentContrastColor(Theme.Accent)
                return
            end
            local isCustom = (isAsset and not shouldTint) or icon == Assets.Logo or icon == 'logo' or icon == 'awalogo' or icon == 'awa' or icon == 'iggylogo' or icon == 'iggy'
            img:SetAttribute('CustomIcon', isCustom or nil)
            if isCustom then
                local existing = img:FindFirstChild('AccentGradient')
                if existing then
                    existing.Enabled = false
                end
                local ctrl = Library._accentGradControllers[img]
                if ctrl then
                    ctrl:Destroy()
                end
                tween(img, { ImageColor3 = Color3.new(1, 1, 1) }, 0)
            else
                local ctrl = Library._accentGradControllers[img]
                if not ctrl then
                    ctrl = attachAccentGradient(img, {
                        Active = true,
                        ThemeKey = 'Accent',
                        FallbackColor = tintColor or Theme.Accent
                    })
                else
                    ctrl.Opts.FallbackColor = tintColor or Theme.Accent
                    ctrl:Update()
                end
            end
            local num = isAsset and not tintColor and icon ~= Assets.Logo and icon ~= 'discord' and (typeof(icon) == 'table' and tonumber(icon.Scale) or TRANSPARENT_MULTIPLIER) or 1
            local val = img:FindFirstChild('CustomIconScale')
            if num ~= 1 then
                val = val or create('UIScale', { Name = 'CustomIconScale', Parent = img })
                val.Scale = num
            elseif val then
                val:Destroy()
            end
        end

        local function tweenIconColor(img, color, active, duration)
            img:SetAttribute('IconActive', active and true or false)
            if img:GetAttribute('CustomIcon') then
                tween(img, { ImageTransparency = active and 0 or 0.4 }, duration)
            else
                if Library.AccentGradient then
                    tween(img, { ImageColor3 = Color3.new(1, 1, 1), ImageTransparency = active and 0 or 0.45 }, duration)
                else
                    tween(img, { ImageColor3 = color, ImageTransparency = 0 }, duration)
                end
            end
        end

        local function getGuiParent()
            local val
            pcall(function()
                if typeof(gethui) == 'function' then
                    val = gethui()
                end
            end)
            if typeof(val) == 'Instance' then
                return val
            end
            local val2
            pcall(function()
                val2 = game:GetService('CoreGui')
                local folder = Instance.new('Folder')
                folder.Parent = val2
                folder:Destroy()
            end)
            if val2 then
                return val2
            end
            return LocalPlayer:WaitForChild('PlayerGui')
        end

        local lastInsetTime, cachedGuiInset = nil, Vector2.zero

        local function getMousePos()
            local now = time()
            if lastInsetTime ~= now then
                lastInsetTime = now
                cachedGuiInset = GuiService:GetGuiInset()
            end
            return UserInputService:GetMouseLocation() - cachedGuiInset
        end

        local function isPrimaryPress(input)
            return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
        end

        local function isLastInputTouch()
            return UserInputService:GetLastInputType() == Enum.UserInputType.Touch
        end

        local function makeTapGuard(guiObj, getScroller)
            local canvasposition
            guiObj.InputBegan:Connect(function(input)
                if isPrimaryPress(input) then
                    local val = getScroller()
                    canvasposition = val and val.CanvasPosition
                end
            end)
            return function()
                local val = getScroller()
                return not (canvasposition and val and (val.CanvasPosition - canvasposition).Magnitude > 4)
            end
        end

        local function isPointInGui(pt, guiObj)
            local absoluteposition, absolutesize = guiObj.AbsolutePosition, guiObj.AbsoluteSize
            return pt.X >= absoluteposition.X and pt.X <= absoluteposition.X + absolutesize.X and pt.Y >= absoluteposition.Y and pt.Y <= absoluteposition.Y + absolutesize.Y
        end

        local function isPointerMove(input)
            return input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch
        end

        local ZOOM_SINK_ACTION = 'IggyUi_BlockCameraZoom'
        local zoomSinkBound = false

        local function isPointerOverAnyWindow()
            local mousePos = getMousePos()
            for idx = 1, #Library.Windows do
                local win = Library.Windows[idx]
                if win and not win._destroyed and win.Open and win.Root and win.Root.Visible and not win.Minimized then
                    if win.Body and isPointInGui(mousePos, win.Body) then
                        return true
                    end
                    if win._dialog and isPointInGui(mousePos, win._dialog) then
                        return true
                    end
                    if win._popouts then
                        for _, popout in ipairs(win._popouts) do
                            if popout and popout.Visible and isPointInGui(mousePos, popout) then
                                return true
                            end
                        end
                    end
                end
            end
            return false
        end

        local function updateZoomSinkState()
            local shouldBind = false
            for idx = 1, #Library.Windows do
                local win = Library.Windows[idx]
                if win and not win._destroyed and win.Open and win.Root and win.Root.Visible and not win.Minimized then
                    shouldBind = true
                    break
                end
            end

            if shouldBind and not zoomSinkBound then
                zoomSinkBound = true
                pcall(function()
                    ContextActionService:BindActionAtPriority(
                        ZOOM_SINK_ACTION,
                        function(actionName, inputState, inputObject)
                            if inputObject.UserInputType == Enum.UserInputType.MouseWheel then
                                if isPointerOverAnyWindow() then
                                    return Enum.ContextActionResult.Sink
                                end
                            end
                            return Enum.ContextActionResult.Pass
                        end,
                        false,
                        Enum.ContextActionPriority.High.Value,
                        Enum.UserInputType.MouseWheel
                    )
                end)
            elseif not shouldBind and zoomSinkBound then
                zoomSinkBound = false
                pcall(function()
                    ContextActionService:UnbindAction(ZOOM_SINK_ACTION)
                end)
            end
        end

        local function createIcon(parent, icon, color, pos)
            local frame = create('Frame', {
                AnchorPoint = Vector2.new(0, 0.5),
                Position = pos,
                Size = UDim2.fromOffset(16, 16),
                BackgroundTransparency = 1,
                Parent = parent
            })
            local imageLabel = create('ImageLabel', {
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                ImageColor3 = color,
                ScaleType = Enum.ScaleType.Fit,
                Parent = frame
            })
            applyIcon(imageLabel, icon)
            return frame, imageLabel
        end

        local function createChevron(parent, anchorX, offsetX)
            local frame = create('Frame', {
                AnchorPoint = Vector2.new(anchorX, 0.5),
                Position = UDim2.new(anchorX, offsetX, 0.5, 0),
                Size = UDim2.fromOffset(18, 18),
                BackgroundTransparency = 1,
                Parent = parent
            })
            local tbl = {}
            local imageLabel = create('ImageLabel', {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromOffset(16, 16),
                BackgroundTransparency = 1,
                ImageColor3 = Theme.Muted,
                ScaleType = Enum.ScaleType.Fit,
                Parent = frame
            })
            applyIcon(imageLabel, 'chevron-down')
            if imageLabel.Image ~= '' then
                function tbl:Set(value)
                    tween(imageLabel, {
                        Rotation = value and 180 or 0,
                        ImageColor3 = value and Theme.Accent or Theme.Muted
                    }, 0.3, Enum.EasingStyle.Quint)
                end

                return tbl
            end
            imageLabel:Destroy()

            local function helperFn(param, param2)
                return createLabel({
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.fromOffset(18, 18),
                    Text = '\u{203a}',
                    TextSize = 22,
                    TextXAlignment = Enum.TextXAlignment.Center,
                    TextColor3 = Theme.Muted,
                    TextTransparency = param2,
                    Rotation = param,
                    Parent = frame
                })
            end

            local val = helperFn(90, 0)
            local val2 = helperFn(270, 1)

            function tbl:Set(value)
                tween(val, { TextTransparency = value and 1 or 0 }, 0.2)
                tween(val2, {
                    TextTransparency = value and 0 or 1,
                    TextColor3 = value and Theme.Accent or Theme.Muted
                }, 0.2)
            end

            return tbl
        end

        local ripplePool = {}

        local function spawnRipple(targetGui)
            local mousePos = getMousePos()
            local num = math.max(targetGui.AbsoluteSize.X, targetGui.AbsoluteSize.Y) * 2.2
            local removed = table.remove(ripplePool)
            if removed and not pcall(function()
                removed.Parent = nil
            end) then
                removed = nil
            end
            if not removed then
                removed = create('Frame', {
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    BackgroundColor3 = Theme.Accent,
                    BorderSizePixel = 0
                })
                addCorner(removed, UDim.new(1, 0))
            end
            removed.Position = UDim2.fromOffset(mousePos.X - targetGui.AbsolutePosition.X, mousePos.Y - targetGui.AbsolutePosition.Y)
            removed.Size = UDim2.fromOffset(0, 0)
            removed.BackgroundColor3 = Theme.Accent
            removed.BackgroundTransparency = 0.82
            removed.ZIndex = targetGui.ZIndex + 1
            removed.Parent = targetGui
            tween(removed, { Size = UDim2.fromOffset(num, num), BackgroundTransparency = 1 }, 0.55)
            task.delay(0.55, function()
                if removed.Parent ~= targetGui or not targetGui.Parent then
                    pcall(removed.Destroy, removed)
                    return
                end
                removed.Parent = nil
                if #ripplePool < 4 then
                    table.insert(ripplePool, removed)
                else
                    removed:Destroy()
                end
            end)
        end

        local function flashStroke(uiStroke)
            -- Disabled: row cards do not flash or show outline/stroke
        end

        local function bindHoverStroke(guiObj, uiStroke)
            -- Disabled: row cards and setting options do not show outline/stroke on hover
        end

        local KEYCODE_NAMES = {
            [Enum.KeyCode.LeftControl] = 'LCtrl',
            [Enum.KeyCode.RightControl] = 'RCtrl',
            [Enum.KeyCode.LeftShift] = 'LShift',
            [Enum.KeyCode.RightShift] = 'RShift',
            [Enum.KeyCode.LeftAlt] = 'LAlt',
            [Enum.KeyCode.RightAlt] = 'RAlt',
            [Enum.KeyCode.Return] = 'Enter',
            [Enum.KeyCode.Escape] = 'Esc',
            [Enum.KeyCode.Backspace] = 'Backspace'
        }

        local function formatKeyCode(keyCode)
            if keyCode == nil then
                return 'None'
            end
            if type(keyCode) == 'string' then
                return keyCode
            end
            return KEYCODE_NAMES[keyCode] or (typeof(keyCode) == 'EnumItem' and keyCode.Name) or tostring(keyCode)
        end

        local function safeCall(callback, ...)
            if type(callback) ~= 'function' then
                return
            end
            local ok, res = pcall(callback, ...)
            if not ok then
                warn('[IggyUiFork] callback error: ' .. tostring(res))
            end
        end

        local function awaitCall(fn)
            local val = nil
            task.spawn(function()
                val = table.pack(pcall(fn))
            end)
            while val == nil do
                task.wait()
            end
            return table.unpack(val, 1, val.n)
        end

        local function makeStepper(minVal, maxVal, stepVal)
            local num = 0
            local str = tostring(stepVal)
            local val = str:find('%.')
            if val then
                num = #str - val
            end
            local str2 = '%.' .. num .. 'f'
            return {
                snap = function(value)
                    value = math.floor(value / stepVal + 0.5) * stepVal
                    return math.clamp(value, minVal, maxVal)
                end,
                format = function(value)
                    return string.format(str2, value)
                end
            }
        end

        local function getMetrics(container)
            return container._metrics or DENSITY_METRICS.Card
        end

        local function calcControlWidth(rowFrame, uiScale)
            local num = rowFrame.AbsoluteSize.X / uiScale.Scale.Scale
            return math.clamp(math.floor(num * 0.48), 90, 220)
        end

        local function createElementCard(container, className, height, opts)
            local compact = getMetrics(container).Compact
            local order = container:_nextOrder()
            local tbl = {
                Size = UDim2.new(1, 0, 0, height),
                BackgroundColor3 = Theme.Recessed or rgb(25, 28, 32),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                LayoutOrder = order,
                Parent = container.List
            }
            if className == 'TextButton' then
                tbl.AutoButtonColor = false
                tbl.Text = ''
            end
            local inst = create(className, tbl)
            inst:SetAttribute('NoDrag', true)
            addCorner(inst, UDim.new(0, 8))
            local stroke = addStroke(inst, Theme.Stroke, 1)
            stroke.Enabled = false
            return inst, stroke
        end

        local function createTitleAndDesc(parent, titleText, descText, rightReserve, metrics)
            metrics = metrics or DENSITY_METRICS.Row
            local label, label2
            if descText then
                label = createLabel({
                    Position = UDim2.fromOffset(8, 6),
                    Size = UDim2.new(1, -(8 + rightReserve), 0, 16),
                    Text = titleText,
                    TextSize = 13,
                    FontFace = Fonts.Medium,
                    TextColor3 = Theme.Text,
                    Parent = parent
                })
                label2 = createLabel({
                    Position = UDim2.fromOffset(8, 24),
                    Size = UDim2.new(1, -(8 + rightReserve), 0, 14),
                    Text = descText,
                    TextSize = 11,
                    FontFace = Fonts.Regular,
                    TextColor3 = Theme.Muted,
                    Parent = parent
                })
            else
                label = createLabel({
                    AnchorPoint = Vector2.new(0, 0.5),
                    Position = UDim2.new(0, 8, 0.5, 0),
                    Size = UDim2.new(1, -(8 + rightReserve), 0, 18),
                    Text = titleText,
                    TextSize = 13,
                    FontFace = Fonts.Regular,
                    TextColor3 = Theme.Text,
                    Parent = parent
                })
            end
            return label, label2
        end

        local function buildElementRow(container, opts, aliases, className, rightReserve, defaultTitle)
            opts = normalizeOpts(opts, aliases)
            local metrics = getMetrics(container)
            local descheight = opts.Desc and metrics.DescHeight or metrics.Height
            local card, cardStroke = createElementCard(container, className or 'Frame', descheight, opts)
            bindHoverStroke(card, cardStroke)
            local titleLabel, descLabel
            if rightReserve then
                titleLabel, descLabel = createTitleAndDesc(card, opts.Name or defaultTitle, opts.Desc, rightReserve, metrics)
            end
            return opts, card, cardStroke, descheight, titleLabel, descLabel
        end

        local function resizeRowLabels(titleLabel, descLabel, rightReserve)
            if titleLabel then
                titleLabel.Size = UDim2.new(1, -(8 + rightReserve), titleLabel.Size.Y.Scale, titleLabel.Size.Y.Offset)
            end
            if descLabel then
                descLabel.Size = UDim2.new(1, -(8 + rightReserve), 0, descLabel.Size.Y.Offset)
            end
        end

        local Container = {}
        Container.__index = Container

        function Container:_nextOrder()
            self._order = self._order + 1
            return self._order
        end

        function Container:Section(opts)
            local isFalse = not (type(opts) == 'table' and opts.Visible == false)

            if type(opts) == 'table' then
                opts = opts.Name or opts.Title or ''
            end

            local num = getMetrics(self).Compact and 14 or 2

            local frame = create('Frame', {
                Size = UDim2.new(1, 0, 0, 28),
                BackgroundTransparency = 1,
                LayoutOrder = self:_nextOrder(),
                Parent = self.List
            })

            local label = createLabel({
                Position = UDim2.fromOffset(num, 8),
                Size = UDim2.new(0, 0, 0, 16),
                AutomaticSize = Enum.AutomaticSize.X,
                Text = string.upper(opts),
                TextSize = 12,
                TextColor3 = Theme.Muted,
                TextTruncate = Enum.TextTruncate.None,
                Parent = frame
            })

            local num2 = num == 2 and 0 or num

            local frame2 = create('Frame', {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -num2, 0, 16),
                Size = UDim2.new(1, -12, 0, 1),
                BackgroundColor3 = Theme.Stroke,
                BorderSizePixel = 0,
                Parent = frame
            })

            local function helperFn()
                frame2.Size = UDim2.new(1, -(label.AbsoluteSize.X / self.Window.Scale.Scale + num + 12 + num2), 0, 1)
            end

            label:GetPropertyChangedSignal('AbsoluteSize'):Connect(helperFn)
            task.defer(helperFn)

            return registerElement(self, { Visible = isFalse }, {
                Set = function(selfArg, value)
                    label.Text = string.upper(value)
                end
            }, frame, 'Section')
        end

        function Container:Divider(opts)
            local text = type(opts) == 'table' and (opts.Text or opts.Name) or type(opts) == 'string' and opts or nil

            if text then
                local num = getMetrics(self).Compact and 14 or 2
                local frame2 = create('Frame', {
                    Size = UDim2.new(1, 0, 0, 18),
                    BackgroundTransparency = 1,
                    LayoutOrder = self:_nextOrder(),
                    Parent = self.List
                })
                local label = createLabel({
                    AnchorPoint = Vector2.new(0.5, 0.5),
                    Position = UDim2.fromScale(0.5, 0.5),
                    Size = UDim2.new(0, 0, 0, 14),
                    AutomaticSize = Enum.AutomaticSize.X,
                    Text = text,
                    TextSize = 12,
                    FontFace = Fonts.Regular,
                    TextColor3 = Theme.Muted,
                    TextTruncate = Enum.TextTruncate.None,
                    Parent = frame2
                })
                addPadding(label, 8, 8)
                local tbl = {}
                for idx, item in ipairs({ 0, 1 }) do
                    tbl[idx] = create('Frame', {
                        AnchorPoint = Vector2.new(item, 0.5),
                        Position = UDim2.new(item, item == 0 and num or -num, 0.5, 0),
                        Size = UDim2.new(0.5, -num, 0, 1),
                        BackgroundColor3 = Theme.Outline,
                        BorderSizePixel = 0,
                        Parent = frame2
                    })
                    bindTheme(tbl[idx], 'BackgroundColor3', 'Outline')
                end

                local function helperFn()
                    local num2 = label.AbsoluteSize.X / self.Window.Scale.Scale / 2
                    for idx, item in ipairs(tbl) do
                        item.Size = UDim2.new(0.5, -(num + num2), 0, 1)
                    end
                end

                label:GetPropertyChangedSignal('AbsoluteSize'):Connect(helperFn)
                task.defer(helperFn)
                return registerElement(self, { Visible = not (type(opts) == 'table' and opts.Visible == false) }, {
                    Set = function(selfArg, value)
                        label.Text = tostring(value)
                    end
                }, frame2, 'Divider')
            end

            local frame = create('Frame', {
                Size = UDim2.new(1, 0, 0, 1),
                BackgroundColor3 = Theme.Outline,
                BorderSizePixel = 0,
                LayoutOrder = self:_nextOrder(),
                Parent = self.List
            })
            bindTheme(frame, 'BackgroundColor3', 'Outline')

            if getMetrics(self).Compact then
                frame.BackgroundTransparency = 1
                frame.Size = UDim2.new(1, 0, 0, 13)
                local compactLine = create('Frame', {
                    Position = UDim2.fromOffset(0, 6),
                    Size = UDim2.new(1, 0, 0, 1),
                    BackgroundColor3 = Theme.Outline,
                    BorderSizePixel = 0,
                    Parent = frame
                })
                bindTheme(compactLine, 'BackgroundColor3', 'Outline')
            end

            return registerElement(self, { Visible = not (type(opts) == 'table' and opts.Visible == false) }, {}, frame, 'Divider')
        end

        function Container:Label(opts)
            opts = normalizeOpts(opts, { Name = 'Text', Title = 'Text' })

            local label = createLabel({
                Size = UDim2.new(1, 0, 0, 18),
                AutomaticSize = Enum.AutomaticSize.Y,
                Text = Library._rich(opts.Text or ''),
                TextSize = 14,
                FontFace = Fonts.Regular,
                TextColor3 = Library._color(opts.Color) or Theme.Text,
                TextWrapped = true,
                TextTruncate = Enum.TextTruncate.None,
                RichText = true,
                LayoutOrder = self:_nextOrder(),
                Parent = self.List
            })

            if getMetrics(self).Compact then
                addPadding(label, 14, 14)
            else
                addPadding(label, 2, 2)
            end

            local elem = {
                Set = function(selfArg, value)
                    label.Text = Library._rich(value)
                end,
                Get = function()
                    return label.Text
                end,
                SetColor = function(selfArg, value)
                    tween(label, { TextColor3 = Library._color(value) or Theme.Text }, 0.25)
                end
            }

            if type(opts.Update) == 'function' then
                local num = math.max(tonumber(opts.UpdateRate) or 1, 0.05)
                local flag = true
                elem._listeners = elem._listeners or {}
                table.insert(elem._listeners, function()
                    flag = false
                end)
                task.spawn(function()
                    while flag and label.Parent do
                        local ok, res = awaitCall(opts.Update)
                        if ok and res ~= nil then
                            label.Text = Library._rich(res)
                        elseif not ok then
                            warn('[IggyUiFork] label update error: ' .. tostring(res))
                        end
                        task.wait(num)
                    end
                end)

                function elem:SetUpdateRate(value)
                    num = math.max(tonumber(value) or num, 0.05)
                end
            end

            return registerElement(self, opts, elem, label, 'Label')
        end

        function Container:Paragraph(opts)
            opts = normalizeOpts(opts, { Title = 'Name' })
            local card = createElementCard(self, 'Frame', 0, opts)
            card.AutomaticSize = Enum.AutomaticSize.Y
            card.BackgroundColor3 = Theme.Recessed or rgb(25, 28, 32)
            card.BackgroundTransparency = 0
            addCorner(card, UDim.new(0, 9))
            addStroke(card, Theme.Stroke, 1)
            addPadding(card, 12, 12, 10, 10)

            create('UIListLayout', {
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 4),
                Parent = card
            })

            if opts.Name and opts.Name ~= '' then
                createLabel({
                    Size = UDim2.new(1, 0, 0, 16),
                    Text = opts.Name,
                    TextSize = 12,
                    FontFace = Fonts.SemiBold,
                    TextColor3 = Theme.Text,
                    LayoutOrder = 1,
                    Parent = card
                })
            end

            local label = createLabel({
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                Text = Library._rich(opts.Content or ''),
                TextSize = 11,
                FontFace = Fonts.Regular,
                TextColor3 = Theme.Muted,
                TextWrapped = true,
                TextTruncate = Enum.TextTruncate.None,
                TextYAlignment = Enum.TextYAlignment.Top,
                RichText = true,
                LayoutOrder = 2,
                Parent = card
            })

            return registerElement(self, opts, {
                Set = function(selfArg, value)
                    label.Text = Library._rich(value)
                end
            }, card, 'Paragraph')
        end

        local function buildSingleButton(container, opts)
            local cond = opts.Style == 'Primary'
            local num = isTouch and 34 or 30
            local num2 = num + 12 + (opts.Desc and 18 or 0)
            local card = createElementCard(container, 'TextButton', num2, opts)
            local frame = create('Frame', {
                Position = UDim2.fromOffset(14, 6),
                Size = UDim2.new(1, -28, 0, num),
                BackgroundColor3 = cond and Theme.Accent or Theme.Surface3,
                BackgroundTransparency = 0,
                BorderSizePixel = 0,
                ClipsDescendants = true,
                Parent = card
            })
            addCorner(frame, UDim.new(0, 8))
            local stroke = addStroke(frame, cond and Theme.Accent or Theme.Stroke, cond and 0.4 or 0, 1)
            local frame2 = create('Frame', {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.new(0, 0, 1, 0),
                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundTransparency = 1,
                Parent = frame
            })
            create('UIListLayout', {
                FillDirection = Enum.FillDirection.Horizontal,
                VerticalAlignment = Enum.VerticalAlignment.Center,
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 6),
                Parent = frame2
            })
            local accentdark = cond and Theme.AccentDark or Theme.Text
            if opts.Icon then
                local imageLabel = create('ImageLabel', {
                    Size = UDim2.fromOffset(14, 14),
                    BackgroundTransparency = 1,
                    ImageColor3 = cond and Theme.AccentDark or Theme.Accent,
                    ScaleType = Enum.ScaleType.Fit,
                    LayoutOrder = 1,
                    Parent = frame2
                })
                applyIcon(imageLabel, opts.Icon)
            end
            local label = createLabel({
                Size = UDim2.new(0, 0, 1, 0),
                AutomaticSize = Enum.AutomaticSize.X,
                Text = opts.Name or 'Button',
                TextSize = 12,
                FontFace = cond and Fonts.SemiBold or Fonts.Medium,
                TextColor3 = accentdark,
                TextTruncate = Enum.TextTruncate.None,
                LayoutOrder = 2,
                Parent = frame2
            })
            if opts.Desc then
                createLabel({
                    Position = UDim2.fromOffset(14, num + 9),
                    Size = UDim2.new(1, -28, 0, 14),
                    Text = opts.Desc,
                    TextSize = 12,
                    FontFace = Fonts.Regular,
                    TextColor3 = Theme.Muted,
                    Parent = card
                })
            end
            card.MouseEnter:Connect(function()
                if not isLastInputTouch() then
                    if cond then
                        tween(frame, { BackgroundTransparency = 0 }, 0.12)
                        tween(stroke, { Transparency = 0 }, 0.12)
                    else
                        tween(frame, { BackgroundColor3 = Theme.Surface }, 0.12)
                        tween(stroke, { Color = Theme.StrokeHover }, 0.12)
                    end
                end
            end)
            card.MouseLeave:Connect(function()
                if cond then
                    tween(frame, { BackgroundTransparency = 0 }, 0.22)
                    tween(stroke, { Transparency = 0.4 }, 0.22)
                else
                    tween(frame, { BackgroundColor3 = Theme.Surface3 }, 0.22)
                    tween(stroke, { Color = Theme.Stroke }, 0.22)
                end
            end)
            card.MouseButton1Click:Connect(function()
                spawnRipple(frame)
                safeCall(opts.Callback)
            end)
            return registerElement(container, opts, {
                _title = label,
                _titleColor = accentdark,
                _fillHost = frame,
                SetText = function(selfArg, value)
                    label.Text = value
                end
            }, card, 'Button')
        end

        function Container:Button(opts)
            opts = normalizeOpts(opts, { Title = 'Name', Description = 'Desc' })

            if (opts.Confirm or opts.HoldToConfirm) and not opts._gated then
                return Library._gateButton(self, opts)
            end

            if getMetrics(self).Compact then
                return buildSingleButton(self, opts)
            end

            local cond = opts.Style == 'Primary'
            local cond2 = opts.Desc and CARD_DESC_HEIGHT or CARD_HEIGHT
            local card, cardStroke = createElementCard(self, 'TextButton', cond2, opts)
            card.ClipsDescendants = true

            if cond then
                cardStroke.Enabled = true
                tween(card, { BackgroundColor3 = Theme.Accent, BackgroundTransparency = 0.12 }, 0)
                tween(cardStroke, { Color = Theme.Accent }, 0)
                cardStroke.Transparency = 0.4
                card.MouseEnter:Connect(function()
                    tween(card, { BackgroundTransparency = 0 }, 0.12)
                    tween(cardStroke, { Transparency = 0 }, 0.12)
                end)
                card.MouseLeave:Connect(function()
                    tween(card, { BackgroundTransparency = 0.12 }, 0.25)
                    tween(cardStroke, { Transparency = 0.4 }, 0.25)
                end)
            else
                cardStroke.Enabled = true
                cardStroke.Transparency = 0
                cardStroke.Color = Theme.Stroke
                card.MouseEnter:Connect(function()
                    tween(cardStroke, { Color = Theme.StrokeHover }, 0.12)
                end)
                card.MouseLeave:Connect(function()
                    tween(cardStroke, { Color = Theme.Stroke }, 0.25)
                end)
            end

            local accentdark = cond and Theme.AccentDark or Theme.Text
            local num = 0

            if opts.Icon then
                createIcon(card, opts.Icon, cond and Theme.AccentDark or Theme.Accent, UDim2.new(0, 14, 0.5, 0))
                num = 26
            end

            local titleLabel = createTitleAndDesc(card, opts.Name or 'Button', opts.Desc, 30)

            if num > 0 then
                for idx, child in ipairs(card:GetChildren()) do
                    if child:IsA('TextLabel') then
                        child.Position = child.Position + UDim2.fromOffset(num, 0)
                        child.Size = child.Size - UDim2.fromOffset(num, 0)
                    end
                end
            end

            if cond then
                for idx, child in ipairs(card:GetChildren()) do
                    if child:IsA('TextLabel') then
                        tween(child, { TextColor3 = accentdark }, 0)
                    end
                end
            end

            createIcon(card, CHEVRON_ICON, cond and Theme.AccentDark or Theme.Muted, UDim2.new(1, -30, 0.5, 0))

            card.MouseButton1Click:Connect(function()
                spawnRipple(card)
                safeCall(opts.Callback)
            end)

            return registerElement(self, opts, {
                _title = titleLabel,
                _titleColor = accentdark,
                _fillHost = card,
                SetText = function(selfArg, value)
                    titleLabel.Text = value
                end
            }, card, 'Button')
        end

        function Container:Toggle(opts)
            local rowCard, rowStroke

            opts, rowCard, rowStroke = buildElementRow(self, opts, {
                Title = 'Name',
                Description = 'Desc',
                CurrentValue = 'Default',
                Value = 'Default'
            }, 'TextButton', 48, 'Toggle')

            local pillW = 34
            local pillH = 20
            local knobSize = 16

            local frame = create('Frame', {
                AnchorPoint = Vector2.new(1, 0.5),
                Position = UDim2.new(1, -8, 0.5, 0),
                Size = UDim2.fromOffset(pillW, pillH),
                BackgroundColor3 = Theme.StrokeHover,
                BorderSizePixel = 0,
                Parent = rowCard
            })
            addCorner(frame, UDim.new(0, 10))
            local toggleStroke = addStroke(frame, Theme.Stroke, 0, 1)

            local pillGrad = attachAccentGradient(frame, { Active = opts.Default == true, ThemeKey = 'Accent' })

            local frame2 = create('Frame', {
                AnchorPoint = Vector2.new(0, 0.5),
                Position = UDim2.new(0, 2, 0.5, 0),
                Size = UDim2.fromOffset(knobSize, knobSize),
                BackgroundColor3 = (opts.Default == true and getAccentContrastColor(Theme.Accent) or Color3.fromRGB(255, 255, 255)),
                BorderSizePixel = 0,
                Parent = frame
            })
            addCorner(frame2, UDim.new(1, 0))

            local elem = { Value = opts.Default == true }

            local function helperFn(param)
                local value = elem.Value
                local dur = param and 0.12 or 0
                pillGrad:SetActive(value)
                local knobCol = value and getAccentContrastColor(Theme.Accent) or Color3.fromRGB(255, 255, 255)
                tween(frame2, {
                    Position = value and UDim2.new(0, pillW - 2 - knobSize, 0.5, 0) or UDim2.new(0, 2, 0.5, 0),
                    BackgroundColor3 = knobCol
                }, dur, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
                if param then
                    tween(frame2, { Size = UDim2.fromOffset(knobSize + 4, knobSize - 2) }, 0.08)
                    task.delay(0.08, function()
                        tween(frame2, { Size = UDim2.fromOffset(knobSize, knobSize) }, 0.2, Enum.EasingStyle.Back)
                    end)
                end
            end

            rowCard.MouseEnter:Connect(function()
                if not isLastInputTouch() then
                    tween(toggleStroke, { Color = Theme.StrokeHover }, 0.12)
                end
            end)
            rowCard.MouseLeave:Connect(function()
                tween(toggleStroke, { Color = Theme.Stroke }, 0.25)
            end)

            onThemeChange(frame, function()
                if not Library.AccentGradient or not elem.Value then
                    frame.BackgroundColor3 = elem.Value and Theme.Accent or Theme.StrokeHover
                end
                toggleStroke.Color = Theme.Stroke
                if elem.Value then
                    frame2.BackgroundColor3 = getAccentContrastColor(Theme.Accent)
                end
            end)

            local flag = false
            function elem:Set(value, silent)
                value = value == true
                if value == elem.Value then return end
                elem.Value = value
                helperFn(true)
                if not flag then flashStroke(rowStroke) end
                if not silent then safeCall(opts.Callback, value) end
            end

            function elem:Get() return elem.Value end

            rowCard.MouseButton1Click:Connect(function()
                elem:Set(not elem.Value)
            end)

            helperFn(false)



            return registerElement(self, opts, elem, rowCard, 'Toggle')
        end

        function Container:Slider(opts)
            opts = normalizeOpts(opts, {
                Title = 'Name',
                Description = 'Desc',
                CurrentValue = 'Default',
                Value = 'Default',
                Increment = 'Step'
            })

            local min = opts.Min or 0
            local max = opts.Max or 100
            local step = opts.Step or 1
            local suffix = opts.Suffix or ''
            local stepper = makeStepper(min, max, step)
            local elem = { Value = math.clamp(opts.Default or min, min, max) }
            local rowHeight = opts.Desc and 58 or 46
            local card, cardStroke = createElementCard(self, 'Frame', rowHeight, opts)
            bindHoverStroke(card, cardStroke)

            -- Row 1: Left Title + optional Desc, Right Value Text Box
            local titleY = opts.Desc and 5 or 0
            local titleLabel = createLabel({
                Position = UDim2.fromOffset(8, titleY),
                Size = UDim2.new(1, -75, 0, 16),
                Text = opts.Name or 'Slider',
                TextSize = 13,
                FontFace = Fonts.Medium,
                TextColor3 = Theme.Text,
                Parent = card
            })

            local descLabel
            if opts.Desc then
                descLabel = createLabel({
                    Position = UDim2.fromOffset(8, 22),
                    Size = UDim2.new(1, -75, 0, 14),
                    Text = opts.Desc,
                    TextSize = 11,
                    FontFace = Fonts.Regular,
                    TextColor3 = Theme.Muted,
                    Parent = card
                })
            end

            local valBox = create('Frame', {
                AnchorPoint = Vector2.new(1, 0),
                Position = UDim2.new(1, -8, 0, opts.Desc and 4 or 0),
                Size = UDim2.fromOffset(40, 22),
                BackgroundColor3 = Theme.Background,
                BorderSizePixel = 0,
                ClipsDescendants = true,
                Parent = card
            })
            addCorner(valBox, UDim.new(0, 6))
            local valBoxStroke = addStroke(valBox, Theme.Stroke, 0, 1)

            -- Display Label (shown when not editing)
            local valDisplayLabel = createLabel({
                Size = UDim2.new(1, 0, 1, 0),
                Text = stepper.format(elem.Value) .. suffix,
                TextSize = 12,
                FontFace = Fonts.SemiBold,
                TextColor3 = Theme.Accent,
                TextXAlignment = Enum.TextXAlignment.Center,
                TextTruncate = Enum.TextTruncate.None,
                ZIndex = 1,
                Parent = valBox
            })

            -- Editing container: contains TextBox and optional Suffix label
            local editBox = create('Frame', {
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                Visible = false,
                ZIndex = 2,
                Parent = valBox
            })

            local editLayout = create('UIListLayout', {
                FillDirection = Enum.FillDirection.Horizontal,
                VerticalAlignment = Enum.VerticalAlignment.Center,
                HorizontalAlignment = Enum.HorizontalAlignment.Center,
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 2),
                Parent = editBox
            })

            local valTextBox = create('TextBox', {
                Size = UDim2.fromOffset(24, 22),
                BackgroundTransparency = 1,
                Text = stepper.format(elem.Value),
                TextColor3 = Theme.Text,
                TextSize = 12,
                FontFace = Fonts.SemiBold,
                TextXAlignment = Enum.TextXAlignment.Center,
                ClearTextOnFocus = false,
                ClipsDescendants = false,
                LayoutOrder = 1,
                Parent = editBox
            })
            create('UISizeConstraint', { MinSize = Vector2.new(16, 0), Parent = valTextBox })

            local valSuffixLabel = createLabel({
                Size = UDim2.new(0, 0, 1, 0),
                AutomaticSize = Enum.AutomaticSize.X,
                Text = suffix,
                TextSize = 12,
                FontFace = Fonts.Medium,
                TextColor3 = Theme.Accent,
                TextTruncate = Enum.TextTruncate.None,
                Visible = suffix ~= '',
                LayoutOrder = 2,
                Parent = editBox
            })

            -- Full clickable overlay button for 1-click typing activation
            local valHitBtn = create('TextButton', {
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                Text = '',
                AutoButtonColor = false,
                ZIndex = 5,
                Parent = valBox
            })

            local isEditing = false

