                opts.LoadingSteps = loading.Steps or opts.LoadingSteps
                opts.LoadingTitle = loading.Title or opts.LoadingTitle
                loading = loading.Enabled ~= false
            end

            local tbl = {}
            local unsupportedexecutor = opts.UnsupportedExecutor

            if unsupportedexecutor ~= false then
                unsupportedexecutor = type(unsupportedexecutor) == 'table' and unsupportedexecutor or {}
                local supportedexecutors = opts.SupportedExecutors or (type(opts.Home) == 'table' and opts.Home.SupportedExecutors or nil)
                local executorName, isSupported, supportMsg = checkExecutorSupport({ SupportedExecutors = supportedexecutors })
                if not isSupported and not UnsupportedSkipStore.Saved(val.ConfigFolder, executorName) then
                    local cond3 = unsupportedexecutor.Block == true
                    local configfolder = val.ConfigFolder
                    table.insert(tbl, {
                        Title = unsupportedexecutor.Title or 'Unsupported executor',
                        Subtitle = executorName,
                        Text = cond3 and ((unsupportedexecutor.Text or supportMsg) .. " This script can't run here.") or (unsupportedexecutor.Text or supportMsg),
                        Icon = 'shield-alert',
                        Color = Theme.Warning,
                        ContinueText = 'Continue anyway',
                        ExitText = 'Exit',
                        Block = cond3,
                        RememberText = "Don't ask again on this executor",
                        Remember = function()
                            UnsupportedSkipStore.Save(configfolder, executorName)
                        end
                    })
                end
            end

            local disclaimer = opts.Disclaimer or opts.Disclaimers

            if type(disclaimer) == 'string' or (type(disclaimer) == 'table' and (disclaimer.Title ~= nil or disclaimer.Text ~= nil)) then
                disclaimer = { disclaimer }
            end

            if type(disclaimer) == 'table' then
                for idx, item in ipairs(disclaimer) do
                    if type(item) == 'string' then
                        item = { Text = item }
                    end
                    if type(item) == 'table' then
                        local val4 = UnsupportedSkipStore.DisclaimerKey(item)
                        local configfolder = val.ConfigFolder
                        local cond3 = item.Block == true
                        local isFalse = item.Remember ~= false and not cond3
                        if not (isFalse and UnsupportedSkipStore.DisclaimerAccepted(configfolder, val4)) then
                            local callback = item.Callback
                            table.insert(tbl, {
                                Title = item.Title or 'Disclaimer',
                                Subtitle = item.Subtitle,
                                Text = item.Text or '',
                                Icon = item.Icon or 'info',
                                Color = item.Color or Theme.Accent,
                                ContinueText = item.AcceptText or 'I understand',
                                ExitText = item.DeclineText == nil and 'Exit' or item.DeclineText,
                                RememberText = isFalse and (item.RememberText or "Don't show again") or nil,
                                Remember = function()
                                    UnsupportedSkipStore.AcceptDisclaimer(configfolder, val4)
                                end,
                                Callback = type(callback) == 'function' and callback or nil,
                                Block = cond3
                            })
                        end
                    end
                end
            end

            if #tbl > 0 then
                opts._prompts = tbl
            end

            if loading == false and opts._prompts then
                opts.LoadingDuration = opts.LoadingDuration or 0.5
                loading = true
            end

            if loading == false then
                task.defer(function()
                    val:_playIntro()
                end)
            else
                val:_showLoader(opts)
            end

            return val
        end

        Library.CreateWindow = Library.Window

        function Library:Notify(opts)
            local win = Library.Windows[#Library.Windows]

            if win then
                return win:Notify(opts)
            end
        end

        function Library:Confirm(param)
            local win = Library.Windows[#Library.Windows]

            if win then
                return win:Confirm(param)
            end
        end

        function Library:Dialog(opts)
            local win = Library.Windows[#Library.Windows]

            if win then
                return win:Dialog(opts)
            end
        end

        local function isGuiVisibleInAncestors(guiObj, stopAt, checkBounds)
            local val = guiObj
            while val and val ~= stopAt and val:IsA('GuiObject') do
                if not val.Visible then
                    return false
                end
                local parent = val.Parent
                if parent and parent ~= stopAt and parent:IsA('GuiObject') and (parent.ClipsDescendants or parent:IsA('ScrollingFrame')) and not isPointInGui(checkBounds, parent) then
                    return false
                end
                val = parent
            end
            return true
        end

        function Window:_refreshControls()
            local tbl = {}

            for idx, child in ipairs(self.Body:GetDescendants()) do
                if child:IsA('GuiButton') or child:IsA('TextBox') or child:GetAttribute('NoDrag') then
                    table.insert(tbl, child)
                end
            end

            self._controls = tbl
            self._controlsDirty = false
        end

        function Window:_overControl(param)
            if self._dialog or self:_overPopout(param) then
                return true
            end

            if self._controlsDirty then
                self:_refreshControls()
            end

            for idx, item in ipairs(self._controls) do
                if item.Parent and isPointInGui(param, item) and isGuiVisibleInAncestors(item, self.Body, param) then
                    return true
                end
            end

            return false
        end

        function Window:_tooltipCard()
            if self._tip then
                return self._tip
            end

            local tooltip = create('CanvasGroup', {
                Name = 'Tooltip',
                Size = UDim2.fromOffset(0, 0),
                BackgroundTransparency = 1,
                GroupTransparency = 1,
                Visible = false,
                ZIndex = 60,
                Parent = self.Gui
            })

            local uiScale = create('UIScale', { Parent = tooltip })
            local num = 4

            local frame = create('Frame', {
                Position = UDim2.fromOffset(num, num),
                Size = UDim2.fromOffset(0, 0),
                AutomaticSize = Enum.AutomaticSize.XY,
                BackgroundTransparency = 1,
                Parent = tooltip
            })

            create('UIListLayout', {
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 2),
                Parent = frame
            })

            local function helperFn(param)
                create('UIStroke', {
                    Color = Color3.new(0, 0, 0),
                    Transparency = 0.35,
                    Thickness = 1,
                    ApplyStrokeMode = Enum.ApplyStrokeMode.Contextual,
                    Parent = param
                })
            end

            local frame2 = create('Frame', {
                Size = UDim2.fromOffset(0, 18),
                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundTransparency = 1,
                LayoutOrder = 1,
                Parent = frame
            })

            create('UIListLayout', {
                FillDirection = Enum.FillDirection.Horizontal,
                VerticalAlignment = Enum.VerticalAlignment.Center,
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 6),
                Parent = frame2
            })

            local imageLabel = create('ImageLabel', {
                Size = UDim2.fromOffset(14, 14),
                BackgroundTransparency = 1,
                ImageColor3 = Theme.Accent,
                ScaleType = Enum.ScaleType.Fit,
                LayoutOrder = 1,
                Parent = frame2
            })

            local label = createLabel({
                Size = UDim2.fromOffset(0, 18),
                AutomaticSize = Enum.AutomaticSize.X,
                TextSize = 13,
                FontFace = Fonts.Bold,
                TextTruncate = Enum.TextTruncate.None,
                LayoutOrder = 2,
                Parent = frame2
            })

            helperFn(label)

            local label2 = createLabel({
                Size = UDim2.fromOffset(0, 0),
                AutomaticSize = Enum.AutomaticSize.XY,
                TextSize = 12,
                FontFace = Fonts.Medium,
                TextWrapped = true,
                TextTruncate = Enum.TextTruncate.None,
                TextYAlignment = Enum.TextYAlignment.Top,
                LineHeight = 1.1,
                LayoutOrder = 2,
                Parent = frame
            })

            helperFn(label2)
            create('UISizeConstraint', { MaxSize = Vector2.new(240, math.huge), Parent = label2 })

            local function helperFn2()
                local num2 = math.max(uiScale.Scale, 0.01)
                local num3 = frame.AbsoluteSize / num2
                tooltip.Size = UDim2.fromOffset(num3.X + num * 2, num3.Y + num * 2)
            end

            frame:GetPropertyChangedSignal('AbsoluteSize'):Connect(helperFn2)

            local tbl = {
                Holder = tooltip,
                Scale = uiScale,
                Pad = num,
                Head = frame2,
                Icon = imageLabel,
                Title = label,
                Body = label2,
                Shown = false,
                Fit = helperFn2
            }

            self._tip = tbl

            self:_listen('Render', function(param)
                local tipowner = self._tipOwner
                if not tipowner then
                    return
                end
                local frame3 = tipowner._frame
                if tipowner._destroyed or not self.Open or self.Minimized or not frame3 or not frame3.Parent or (tipowner._isShown and not tipowner:_isShown()) or not isGuiVisibleInAncestors(frame3, self.Body, frame3.AbsolutePosition + frame3.AbsoluteSize / 2) then
                    self:_hideTooltip()
                    return
                end
                local num2 = getMousePos() - self.Gui.AbsolutePosition
                local num3 = tbl.Pad * uiScale.Scale
                local num4 = tooltip.AbsoluteSize - Vector2.one * num3 * 2
                local absolutesize = self.Gui.AbsoluteSize
                local num5, num6
                if tbl.Touch then
                    num5, num6 = num2.X - num4.X / 2, num2.Y - num4.Y - 30
                else
                    num5, num6 = num2.X + 14, num2.Y + 20
                    if num5 + num4.X > absolutesize.X - 8 then
                        num5 = num2.X - num4.X - 10
                    end
                    if num6 + num4.Y > absolutesize.Y - 8 then
                        num6 = num2.Y - num4.Y - 12
                    end
                end
                local vec = Vector2.new(math.clamp(num5, 8, math.max(8, absolutesize.X - num4.X - 8)), math.clamp(num6, 8, math.max(8, absolutesize.Y - num4.Y - 8)))
                local position = tbl.Position
                if not position or tbl.Snap then
                    position = vec + Vector2.new(0, 6)
                    tbl.Snap = false
                else
                    position = position:Lerp(vec, math.min(param * 22, 1))
                end
                tbl.Position = position
                tooltip.Position = UDim2.fromOffset(math.floor(position.X - num3 + 0.5), math.floor(position.Y - num3 + 0.5))
            end)

            self:_listen('Began', function(param)
                if self._tipOwner and not tbl.Touch and (param.UserInputType == Enum.UserInputType.MouseButton1 or param.UserInputType == Enum.UserInputType.MouseButton2 or param.UserInputType == Enum.UserInputType.Keyboard) then
                    self:_hideTooltip()
                end
            end)

            return tbl
        end

        function Window:_showTooltip(param, param2)
            local tooltip = param._tooltip
            local text, title, icon

            if type(tooltip) == 'table' then
                text, title, icon = tooltip.Text or tooltip.Content or tooltip.Desc, tooltip.Title or tooltip.Name, tooltip.Icon
            elseif tooltip ~= nil and tooltip ~= false then
                text = tostring(tooltip)
            end

            if (text == nil or text == '') and (title == nil or title == '') then
                return
            end

            local val = self:_tooltipCard()
            val.Title.Text = title or ''
            val.Title.Visible = title ~= nil and title ~= ''
            val.Icon.Visible = icon ~= nil

            if icon ~= nil then
                applyIcon(val.Icon, icon)
            end

            val.Head.Visible = val.Title.Visible or icon ~= nil
            val.Body.Text = text or ''
            val.Body.Visible = text ~= nil and text ~= ''
            val.Fit()
            val.Body.TextColor3 = Theme.Text
            val.Scale.Scale = math.max(self.Scale.Scale, 0.75)
            val.Touch = param2 == true
            local shown = val.Shown
            self._tipOwner = param
            val.Shown = true
            val.Generation = (val.Generation or 0) + 1
            local holder = val.Holder

            if not shown then
                val.Snap = true
                holder.Visible = true
                holder.GroupTransparency = 1
                val.Scale.Scale = val.Scale.Scale * 0.96
            end

            tween(holder, { GroupTransparency = 0 }, 0.14, Enum.EasingStyle.Quad)
            tween(val.Scale, { Scale = math.max(self.Scale.Scale, 0.75) }, 0.18, Enum.EasingStyle.Back)
        end

        function Window:_hideTooltip(param)
            local tip = self._tip

            if not tip or not tip.Shown or (param and self._tipOwner ~= param) then
                return
            end

            self._tipOwner = nil
            self._tipHiddenAt = os.clock()
            tip.Shown = false
            tip.Generation = (tip.Generation or 0) + 1
            local generation = tip.Generation
            tween(tip.Holder, { GroupTransparency = 1 }, 0.1, Enum.EasingStyle.Quad)

            task.delay(0.1, function()
                if tip.Generation == generation then
                    tip.Holder.Visible = false
                end
            end)
        end

        function Window:_attachTooltip(param, param2)
            -- Disabled: tooltips do not pop up on row hover
        end

        -- While dragging, a stand-in follows the pointer while the window stays put,
        -- and the window glides into its spot on release. The look is the player's
        -- Drag Style; "Off" drags the window itself.
        Library.DragStyles = { 'Outline', 'Brackets', 'Ghost', 'Frame', 'Off' }

        local function makeSkeleton(window)
            local root = window.Root
            local style = window.DragStyle or 'Outline'
            local c = root.AbsolutePosition + root.AbsoluteSize * root.AnchorPoint - window.Gui.AbsolutePosition
            local skeleton = create('Frame', {
                AnchorPoint = root.AnchorPoint,
                Position = UDim2.fromOffset(c.X, c.Y),
                Size = UDim2.fromOffset(root.AbsoluteSize.X, root.AbsoluteSize.Y),
                BackgroundColor3 = style == 'Ghost' and Theme.Background or Theme.Accent,
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ZIndex = 40,
                Parent = window.Gui
            })
            addCorner(skeleton, UDim.new(0, 10))
            -- Each part fades from hidden to its shown values, and back on release.
            local parts = {}
            local function part(object, shown)
                local hidden = {}
                for key in pairs(shown) do
                    hidden[key] = 1
                end
                table.insert(parts, { Object = object, Shown = shown, Hidden = hidden })
            end
            local function brackets(length, inset)
                for _, spot in ipairs({ Vector2.new(0, 0), Vector2.new(1, 0), Vector2.new(0, 1), Vector2.new(1, 1) }) do
                    local at = UDim2.new(spot.X, spot.X == 0 and inset or -inset, spot.Y, spot.Y == 0 and inset or -inset)
                    for _, size in ipairs({ UDim2.fromOffset(length, 2), UDim2.fromOffset(2, length) }) do
                        local bracket = create('Frame', {
                            AnchorPoint = spot,
                            Position = at,
                            Size = size,
                            BackgroundColor3 = Theme.Accent,
                            BackgroundTransparency = 1,
                            BorderSizePixel = 0,
                            Parent = skeleton
                        })
                        addCorner(bracket, UDim.new(1, 0))
                        part(bracket, { BackgroundTransparency = 0 })
                    end
                end
            end
            if style == 'Brackets' then
                -- Just the four corners of the window, a little longer.
                brackets(22, 0)
            elseif style == 'Ghost' then
                -- A see-through copy of the window's panel.
                part(skeleton, { BackgroundTransparency = 0.35 })
                part(addStroke(skeleton, Theme.Stroke, 1, 1), { Transparency = 0 })
            elseif style == 'Frame' then
                -- A single quiet line, nothing else.
                part(addStroke(skeleton, Theme.StrokeHover, 1, 1), { Transparency = 0 })
            else
                -- Outline: a faint accent wash, an outline and corner brackets.
                part(skeleton, { BackgroundTransparency = 0.92 })
                part(addStroke(skeleton, Theme.Accent, 1, 1.5), { Transparency = 0.2 })
                brackets(16, 6)
            end
            local scale = create('UIScale', { Scale = 1.02, Parent = skeleton })
            for _, item in ipairs(parts) do
                tween(item.Object, item.Shown, 0.15, Enum.EasingStyle.Quad)
            end
            tween(scale, { Scale = 1 }, 0.25, Enum.EasingStyle.Quint)
            local function fade()
                for _, item in ipairs(parts) do
                    tween(item.Object, item.Hidden, 0.2, Enum.EasingStyle.Quad)
                end
                task.delay(0.22, function()
                    skeleton:Destroy()
                end)
            end
            return skeleton, fade
        end

        function Window:_enableDrag()
            local dragging, moved = false, false
            local grabOffset, pressPoint = Vector2.zero, Vector2.zero
            local target = nil
            local skeleton, fadeSkeleton = nil, nil

            local function centre()
                local root = self.Root
                return root.AbsolutePosition + root.AbsoluteSize * root.AnchorPoint - self.Gui.AbsolutePosition
            end

            local function dropSkeleton()
                if not skeleton then
                    return
                end
                local spot = Vector2.new(skeleton.Position.X.Offset, skeleton.Position.Y.Offset)
                if self.KeepOnScreen then
                    spot = self:_clampedCentre(spot)
                end
                if self._clampTween then
                    self._clampTween:Cancel()
                end
                self._clampTween = tween(self.Root, { Position = UDim2.fromOffset(spot.X, spot.Y) }, 0.3, Enum.EasingStyle.Quint)
                fadeSkeleton()
                skeleton, fadeSkeleton = nil, nil
            end

            table.insert(self._connections, UserInputService.InputBegan:Connect(function(input)
                if not isPrimaryPress(input) then
                    return
                end
                if not self.Open or not self.Root.Visible then
                    return
                end
                local point = getMousePos()
                if self._resizeActive or (self._grip and isPointInGui(point, self._grip)) then
                    return
                end
                if not isPointInGui(point, self.Body) or self:_overControl(point) then
                    return
                end
                if self._clampTween then
                    self._clampTween:Cancel()
                    self._clampTween = nil
                end
                dragging, moved = true, false
                pressPoint = point
                grabOffset = point - centre()
            end))

            table.insert(self._connections, UserInputService.InputEnded:Connect(function(input)
                if not dragging then
                    return
                end
                if isPrimaryPress(input) then
                    dragging = false
                    target = nil
                    if skeleton then
                        dropSkeleton()
                    else
                        self:_clampToScreen()
                    end
                end
            end))

            table.insert(self._frameSteps, function(deltaTime)
                if not dragging then
                    return
                end
                local point = getMousePos()
                if not moved and (point - pressPoint).Magnitude > 3 then
                    moved = true
                    if self.DragSkeleton then
                        skeleton, fadeSkeleton = makeSkeleton(self)
                    end
                end
                if not moved then
                    return
                end
                -- Hidden or minimized mid-drag: land it where the outline is.
                if skeleton and (not self.Open or not self.Root.Visible) then
                    dragging = false
                    dropSkeleton()
                    return
                end
                target = point - grabOffset
                local alpha = 1 - math.exp(-deltaTime * 45)
                if skeleton then
                    local current = Vector2.new(skeleton.Position.X.Offset, skeleton.Position.Y.Offset)
                    local step = current:Lerp(target, alpha)
                    skeleton.Position = UDim2.fromOffset(step.X, step.Y)
                else
                    local step = centre():Lerp(target, alpha)
                    self.Root.Position = UDim2.fromOffset(step.X, step.Y)
                end
            end)
        end

        -- One of Library.DragStyles; anything else falls back to "Outline".
        -- Returns the style it settled on.
        function Window:SetDragStyle(style)
            style = table.find(Library.DragStyles, style) and style or 'Outline'
            self.DragStyle = style
            self.DragSkeleton = style ~= 'Off'
            return style
        end

        function Window:GetDragStyle()
            return self.DragStyle
        end

        Library.IslandStyles = { 'Show on Hover', 'Always Show' }

        function Window:SetIslandStyle(value)
            value = table.find(Library.IslandStyles, value) and value or 'Show on Hover'
            self.IslandStyle = value

            if self._islandSettle then
                self._islandSettle()
            end

            return value
        end

        function Window:GetIslandStyle()
            return self.IslandStyle
        end

        function Window:SetDragSkeleton(value)
            if value == false then
                self:SetDragStyle('Off')
            elseif self.DragStyle == 'Off' or not self.DragStyle then
                self:SetDragStyle('Outline')
            end
        end

        function Window:_sidebarResize(param, param2, allowDragResize)
            self.SidebarWidth = tonumber(param2) or self.SidebarWidth or SIDEBAR_WIDTH
            param.Size = UDim2.new(0, self.SidebarWidth, 1, 0)
            self.Content.Position = UDim2.fromOffset(self.SidebarWidth + 1, 0)
            self.Content.Size = UDim2.new(1, -(self.SidebarWidth + 1), 1, 0)
        end

        function Window:ToggleSidebar(collapsed)
            if collapsed == nil then
                collapsed = not self._sidebarCollapsed
            end
            self._sidebarCollapsed = collapsed
            local targetWidth = collapsed and SIDEBAR_COLLAPSED_WIDTH or (self.SidebarWidth or SIDEBAR_WIDTH)
            local duration = 0.18

            tween(self.Sidebar, { Size = UDim2.new(0, targetWidth, 1, 0) }, duration, Enum.EasingStyle.Quint)
            tween(self.Content, {
                Position = UDim2.fromOffset(targetWidth + 1, 0),
                Size = UDim2.new(1, -(targetWidth + 1), 1, 0)
            }, duration, Enum.EasingStyle.Quint)

            local profBottom = self._hasProfile and PROFILE_FOOTER_HEIGHT or 12
            if collapsed then
                self._brandTitleBox.Visible = false
                tween(self._brandLogo, { Position = UDim2.fromOffset(14, 12) }, duration)
                tween(self._collapseBtn, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 54) }, duration)
                tween(self.TabList, { Position = UDim2.fromOffset(0, 90), Size = UDim2.new(1, 0, 1, -(90 + profBottom)) }, duration)
            else
                self._brandTitleBox.Visible = true
                tween(self._brandLogo, { Position = UDim2.fromOffset(12, 9) }, duration)
                tween(self._collapseBtn, { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -12, 0, 12) }, duration)
                tween(self.TabList, { Position = UDim2.fromOffset(0, SIDEBAR_HEADER_HEIGHT), Size = UDim2.new(1, 0, 1, -(SIDEBAR_HEADER_HEIGHT + profBottom)) }, duration)
            end

            self:_updateSidebarCollapsed(collapsed)
        end

        function Window:_updateSidebarCollapsed(collapsed)
            -- Update category headers
            if self._categoryList then
                for _, cat in ipairs(self._categoryList) do
                    cat.Label.Visible = not collapsed
                    cat.Divider.Visible = collapsed
                end
            end
            -- Update tabs
            for _, tab in ipairs(self.Tabs or {}) do
                if tab._label then
                    tab._label.Visible = not collapsed
                end
                if tab._icon then
                    if collapsed then
                        tab._icon.AnchorPoint = Vector2.new(0.5, 0.5)
                        tab._icon.Position = UDim2.fromScale(0.5, 0.5)
                    else
                        tab._icon.AnchorPoint = Vector2.new(0, 0.5)
                        tab._icon.Position = UDim2.new(0, 10, 0.5, 0)
                    end
                end
            end
            -- Update profile card
            if self._profileCard then
                if collapsed then
                    self._profileCard.BackgroundTransparency = 1
                    if self._profileCardStroke then self._profileCardStroke.Transparency = 1 end
                    if self._profileName then self._profileName.Visible = false end
                    if self._profileSub then self._profileSub.Visible = false end
                    if self._profileChevron then self._profileChevron.Visible = false end
                    if self._profileAvatar then
                        self._profileAvatar.AnchorPoint = Vector2.new(0.5, 0.5)
                        self._profileAvatar.Position = UDim2.fromScale(0.5, 0.5)
                    end
                else
                    self._profileCard.BackgroundTransparency = 0
                    if self._profileCardStroke then self._profileCardStroke.Transparency = 0 end
                    if self._profileName then self._profileName.Visible = true end
                    if self._profileSub then self._profileSub.Visible = true end
                    if self._profileChevron then self._profileChevron.Visible = true end
                    if self._profileAvatar then
                        self._profileAvatar.AnchorPoint = Vector2.new(0, 0.5)
                        self._profileAvatar.Position = UDim2.new(0, 6, 0.5, 0)
                    end
                end
            end
        end

        function Window:SetTransparent(value)
            if type(value) == 'number' then
                local num2 = value > 1 and (value / 100) or value
                self.Transparency = math.clamp(num2, 0, 1)
                self.Transparent = self.Transparency > 0
            elseif type(value) == 'boolean' then
                self.Transparent = value
                if self.Transparent then
                    if not self.Transparency or self.Transparency == 0 then
                        self.Transparency = 0.35
                    end
                else
                    self.Transparency = 0
                end
            elseif value == nil then
                self.Transparent = self.Transparent == true
                if self.Transparent and (not self.Transparency or self.Transparency == 0) then
                    self.Transparency = 0.35
                elseif not self.Transparent then
                    self.Transparency = 0
                end
            end

            local transparent = self.Transparent
            local transparency = transparent and (self.Transparency or 0.35) or 0
            self._shadowRest = transparent and 0.85 or 0.6
            tween(self.Body, { BackgroundTransparency = transparency }, 0.25)
            local num = transparent and 1 or (self.Background and 0.45 or 0)
            tween(self.SidebarFill, { BackgroundTransparency = num }, 0.25)

            if self.Open and not self.Minimized and self.Root.Visible then
                tween(self.Shadow, { ImageTransparency = self._shadowRest }, 0.25)
            end

            if self._transparentSlider and self._transparentSlider.Value ~= math.floor(transparency * 100 + 0.5) then
                pcall(function()
                    self._transparentSlider:Set(math.floor(transparency * 100 + 0.5), true)
                end)
            end
        end

        local function getSortedGuiChildren(parent)
            local tbl = {}
            for idx, child in ipairs(parent:GetChildren()) do
                if child:IsA('GuiObject') then
                    table.insert(tbl, child)
                end
            end
            table.sort(tbl, function(param, param2)
                return param.LayoutOrder < param2.LayoutOrder
            end)
            return tbl
        end

        local function popInElement(guiObj, delaySec, force)
            if not guiObj.Visible and not force then
                return
            end
            guiObj.Visible = false
            task.delay(delaySec, function()
                if not guiObj.Parent then
                    return
                end
                local uiScale = create('UIScale', { Scale = 0.94, Parent = guiObj })
                guiObj.Visible = true
                tween(uiScale, { Scale = 1 }, 0.4, Enum.EasingStyle.Back)
                task.delay(0.4, function()
                    uiScale:Destroy()
                end)
            end)
        end

        function Window:_revealCards(param, param2)
            local currentsubtab = param.CurrentSubTab or param

            if currentsubtab._revealed then
                return
            end

            currentsubtab._revealed = true
            local num = 0

            local function helperFn(param3)
                popInElement(param3, (param2 or 0) + num * 0.035)
                num += 1
            end

            local columnset = currentsubtab._columnSet

            for idx, item in ipairs(getSortedGuiChildren(currentsubtab.List)) do
                if columnset and item == columnset.Holder then
                    local val, val2 = getSortedGuiChildren(columnset.Left), getSortedGuiChildren(columnset.Right)
                    for idx2 = 1, math.max(#val, #val2) do
                        if val[idx2] then
                            helperFn(val[idx2])
                        end
                        if val2[idx2] then
                            helperFn(val2[idx2])
                        end
                    end
                else
                    helperFn(item)
                end
            end
        end

        function Window:_playIntro(param)
            if self._introDone or self._destroyed then
                return
            end

            self._introDone = true
            self:_refreshBackdrop(true)

            task.delay(0.4, function()
                self:_refreshToggleButton()
            end)

            task.delay(1.5, function()
                if not self._destroyed and not self.MiniBar then
                    self:_buildMiniBar()
                end
            end)

            if self:GetMinimizeOnStart() then
                task.delay(0.6, function()
                    if not self._destroyed and self.Open and not self.Minimized then
                        self:Minimize()
                    end
                end)
            end

            local root, shadow, scale = self.Root, self.Shadow, self.Scale

            if self.CurrentTab then
                self:_revealCards(self.CurrentTab, param and 0.15 or 0.25)
            end

            root.Visible = true

            local hp = self._homePos or UDim2.fromScale(0.5, 0.5)
            if param then
                scale.Scale = self._fitScale or 1
                root.Position = hp
                self:_fade(0, 0.3)
                tween(self.BodyStroke, { Transparency = 0 }, 0.3)
                tween(shadow, { ImageTransparency = 0.6 }, 0.3)
            else
                root.Position = hp + UDim2.fromOffset(0, 24)
                tween(scale, { Scale = self._fitScale or 1 }, 0.5, Enum.EasingStyle.Back)
                tween(root, { Position = hp }, 0.5, Enum.EasingStyle.Quint)
                self:_fade(0, 0.35)
                tween(self.BodyStroke, { Transparency = 0 }, 0.35)
            end

            if not param then
                tween(shadow, { ImageTransparency = 0.6 }, 0.5)
            end

            for idx, tab in ipairs(self.Tabs) do
                popInElement(tab._button, 0.1 + idx * 0.05, true)
            end

            self.Indicator.Visible = false

            task.delay(0.15 + #self.Tabs * 0.05, function()
                if self.CurrentTab then
                    self:_placeIndicator(self.CurrentTab)
                end
            end)
        end

        function Window:_showLoader(param)
            local loadingduration = param.LoadingDuration or 1.6
            local gui = self.Gui
            local loadingsteps = param.LoadingSteps or { 'Preparing interface', 'Loading icons', 'Almost there' }
            local num, num2, num3 = 340, 22, 24
            local num4 = 80
            local num5 = num4 + #loadingsteps * num3 + 18

            local canvasGroup = create('CanvasGroup', {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.new(0.5, 0, 0.5, 10),
                Size = UDim2.fromOffset(num, num5),
                BackgroundColor3 = Theme.Background,
                BorderSizePixel = 0,
                GroupTransparency = 1,
                ZIndex = 10,
                Parent = gui
            })

