        function Window:_fitToScreen(param)
            local absolutesize = self.Gui.AbsoluteSize

            if absolutesize.X == 0 or absolutesize.Y == 0 then
                return
            end

            local size = self.Root.Size
            local num = (self._uiScale or 1) * (self._adaptive ~= false and Library._adaptiveFactor(absolutesize) or 1)
            local num2 = math.min(num, (absolutesize.X - 24) / math.max(size.X.Offset, 1), (absolutesize.Y - 24) / math.max(size.Y.Offset, 1))
            self._fitScale = math.max(num2, 0.45)

            if self._introDone and self.Open then
                if param then
                    self.Scale.Scale = self._fitScale
                else
                    tween(self.Scale, { Scale = self._fitScale }, 0.2)
                end
            end
        end

        function Library._adaptiveFactor(param)
            if isTouch then
                return 1
            end

            local num = math.min(param.X / 1920, param.Y / 1020)

            if num > 0.9 and num < 1.15 then
                return 1
            end

            return math.clamp(math.floor(num * 20 + 0.5) / 20, 0.85, 1.75)
        end

        function Window:SetAdaptiveSize(value)
            self._adaptive = value ~= false
            self:_fitToScreen()

            task.delay(0.22, function()
                if not self._destroyed then
                    self:_clampToScreen()
                end
            end)
        end

        function Window:GetAdaptiveSize()
            return self._adaptive ~= false
        end

        function Window:SetUIScale(value)
            value = math.clamp(tonumber(value) or 1, 0.6, 1.5)
            self.UIScale = value
            self._uiScale = value
            self:_fitToScreen()

            task.delay(0.22, function()
                if not self._destroyed then
                    self:_clampToScreen()
                end
            end)
        end

        function Window:GetUIScale()
            return self._uiScale or 1
        end

        Library.DensityModes = {
            Compact = 0.55,
            Default = 1,
            Comfortable = 1.45
        }

        Library.Density = 'Default'

        function Library._spaced(param, param2)
            if param <= 0 then
                return 0
            end

            return math.max(math.floor(param * param2 + (param2 - 1) * 4 + 0.5), 0)
        end

        function Library._space(param, param2)
            local entry = Library.DensityModes[Library.Density] or 1

            if param:IsA('UIListLayout') or param:IsA('UIGridLayout') then
                param:SetAttribute('Space', param2)
                param.Padding = UDim.new(0, Library._spaced(param2, entry))
            elseif param:IsA('UIPadding') then
                param:SetAttribute('SpaceL', param2[1])
                param:SetAttribute('SpaceR', param2[2])
                param:SetAttribute('SpaceT', param2[3])
                param:SetAttribute('SpaceB', param2[4])
                param.PaddingLeft = UDim.new(0, math.floor(param2[1] * math.sqrt(entry) + 0.5))
                param.PaddingRight = UDim.new(0, math.floor(param2[2] * math.sqrt(entry) + 0.5))
                param.PaddingTop = UDim.new(0, Library._spaced(param2[3], entry))
                param.PaddingBottom = UDim.new(0, Library._spaced(param2[4], entry))
            end

            return param
        end

        function Library:SetDensity(value)
            if type(value) == 'string' then
                for key in pairs(Library.DensityModes) do
                    if key:lower() == value:lower() then
                        value = key
                        break
                    end
                end
            end

            if not Library.DensityModes[value] then
                value = 'Default'
            end

            Library.Density = value

            for idx, win in ipairs(Library.Windows) do
                if win.Gui and win.Gui.Parent then
                    for idx2, child in ipairs(win.Gui:GetDescendants()) do
                        local val = child:GetAttribute('Space')
                        if val then
                            Library._space(child, val)
                        elseif child:GetAttribute('SpaceL') then
                            Library._space(child, {
                                child:GetAttribute('SpaceL'),
                                child:GetAttribute('SpaceR'),
                                child:GetAttribute('SpaceT'),
                                child:GetAttribute('SpaceB')
                            })
                        end
                    end
                end
            end

            return value
        end

        function Window:SetDensity(value)
            return Library:SetDensity(value)
        end

        function Window:GetDensity()
            return Library.Density
        end

        function Window:_clampedCentre(param)
            local absolutesize = self.Gui.AbsoluteSize
            local num = self.Root.AbsoluteSize / 2
            return Vector2.new(math.clamp(param.X, math.min(num.X, absolutesize.X / 2), math.max(absolutesize.X - num.X, absolutesize.X / 2)), math.clamp(param.Y, math.min(num.Y, absolutesize.Y / 2), math.max(absolutesize.Y - num.Y, absolutesize.Y / 2)))
        end

        function Window:_clampToScreen()
            if not self.KeepOnScreen or self._resizeActive then
                return
            end

            local root = self.Root
            local num = root.AbsolutePosition + root.AbsoluteSize / 2 - self.Gui.AbsolutePosition
            local val = self:_clampedCentre(num)

            if (val - num).Magnitude > 0.5 then
                self._clampTween = tween(root, { Position = UDim2.fromOffset(val.X, val.Y) }, 0.25, Enum.EasingStyle.Quint)
            end
        end

        function Window:_createOpenButton(param)
            local gui = self.Gui

            local button = create('TextButton', {
                AnchorPoint = Vector2.new(0.5, 0),
                Position = UDim2.new(0.5, 0, 0, 14),
                Size = UDim2.fromOffset(0, 40),
                AutomaticSize = Enum.AutomaticSize.X,
                BackgroundColor3 = Theme.Background,
                BorderSizePixel = 0,
                Text = '',
                AutoButtonColor = false,
                ZIndex = 30,
                Parent = gui
            })

            addCorner(button, UDim.new(1, 0))
            addStroke(button, Theme.Stroke)
            addPadding(button, 12, 16)

            local imageLabel = create('ImageLabel', {
                AnchorPoint = Vector2.new(0, 0.5),
                Position = UDim2.new(0, 0, 0.5, 0),
                Size = UDim2.fromOffset(20, 20),
                BackgroundTransparency = 1,
                ImageColor3 = Theme.Accent,
                ScaleType = Enum.ScaleType.Fit,
                ZIndex = 31,
                Parent = button
            })

            applyIcon(imageLabel, param.Icon or Assets.Logo, true)

            createLabel({
                Position = UDim2.fromOffset(28, 0),
                Size = UDim2.new(0, 0, 1, 0),
                AutomaticSize = Enum.AutomaticSize.X,
                Text = param.Title or 'IggyHub',
                TextSize = 13,
                TextTruncate = Enum.TextTruncate.None,
                ZIndex = 31,
                Parent = button
            })

            self.OpenButton = button
            local flag, flag2 = false, false
            local zero = Vector2.zero

            button.InputBegan:Connect(function(input)
                if isPrimaryPress(input) then
                    flag = true
                    flag2 = false
                    zero = getMousePos() - button.AbsolutePosition
                end
            end)

            table.insert(self._connections, UserInputService.InputChanged:Connect(function(input)
                if not flag then
                    return
                end
                if isPointerMove(input) then
                    local num = getMousePos() - zero - gui.AbsolutePosition
                    if (num - (button.AbsolutePosition - gui.AbsolutePosition)).Magnitude > 3 then
                        flag2 = true
                    end
                    button.AnchorPoint = Vector2.new(0, 0)
                    button.Position = UDim2.fromOffset(math.clamp(num.X, 0, math.max(gui.AbsoluteSize.X - button.AbsoluteSize.X, 0)), math.clamp(num.Y, 0, math.max(gui.AbsoluteSize.Y - button.AbsoluteSize.Y, 0)))
                end
            end))

            table.insert(self._connections, UserInputService.InputEnded:Connect(function(input)
                if flag and isPrimaryPress(input) then
                    flag = false
                    if not flag2 then
                        self:Toggle()
                    end
                end
            end))
        end

        function Window:_toggleButtonAllowed()
            return self._toggleEnabled and (isTouch or self._togglePlatform == 'Both')
        end

        function Window:_refreshToggleButton()
            local togglebutton = self.ToggleButton

            if not togglebutton then
                return
            end

            local cond = self._introDone and not self._destroyed and self:_toggleButtonAllowed()

            if cond and not togglebutton.Visible then
                togglebutton.Visible = true
                togglebutton.Size = UDim2.fromOffset(0, 0)
                tween(togglebutton, { Size = UDim2.fromOffset(self._toggleSize, self._toggleSize) }, 0.45, Enum.EasingStyle.Quint)
            elseif not cond then
                togglebutton.Visible = false
            end

            local minimized = self.Minimized or not self.Open

            if self._toggleStroke then
                tween(self._toggleStroke, {
                    Transparency = 1
                }, 0.35)
            end

            local toggleicon = self._toggleIcon
            if toggleicon then
                tween(toggleicon, {
                    Rotation = 0,
                    ImageTransparency = minimized and 0.25 or 0
                }, 0.35, Enum.EasingStyle.Quint)

                if self._toggleIconScale then
                    tween(self._toggleIconScale, {
                        Scale = minimized and 0.94 or 1.0
                    }, 0.4, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
                end

                if not toggleicon:GetAttribute('CustomIcon') then
                    tween(toggleicon, { ImageColor3 = minimized and Theme.Muted or Theme.Accent }, 0.35)
                end
            end
        end

        function Window:_createToggleButton(param)
            local gui = self.Gui
            local num = tonumber(param.Size) or (isTouch and 70 or 64)
            self._toggleEnabled = param.Enabled ~= false
            self._togglePlatform = param.Platform == 'Both' and 'Both' or 'Mobile'
            self._toggleSize = num

            local button = create('TextButton', {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = param.Position or UDim2.new(0, 18 + num / 2, 0.5, 62),
                Size = UDim2.fromOffset(num, num),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                Text = '',
                AutoButtonColor = false,
                ClipsDescendants = false,
                Visible = false,
                ZIndex = 30,
                Parent = gui
            })

            local stroke = addStroke(button, Theme.Stroke, 1, 1)

            local imageLabel = create('ImageLabel', {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                ImageColor3 = Theme.Accent,
                ScaleType = Enum.ScaleType.Fit,
                ZIndex = 31,
                Parent = button
            })

            local iconScale = create('UIScale', { Parent = imageLabel })
            self.ToggleButton = button
            self._toggleStroke = stroke
            self._toggleIcon = imageLabel
            self._toggleIconScale = iconScale
            self:SetToggleButtonIcon(param.Icon or 'layout-grid')
            local flag, flag2 = false, false
            local zero = Vector2.zero

            button.MouseEnter:Connect(function()
                tween(iconScale, { Scale = 1.08 }, 0.2, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
                tween(imageLabel, { ImageTransparency = 0 }, 0.15)
            end)

            button.MouseLeave:Connect(function()
                local minimized = self.Minimized or not self.Open
                tween(iconScale, { Scale = minimized and 0.94 or 1.0 }, 0.25, Enum.EasingStyle.Quint)
                tween(imageLabel, { ImageTransparency = minimized and 0.25 or 0 }, 0.2)
            end)

            button.InputBegan:Connect(function(input)
                if isPrimaryPress(input) then
                    flag = true
                    flag2 = false
                    zero = getMousePos() - button.AbsolutePosition
                    tween(iconScale, { Scale = 0.85 }, 0.12, Enum.EasingStyle.Quad)
                end
            end)

            table.insert(self._connections, UserInputService.InputChanged:Connect(function(input)
                if not flag or not isPointerMove(input) then
                    return
                end
                local num3 = getMousePos() - zero - gui.AbsolutePosition
                if (num3 - (button.AbsolutePosition - gui.AbsolutePosition)).Magnitude > 3 then
                    flag2 = true
                end
                if flag2 then
                    button.AnchorPoint = Vector2.zero
                    button.Position = UDim2.fromOffset(math.clamp(num3.X, 0, math.max(gui.AbsoluteSize.X - button.AbsoluteSize.X, 0)), math.clamp(num3.Y, 0, math.max(gui.AbsoluteSize.Y - button.AbsoluteSize.Y, 0)))
                end
            end))

            table.insert(self._connections, UserInputService.InputEnded:Connect(function(input)
                if not flag or not isPrimaryPress(input) then
                    return
                end
                flag = false
                tween(iconScale, { Scale = 1.0 }, 0.35, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
                if flag2 then
                    return
                end
                if not self.Open then
                    self:Toggle(true)
                elseif self.Minimized then
                    self:Restore()
                else
                    self:Minimize()
                end
            end))
        end

        function Window:SetToggleButton(value)
            self._toggleEnabled = value ~= false
            self:_refreshToggleButton()
        end

        function Window:SetToggleButtonSize(value)
            local n = tonumber(value)
            if not n then return end
            self._toggleSize = n
            if self.ToggleButton then
                self.ToggleButton.Size = UDim2.fromOffset(n, n)
            end
        end

        function Window:SetToggleButtonPlatform(value)
            self._togglePlatform = value == 'Both' and 'Both' or 'Mobile'
            self:_refreshToggleButton()
        end

        function Window:SetToggleButtonIcon(value)
            local toggleicon = self._toggleIcon

            if not toggleicon then
                return
            end

            toggleicon.Image = ''
            applyIcon(toggleicon, value)

            if toggleicon.Image == '' then
                applyIcon(toggleicon, Assets.Logo)
            end

            if not toggleicon:GetAttribute('CustomIcon') then
                tween(toggleicon, {
                    ImageColor3 = (self.Minimized or not self.Open) and Theme.Text or Theme.Accent
                }, 0)
            end
        end

        function Window:_enableResize(param)
            local maxsize = self.MaxSize or Vector2.new(math.huge, math.huge)
            self._minSize = param
            local root = self.Root

            local frame = create('Frame', {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.new(1, 4, 1, 4),
                Size = UDim2.fromOffset(32, 32),
                BackgroundTransparency = 1,
                Active = true,
                ZIndex = 20,
                Parent = root
            })

            self._grip = frame

            local frame2 = create('Frame', {
                AnchorPoint = Vector2.new(1, 1),
                Position = UDim2.fromOffset(12, 12),
                Size = UDim2.fromOffset(26, 26),
                BackgroundTransparency = 1,
                ZIndex = 20,
                Parent = frame
            })

            addCorner(frame2, UDim.new(0, 10))

            local uiStroke = create('UIStroke', {
                Color = Theme.Muted,
                Thickness = 2,
                Transparency = 0.55,
                Parent = frame2
            })

            create('UIGradient', {
                Rotation = 45,
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 1),
                    NumberSequenceKeypoint.new(0.55, 1),
                    NumberSequenceKeypoint.new(0.85, 0),
                    NumberSequenceKeypoint.new(1, 0)
                }),
                Parent = uiStroke
            })

            local function helperFn(param2)
                tween(uiStroke, {
                    Color = param2 and Theme.Accent or Theme.Muted,
                    Transparency = param2 and 0 or 0.55
                }, param2 and 0.15 or 0.3, Enum.EasingStyle.Quint)
            end

            local num = 20
            local flag = false
            local zero = Vector2.zero
            local zero2 = Vector2.zero
            local zero3 = Vector2.zero
            local zero4 = Vector2.zero
            local zero5 = Vector2.zero
            local zero6 = Vector2.zero

            local function helperFn2()
                return Vector2.new(root.Size.X.Offset, root.Size.Y.Offset)
            end

            local function helperFn3()
                if root.AnchorPoint == Vector2.zero then
                    return
                end
                if self._clampTween then
                    self._clampTween:Cancel()
                    self._clampTween = nil
                end
                local num2 = root.AbsolutePosition - self.Gui.AbsolutePosition
                root.AnchorPoint = Vector2.zero
                root.Position = UDim2.fromOffset(num2.X, num2.Y)
            end

            local function helperFn4()
                local num2 = root.AbsolutePosition - self.Gui.AbsolutePosition
                local num3 = root.AbsoluteSize / 2
                root.AnchorPoint = Vector2.new(0.5, 0.5)
                root.Position = UDim2.fromOffset(num2.X + num3.X, num2.Y + num3.Y)
            end

            local function helperFn5(param2)
                return Vector2.new(math.floor(math.clamp(param2.X, param.X, maxsize.X) + 0.5), math.floor(math.clamp(param2.Y, param.Y, maxsize.Y) + 0.5))
            end

            frame.InputBegan:Connect(function(input)
                if not isPrimaryPress(input) or not self.Open then
                    return
                end
                if not self._resizeActive then
                    helperFn3()
                    zero3 = helperFn2()
                    zero4 = Vector2.zero
                    zero6 = zero3
                end
                self._resizeActive = true
                flag = true
                zero = zero3
                zero2 = getMousePos()
                zero5 = helperFn5(zero)
                helperFn(true)
            end)

            frame.MouseEnter:Connect(function()
                if not flag then
                    helperFn(true)
                end
            end)

            frame.MouseLeave:Connect(function()
                if not flag then
                    helperFn(false)
                end
            end)

            table.insert(self._connections, UserInputService.InputEnded:Connect(function(input)
                if flag and isPrimaryPress(input) then
                    flag = false
                    helperFn(false)
                end
            end))

            table.insert(self._frameSteps, function(param2)
                if not self._resizeActive then
                    return
                end
                if flag then
                    local num6 = (getMousePos() - zero2) / self.Scale.Scale
                    zero5 = helperFn5(zero + num6)
                end
                local num2 = math.min(param2, 1 / 30)
                local num3 = math.exp(-num * num2)
                local num4 = zero3 - zero5
                local num5 = (zero4 + num4 * num) * num2
                zero4 = (zero4 - num5 * num) * num3
                zero3 = zero5 + (num4 + num5) * num3
                local vec = Vector2.new(math.floor(zero3.X + 0.5), math.floor(zero3.Y + 0.5))
                if vec ~= zero6 then
                    zero6 = vec
                    root.Size = UDim2.fromOffset(vec.X, vec.Y)
                end
                if not flag and (zero3 - zero5).Magnitude < 0.3 and zero4.Magnitude < 3 then
                    zero3 = zero5
                    zero4 = Vector2.zero
                    zero6 = zero5
                    root.Size = UDim2.fromOffset(zero5.X, zero5.Y)
                    helperFn4()
                    self._resizeActive = false
                    self:_fitToScreen()
                    self:_clampToScreen()
                end
            end)
        end

        function Window:GetSize()
            return Vector2.new(self.Root.Size.X.Offset, self.Root.Size.Y.Offset)
        end

        function Window:SetSize(value, param)
            if typeof(value) == 'UDim2' then
                value = Vector2.new(value.X.Offset, value.Y.Offset)
            end

            if typeof(value) ~= 'Vector2' or self._resizeActive then
                return
            end

            local minsize = self._minSize or Vector2.zero
            local maxsize = self.MaxSize or Vector2.new(math.huge, math.huge)
            value = Vector2.new(math.floor(math.clamp(value.X, minsize.X, maxsize.X) + 0.5), math.floor(math.clamp(value.Y, minsize.Y, maxsize.Y) + 0.5))

            if value == self:GetSize() then
                return
            end

            local num = (param or not self.Root.Visible) and 0 or 0.3
            tween(self.Root, { Size = UDim2.fromOffset(value.X, value.Y) }, num, Enum.EasingStyle.Quint)

            task.delay(num + 0.02, function()
                if not self._destroyed then
                    self:_fitToScreen()
                    self:_clampToScreen()
                end
            end)
        end

        local CONFIG_SCHEMA_VERSION = 1
        local SHARE_CODE_PREFIX = 'iggyui:'

        local function getConfigFilePath(win, cfgName)
            return win.ConfigFolder .. '/' .. cfgName .. '.json'
        end

        local function hasFileApi()
            return type(writefile) == 'function' and type(readfile) == 'function' and type(isfile) == 'function'
        end

        local function ensureFolder(folderPath)
            if type(isfolder) ~= 'function' or type(makefolder) ~= 'function' then
                return
            end
            local str = ''
            for part in tostring(folderPath):gmatch('[^/\\]+') do
                str = str == '' and part or str .. '/' .. part
                if not isfolder(str) then
                    makefolder(str)
                end
            end
        end

        local function colorToHexLower(col)
            return string.format('%02x%02x%02x', math.floor(col.R * 255 + 0.5), math.floor(col.G * 255 + 0.5), math.floor(col.B * 255 + 0.5))
        end

        local function parseSavedColor(raw)
            if type(raw) == 'table' then
                if type(raw.Hex) == 'string' then
                    raw = raw.Hex
                elseif type(raw[1]) == 'number' then
                    return Color3.new(raw[1], raw[2] or 0, raw[3] or 0)
                end
            end
            if type(raw) == 'string' then
                local val, val2, val3 = raw:match('^%s*#?(%x%x)(%x%x)(%x%x)%s*$')
                if val then
                    return Color3.fromRGB(tonumber(val, 16), tonumber(val2, 16), tonumber(val3, 16))
                end
            end
            return nil
        end

        local function serializeFlagElement(elem)
            local typeVal = elem._type
            local val = elem:Get()
            if type(elem._saveValue) == 'function' then
                val = elem:_saveValue()
            end
            if typeVal == 'Keybind' then
                return { Type = typeVal, Value = val and val.Name or nil }
            elseif typeVal == 'ColorPicker' then
                return {
                    Type = typeVal,
                    Value = typeof(val) == 'Color3' and { Hex = colorToHexLower(val) } or nil
                }
            end
            return { Type = typeVal, Value = val }
        end

        local function applySavedFlag(elem, savedEntry, silent)
            local typeVal = elem._type
            local value = savedEntry.Value
            if typeVal == 'Keybind' then
                elem:Set(type(value) == 'string' and Enum.KeyCode[value] or nil, silent)
            elseif typeVal == 'ColorPicker' then
                local val = parseSavedColor(value)
                if val then
                    elem:Set(val, silent)
                end
            elseif typeVal == 'Dropdown' then
                elem:Set(value, silent)
            elseif typeVal == 'Toggle' then
                if type(value) == 'boolean' then
                    elem:Set(value, silent)
                end
            elseif typeVal == 'Slider' or typeVal == 'Stepper' or typeVal == 'Progress' then
                local num = tonumber(value)
                if num then
                    elem:Set(num, silent)
                end
            elseif value ~= nil then
                elem:Set(value, silent)
            end
        end

        local function isFlagTypeCompatible(elem, savedEntry)
            return type(savedEntry) == 'table' and (savedEntry.Type == nil or savedEntry.Type == elem._type)
        end

        local function collectAllFlags(win)
            local tbl = {}
            if win and win._pendingFlags then
                for key, val in pairs(win._pendingFlags) do
                    tbl[key] = val.Entry
                end
            end
            local ignoreflags = win and win._ignoreFlags or {}
            for key in pairs(ignoreflags) do
                tbl[key] = nil
            end
            for key, val in pairs(Library.Flags) do
                if not ignoreflags[key] and val._type and type(val.Get) == 'function' then
                    local ok, res = pcall(serializeFlagElement, val)
                    if ok then
                        tbl[key] = res
                    end
                end
            end
            return tbl
        end

        Library.LoadingOrder = {
            'Dropdown',
            'Slider',
            'Stepper',
            'Input',
            'ColorPicker',
            'Keybind',
            'Toggle'
        }

        function Window:SetIgnoreFlags(value)
            self._ignoreFlags = self._ignoreFlags or {}

            for idx, item in ipairs(value or {}) do
                self._ignoreFlags[item] = true
            end
        end

        function Window:SetLoadingOrder(value)
            self._loadingOrder = type(value) == 'table' and value or nil
        end

        function Window:_applyFlags(param, param2)
            param2 = param2 == true
            self._pendingFlags = {}
            local ignoreflags = self._ignoreFlags or {}
            local loadingorder = self._loadingOrder or Library.LoadingOrder
            local tbl = {}

            for key, val in pairs(param) do
                if not ignoreflags[key] then
                    local flagElem = Library.Flags[key]
                    if flagElem and type(flagElem.Set) == 'function' then
                        if isFlagTypeCompatible(flagElem, val) then
                            table.insert(tbl, {
                                Element = flagElem,
                                Entry = val,
                                Rank = table.find(loadingorder, flagElem._type) or 0
                            })
                        end
                    elseif type(val) == 'table' then
                        self._pendingFlags[key] = { Entry = val, Silent = param2 }
                    end
                end
            end

            table.sort(tbl, function(param3, param4)
                return param3.Rank < param4.Rank
            end)

            for idx, item in ipairs(tbl) do
                task.defer(function()
                    if not item.Element._destroyed and not self._destroyed then
                        pcall(applySavedFlag, item.Element, item.Entry, param2)
                    end
                end)
            end
        end

        function Window:_flagCreated(param, param2)
            local ok, res = pcall(serializeFlagElement, param2)

            if ok then
                param2._defaultEntry = res
            end

            local entry = self._pendingFlags and self._pendingFlags[param]

            if not entry then
                return
            end

            task.defer(function()
                if self._pendingFlags[param] ~= entry or Library.Flags[param] ~= param2 or param2._destroyed then
                    return
                end
                self._pendingFlags[param] = nil
                if isFlagTypeCompatible(param2, entry.Entry) then
                    pcall(applySavedFlag, param2, entry.Entry, entry.Silent)
                end
            end)
        end

        function Window:_configChanged()
            for idx, item in ipairs(self._configListeners) do
                safeCall(item)
            end
        end

        function Window:OnConfigChanged(param)
            table.insert(self._configListeners, param)

            return function()
                local foundIdx = table.find(self._configListeners, param)
                if foundIdx then
                    table.remove(self._configListeners, foundIdx)
                end
            end
        end

        local function isValidFileName(nameStr)
            return type(nameStr) == 'string' and nameStr ~= '' and not nameStr:find('[\\/:%*%?"<>|]')
        end

        local function encodeSharePayload(win, cfgName, data)
            return HttpService:JSONEncode({
                Folder = win.ConfigFolder,
                Name = cfgName,
                Version = CONFIG_SCHEMA_VERSION,
                Config = HttpService:JSONEncode(data)
            })
        end

        local B64_ALPHABET = [[ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/]]
        local B64_DECODE_MAP = {}

        for idx = 1, #B64_ALPHABET do
            B64_DECODE_MAP[B64_ALPHABET:byte(idx)] = idx - 1
        end

        local function decodeBase64String(b64)
            if #b64 % 4 ~= 0 then
                return nil
            end
            local tbl = {}
            for idx = 1, #b64, 4 do
                local num, num2 = 0, 0
                for idx2 = 0, 3 do
                    local val = b64:byte(idx + idx2)
                    local entry = B64_DECODE_MAP[val]
                    if val == 61 and idx + 3 >= #b64 then
                        num2 += 1
                        entry = 0
                    elseif entry == nil or num2 > 0 then
                        return nil
                    end
                    num = num * 64 + entry
                end
                if num2 > 2 then
                    return nil
                end
                local str = string.char(bit32.extract(num, 16, 8), bit32.extract(num, 8, 8), bit32.extract(num, 0, 8))
                table.insert(tbl, str:sub(1, 3 - num2))
            end
            return table.concat(tbl)
        end

        local function decodeSharePayload(rawCode)
            rawCode = tostring(rawCode or ''):match('^%s*(.-)%s*$')
            if rawCode:sub(1, #SHARE_CODE_PREFIX) == SHARE_CODE_PREFIX then
                rawCode = decodeBase64String((rawCode:sub(#SHARE_CODE_PREFIX + 1):gsub('%s', '')))
                if not rawCode then
                    return nil, 'invalid config code'
                end
            end
            local ok, res = pcall(function()
                return HttpService:JSONDecode(rawCode)
            end)
            if not ok or type(res) ~= 'table' then
                return nil, 'invalid config code'
            end
            local tbl = {}
            if type(res.Config) == 'string' or (type(res.Config) == 'table' and res.Config.Type == nil) then
                tbl.Folder = type(res.Folder) == 'string' and res.Folder or nil
                tbl.Name = type(res.Name) == 'string' and res.Name or nil
                tbl.Version = tonumber(res.Version)
                local config = res.Config
                if type(config) == 'string' then
                    ok, config = pcall(function()
                        return HttpService:JSONDecode(res.Config)
                    end)
                    if not ok then
                        return nil, 'invalid config code'
                    end
                end
                if type(config) ~= 'table' then
                    return nil, 'invalid config code'
                end
                res = config
            end
            for key, val in pairs(res) do
                if type(key) ~= 'string' or type(val) ~= 'table' then
                    return nil, 'invalid config code'
                end
            end
            return res, tbl
        end

        local function writeConfigData(win, cfgName, data)
            if not isValidFileName(cfgName) then
                return false, 'invalid config name'
            end
            if not hasFileApi() then
                return false, 'file API unavailable'
            end
            local ok, res = pcall(encodeSharePayload, win, cfgName, data)
            if not ok then
                return false, 'could not encode config'
            end
            ensureFolder(win.ConfigFolder)
            return pcall(writefile, getConfigFilePath(win, cfgName), res)
        end

        local function readConfigData(win, cfgName)
            if not hasFileApi() then
                return nil, 'file API unavailable'
            end
            if not isValidFileName(cfgName) then
                return nil, 'invalid config name'
            end
            local val = getConfigFilePath(win, cfgName)
            if not isfile(val) then
                return nil, 'no config named ' .. tostring(cfgName)
            end
            local ok, res = pcall(readfile, val)
            if not ok or type(res) ~= 'string' then
                return nil, 'could not read ' .. cfgName
            end
            local payload, errMsg = decodeSharePayload(res)
            if not payload then
                return nil, 'config is not valid JSON'
            end
            return payload, errMsg
