            end

            local saved, errMsg = writeConfigData(self, param, collectAllFlags(self))

            if saved then
                self.ConfigName = param
            end

            return saved, errMsg
        end

        function Window:LoadConfig(param, param2)
            param = param or self.ConfigName

            if not param then
                return false, 'no config name'
            end

            local cfgData, errMsg = readConfigData(self, param)

            if not cfgData then
                return false, errMsg
            end

            self:_applyFlags(cfgData, param2)
            self.ConfigName = param
            self.LoadedConfig = param
            self:_configChanged()
            return true
        end

        function Window:DeleteConfig(param)
            if not hasFileApi() or type(delfile) ~= 'function' then
                return false, 'file API unavailable'
            end

            if not isValidFileName(param) then
                return false, 'invalid config name'
            end

            local val = getConfigFilePath(self, param)

            if not isfile(val) then
