            if self.LoadedConfig == param then
                self.LoadedConfig = nil
            end

            self:_configChanged()
            return true
        end

        function Window:RenameConfig(param, param2)
            if not isValidFileName(param2) then
                return false, 'invalid config name'
            end

            if param == param2 then
                return true
            end

            if self:ConfigExists(param2) then
                return false, param2 .. ' already exists'
            end

            local cfgData, errMsg = readConfigData(self, param)

            if not cfgData then
                return false, errMsg
            end

            local saved
            saved, errMsg = writeConfigData(self, param2, cfgData)

            if not saved then
                return false, errMsg
            end

            if type(delfile) == 'function' then
                pcall(delfile, getConfigFilePath(self, param))
            end

            if self.LoadedConfig == param then
                self.LoadedConfig = param2
            end

            if self.ConfigName == param then
                self.ConfigName = param2
            end

            for idx, item in ipairs({ 'Global', 'Account' }) do
                if self:GetAutoload(item) == param then
                    self:SetAutoload(param2, item)
                end
            end

            self:_configChanged()
            return true
        end

        function Window:ListConfigs()
            local tbl = {}

            if type(listfiles) ~= 'function' or type(isfolder) ~= 'function' or not isfolder(self.ConfigFolder) then
                return tbl
            end

            local ok, res = pcall(listfiles, self.ConfigFolder)

            if not ok or type(res) ~= 'table' then
                return tbl
            end

            for idx, item in ipairs(res) do
                local val = item:match('([^/\\]+)%.json$')
                if val then
                    table.insert(tbl, val)
                end
            end

            table.sort(tbl, function(param, param2)
                return param:lower() < param2:lower()
            end)

            return tbl
        end

        function Window:ResetConfig(param)
            self._pendingFlags = {}

            for key, val in pairs(Library.Flags) do
                if val._defaultEntry and type(val.Set) == 'function' then
                    pcall(applySavedFlag, val, val._defaultEntry, param == true)
                end
            end

            self:_configChanged()
            return true
        end

        local function removeFolderRecursive(folderPath)
            if type(isfolder) ~= 'function' or not isfolder(folderPath) then
                return true
            end
            if type(delfolder) == 'function' and pcall(delfolder, folderPath) and not isfolder(folderPath) then
                return true
            end
            if type(listfiles) == 'function' then
                local ok, res = pcall(listfiles, folderPath)
                for idx, item in ipairs(ok and res or {}) do
                    if isfolder(item) then
                        removeFolderRecursive(item)
                    elseif type(delfile) == 'function' then
                        pcall(delfile, item)
                    end
                end
            end
            if type(delfolder) == 'function' then
                pcall(delfolder, folderPath)
            end
            return not isfolder(folderPath)
        end

        function Window:ClearWorkspace()
            local val = removeFolderRecursive(self.ConfigFolder)
            self.LoadedConfig = nil

            for idx, item in ipairs(self._workspaceListeners or {}) do
                safeCall(item)
            end

            self:_configChanged()
            return val
        end

        function Window:ExportConfig(param)
            local cfgData, errMsg

            if param then
