                if not cfgData then
                    return nil, errMsg
                end
            else
                cfgData = collectAllFlags(self)
                param = self.LoadedConfig or self.ConfigName
            end

            local ok, res = pcall(encodeSharePayload, self, param, cfgData)

            if not ok then
                return nil, 'could not encode config'
            end

            return res
        end

        function Window:DecodeConfig(param)
