        end

        function Window:ImportConfig(param, param2, param3)
            local payload, errMsg = decodeSharePayload(param)

            if not payload then
                return false, errMsg
            end

            if not param3 and errMsg.Folder and errMsg.Folder ~= self.ConfigFolder then
                return false, 'config is for ' .. errMsg.Folder
            end

            if param2 == true then
                param2 = errMsg.Name
                if not isValidFileName(param2) then
                    return false, 'config has no usable name'
                end
            end

            if param2 then
                local saved, errMsg2 = writeConfigData(self, param2, payload)
                if not saved then
                    return false, errMsg2
                end
            end

            self:_applyFlags(payload)

            if param2 then
                self.ConfigName = param2
                self.LoadedConfig = param2
            end

            self:_configChanged()
