                return false, 'file API unavailable'
            end

            local val = self:_readConfigSettings()

            for key, val2 in pairs(param) do
                val[key] = val2
            end

            ensureFolder(self.ConfigFolder)
            return pcall(writefile, getConfigSettingsPath(self), HttpService:JSONEncode(val))
        end

        local function getAutoloadPath(win, mode)
            if mode == 'Account' then
                return win.ConfigFolder .. '/autoload_' .. tostring(LocalPlayer and LocalPlayer.UserId or 0) .. '.txt'
            end
            return win.ConfigFolder .. '/autoload.txt'
        end

        function Window:GetAutoloadMode()
            return self:_readConfigSettings().AutoloadMode == 'Account' and 'Account' or 'Global'
        end

        function Window:GetAutoload(param)
            if param then
                return readTextFile(getAutoloadPath(self, param))
            end

            return readTextFile(getAutoloadPath(self, 'Account')) or readTextFile(getAutoloadPath(self, 'Global'))
        end

        function Window:SetAutoload(value, param)
            if not hasFileApi() then
                return false, 'file API unavailable'
            end

            param = param or self:GetAutoloadMode()
            local flag, val = true, nil

            if value == nil or value == '' then
                deleteFileSafe(getAutoloadPath(self, param))
                if param == 'Global' then
                    deleteFileSafe(getAutoloadPath(self, 'Account'))
                end
            else
                ensureFolder(self.ConfigFolder)
                flag, val = pcall(writefile, getAutoloadPath(self, param), tostring(value))
                if flag and param == 'Global' then
                    deleteFileSafe(getAutoloadPath(self, 'Account'))
                end
            end

            self:_configChanged()
            return flag, val
        end

        function Window:SetAutoloadMode(value)
            value = value == 'Account' and 'Account' or 'Global'

            if value == self:GetAutoloadMode() then
                return true
            end

            local val = self:GetAutoload()
            local val2, val3 = self:_writeConfigSettings({ AutoloadMode = value })

            if not val2 then
                return false, val3
            end

            deleteFileSafe(getAutoloadPath(self, value == 'Account' and 'Global' or 'Account'))

            if val then
                return self:SetAutoload(val, value)
            end

            self:_configChanged()
            return true
        end

        function Window:GetMinimizeOnStart()
            return self:_readConfigSettings().MinimizeOnStart == true
        end

        function Window:SetMinimizeOnStart(value)
            return self:_writeConfigSettings({ MinimizeOnStart = value == true })
        end

        function Window:LoadAutoload(param)
            if self._autoloaded then
                return false, 'autoload already ran'
            end

            self._autoloaded = true
            local val = self:GetAutoload()

            if not val then
                return false, 'no autoload config'
            end

            local val2, val3 = self:LoadConfig(val, param)

            pcall(self.Notify, self, {
                Title = val2 and 'Autoload' or 'Autoload failed',
                Content = val2 and ('Loaded config %q'):format(val) or tostring(val3),
                Type = val2 and 'Success' or 'Error',
                Duration = 3
            })

            return val2, val3
        end

        Library._themeListeners = {}

        local function parseColorInput(raw)
            if typeof(raw) == 'Color3' then
                return raw
            elseif type(raw) == 'string' then
                local val, val2, val3 = raw:match('^%s*#?(%x%x)(%x%x)(%x%x)%s*$')
                if val then
                    return Color3.fromRGB(tonumber(val, 16), tonumber(val2, 16), tonumber(val3, 16))
                end
            elseif type(raw) == 'table' then
                local entry, entry2, entry3 = raw[1] or raw.R, raw[2] or raw.G, raw[3] or raw.B
                if tonumber(entry) and tonumber(entry2) and tonumber(entry3) then
                    return Color3.fromRGB(entry, entry2, entry3)
                end
            end
            return nil
        end

        local function colorToHexUpper(col)
            return string.format('#%02X%02X%02X', math.floor(col.R * 255 + 0.5), math.floor(col.G * 255 + 0.5), math.floor(col.B * 255 + 0.5))
        end

        Library._toneTags = {}

        for idx, item in ipairs(THEME_KEYS) do
            Library._toneTags[string.lower(item)] = item
        end

        function Library._dependsMet(param)
            if type(param) == 'function' then
                local ok, res = pcall(param)
                return ok and res and true or false
            end

            if type(param) == 'string' then
                param = { Flag = param }
            end

            if type(param) ~= 'table' then
                return true
            end

            if type(param) == 'table' and (type(param.Get) == 'function' or param._type ~= nil) and param.Flag == nil and #param == 0 then
                local ok, res = pcall(function()
                    if type(param.Get) == 'function' then
                        return param:Get()
                    end
                    return param.Value
                end)
                if ok then
                    local met = res == true or (type(res) == 'number' and res ~= 0) or (type(res) == 'string' and res ~= '') or (type(res) == 'table' and next(res) ~= nil)
                    if param.Not then met = not met end
                    return met
                end
            end

            if type(param) == 'table' and (param.Element or param.Toggle) then
                local elem = param.Element or param.Toggle
                local ok, res = pcall(function()
                    return type(elem.Get) == 'function' and elem:Get() or elem.Value
                end)
                if ok then
                    local met = false
                    if param.Value ~= nil then
                        met = res == param.Value
                    else
                        met = res == true or (type(res) == 'number' and res ~= 0) or (type(res) == 'string' and res ~= '')
                    end
                    if param.Not then met = not met end
                    return met
                end
            end

            if param.Flag == nil then
                for idx, item in ipairs(param) do
                    if not Library._dependsMet(item) then
                        return false
                    end
                end
                return true
            end

            local flagElem = Library.Flags[param.Flag]
            local flag = false

            if flagElem and type(flagElem.Get) == 'function' then
                local ok, res = pcall(flagElem.Get, flagElem)
                if ok then
                    if param.Value ~= nil then
                        local value = type(param.Value) == 'table' and param.Value or { param.Value }
                        local tbl = type(res) == 'table' and res or { res }
                        for idx, item in ipairs(value) do
                            if table.find(tbl, item) then
                                flag = true
                                break
                            end
                        end
                    else
                        flag = res == true or (type(res) == 'number' and res ~= 0) or (type(res) == 'string' and res ~= '') or (type(res) == 'table' and next(res) ~= nil) or typeof(res) == 'EnumItem' or typeof(res) == 'Color3'
                    end
                end
            end

            if param.Not then
                flag = not flag
            end

            return flag
        end

        function Library._applyDepends(param, param2)
            local cond = param._dependsOn == nil or Library._dependsMet(param._dependsOn)

            if cond == param._dependsMet and not param2 then
                return
            end

            param._dependsMet = cond
            local str = string.lower(tostring(param._dependsMode or 'Hide'))

            if str == 'disable' then
                if param._dependHidden then
                    Library._setDependHidden(param, false)
                end
                param._dependDisabled = not cond
                Library._setDisabled(param, param._frame, param.Disabled)
            else
                if param._dependDisabled then
                    param._dependDisabled = false
                    Library._setDisabled(param, param._frame, param.Disabled)
                end
                Library._setDependHidden(param, not cond)
            end
        end

        function Library._setDependHidden(param, param2)
            param2 = param2 == true

            if param2 == (param._dependHidden == true) then
                return
            end

            param._dependHidden = param2

            if param2 then
                if param._onHide then
                    param._onHide()
                end
                if param.Open and type(param.SetOpen) == 'function' then
                    param:SetOpen(false)
                end
            end

            local frame = param._frame

            if frame then
                frame.Visible = param._userVisible ~= false and not param2
            end

            if param._window then
                param._window._controlsDirty = true
            end
        end

        function Library._watchDepends(param, param2)
            if not param._dependents then
                param._dependents = {}
                local num = 0
                param:_listen('Render', function()
                    local clockTime = os.clock()
                    if clockTime - num < 0.1 then
                        return
                    end
                    num = clockTime
                    local dependents = param._dependents
                    for idx = #dependents, 1, -1 do
                        local entry = dependents[idx]
                        if entry._destroyed then
                            table.remove(dependents, idx)
                        elseif entry._dependsOn ~= nil then
                            Library._applyDepends(entry)
                        end
                    end
                end)
            end

            if not table.find(param._dependents, param2) then
                table.insert(param._dependents, param2)
            end

            Library._applyDepends(param2, true)
        end

        function Library._setDisabled(param, param2, param3)
            param.Disabled = param3 == true

            if not param2 then
                return
            end

            local disabled = param.Disabled or param._dependDisabled == true

            if disabled == (param._covered == true) then
                return
            end

            param._covered = disabled

            if disabled then
                if param._onHide then
                    param._onHide()
                end
                if param.Open and type(param.SetOpen) == 'function' then
                    param:SetOpen(false)
                end
            end

            local cover = param._cover

            if not cover then
                cover = create('TextButton', {
                    Name = 'DisabledCover',
                    Size = UDim2.fromScale(1, 1),
                    BackgroundColor3 = Theme.Surface2,
                    BackgroundTransparency = 1,
                    AutoButtonColor = false,
                    Text = '',
                    ZIndex = 20,
                    Visible = false,
                    Parent = param2
                })
                cover:SetAttribute('NoDrag', true)
                addCorner(cover)
                param._cover = cover
            end

            param._coverGeneration = (param._coverGeneration or 0) + 1
            local covergeneration = param._coverGeneration

            if disabled then
                cover.Visible = true
                tween(cover, { BackgroundTransparency = 0.4 }, 0.15)
            else
                tween(cover, { BackgroundTransparency = 1 }, 0.15)
                task.delay(0.16, function()
                    if param._coverGeneration == covergeneration then
                        cover.Visible = false
                    end
                end)
            end
        end

        function Library._gateButton(param, param2)
            local callback = param2.Callback
            local num = param2.HoldToConfirm == true and 1 or tonumber(param2.HoldToConfirm)
            local cloned = table.clone(param2)
            cloned._gated = true
            local buttonElem
            local str = tostring(param2.Name or 'Button')
            local flag, num2 = false, 0

            local function helperFn(param3)
                flag = param3
                num2 += 1
                if not buttonElem then
                    return
                end
                buttonElem._title.Text = param3 and tostring(type(param2.Confirm) == 'string' and param2.Confirm or 'Click again to confirm') or str
                tween(buttonElem._title, { TextColor3 = param3 and Theme.Warning or buttonElem._titleColor }, 0.15)
            end

            cloned.Callback = function()
                if num then
                    return
                end
                if flag then
                    helperFn(false)
                    safeCall(callback)
                    return
                end
                helperFn(true)
                local val = num2
                task.delay(tonumber(param2.ConfirmTimeout) or 3, function()
                    if flag and num2 == val then
                        helperFn(false)
                    end
                end)
            end

            buttonElem = param:Button(cloned)
            local settext = buttonElem.SetText

            buttonElem.SetText = function(value, param3)
                str = tostring(param3)
                if not flag then
                    settext(value, param3)
                end
            end

            function buttonElem:Disarm()
                if flag then
                    helperFn(false)
                end
            end

            if num then
                local fillhost = buttonElem._fillHost
                local frame = create('Frame', {
                    Size = UDim2.fromScale(0, 1),
                    BackgroundColor3 = Theme.Accent,
                    BackgroundTransparency = 0.7,
                    BorderSizePixel = 0,
                    ZIndex = 0,
                    Parent = fillhost
                })
                local num3 = 0

                local function helperFn2()
                    num3 += 1
                    tween(frame, { Size = UDim2.fromScale(0, 1) }, 0.2, Enum.EasingStyle.Quint)
                end

                local frame2 = buttonElem._frame
                frame2.InputBegan:Connect(function(input)
                    if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
                        return
                    end
                    if buttonElem.Disabled or buttonElem._dependDisabled then
                        return
                    end
                    num3 += 1
                    local val = num3
                    frame.Size = UDim2.fromScale(0, 1)
                    tween(frame, { Size = UDim2.fromScale(1, 1) }, num, Enum.EasingStyle.Linear)
                    task.delay(num, function()
                        if num3 == val and not buttonElem._destroyed then
                            num3 += 1
                            tween(frame, { BackgroundTransparency = 0.45 }, 0.08)
                            task.delay(0.12, function()
                                frame.BackgroundTransparency = 0.7
                                tween(frame, { Size = UDim2.fromScale(0, 1) }, 0.25, Enum.EasingStyle.Quint)
                            end)
                            safeCall(callback)
                        end
                    end)
                end)
                frame2.InputEnded:Connect(function(input)
                    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                        helperFn2()
                    end
                end)
                frame2.MouseLeave:Connect(helperFn2)
            end

            return buttonElem
        end

        function Library._color(param)
            if type(param) == 'string' then
                local entry = Library._toneTags[string.lower(param)]
                if entry then
                    return Theme[entry]
                end
            end

            return parseColorInput(param)
        end

        function Library._rich(param)
            param = tostring(param == nil and '' or param)

            if not string.find(param, '<', 1, true) then
                return param
            end

            return (string.gsub(param, '<(/?)(%a+%d*)>', function(param2, param3)
                local entry = Library._toneTags[string.lower(param3)]
                if not entry then
                    return nil
                end
                if param2 == '/' then
                    return '</font>'
                end
                return '<font color="' .. colorToHexUpper(Theme[entry]) .. '">'
            end))
        end

        function Library.Colorize(...)
            local tbl = { ... }

            if tbl[1] == Library then
                table.remove(tbl, 1)
            end

            local str, entry = tostring(tbl[1] == nil and '' or tbl[1]), tbl[2]
            local entry2 = type(entry) == 'string' and Library._toneTags[string.lower(entry)]

            if entry2 then
                return '<' .. entry2 .. '>' .. str .. '</' .. entry2 .. '>'
            end

            local val = parseColorInput(entry)

            if not val then
                return str
            end

            return '<font color="' .. colorToHexUpper(val) .. '">' .. str .. '</font>'
        end

        function Library:SetCornerRadius(value, param)
            value = math.clamp(math.floor((tonumber(value) or 10) + 0.5), 0, 20)
            Library.Roundness = value / 10

            for key, val in pairs(Library._cornerBases) do
                if not key.Parent then
                    Library._cornerBases[key] = nil
                else
                    local udim = UDim.new(0, math.floor(val * Library.Roundness + 0.5))
                    if param then
                        key.CornerRadius = udim
                    else
                        tween(key, { CornerRadius = udim }, 0.25, Enum.EasingStyle.Quint)
                    end
                end
            end

            return value
        end

        function Library:GetCornerRadius()
            return math.floor(Library.Roundness * 10 + 0.5)
        end

        function Library:SetTheme(value, param)
            if type(value) == 'string' then
                local preset = Library.ThemePresets[value]
                if not preset then
                    return false
                end
                Library.ThemeName = value
                value = preset
            elseif type(value) ~= 'table' then
                return false
            end

            local flag = false
            local aliases = {
                ['Card Outline'] = 'Outline',
                CardOutline = 'Outline',
                ['Tab Structure'] = 'TabStructure',
                Sidebar = 'TabStructure',
                ['Surface'] = 'Surface2',
            }
            for alias, target in pairs(aliases) do
                if value[alias] ~= nil and value[target] == nil then
                    value[target] = value[alias]
                end
            end

            for idx, item in ipairs(THEME_KEYS) do
                local val = parseColorInput(value[item])
                if val and val ~= Theme[item] then
                    Theme[item] = val
                    flag = true
                end
            end

            if not flag then
                return true
            end

            rebuildThemeLookup()
            sweepThemedObjects()
            transitionTheme(param and 0 or 0.3)

            for _, grad in ipairs(Library._accentGradients or {}) do
                pcall(function() grad:Update() end)
            end

            for key, val in pairs(themeCallbacks) do
                if typeof(key) ~= 'Instance' or key.Parent then
                    pcall(val)
                end
            end

            for idx, item in ipairs(Library._themeListeners) do
                pcall(item)
            end

            return true
        end

        function Library:GetTheme()
            local tbl = {}

            for idx, item in ipairs(THEME_KEYS) do
                tbl[item] = Theme[item]
            end

            return tbl
        end

        function Library:SetDefaultTheme(value)
            Library.DefaultTheme = value

            if value == nil then
                return true
            end

            local flag = false

            for idx, win in ipairs(Library.Windows) do
                if not win._destroyed then
                    if win:GetDefaultTheme() then
                        return true
                    end
                    flag = true
                end
            end

            return Library:SetTheme(value, not flag)
        end

        function Library:GetDefaultTheme()
            return Library.DefaultTheme
        end

        local function getThemesFolder(win)
            return win.ConfigFolder .. '/themes'
        end

        function Window:SaveTheme(param)
            if not hasFileApi() then
                return false, 'file API unavailable'
            end

            if type(param) ~= 'string' or param == '' then
                return false, 'theme needs a name'
            end

            ensureFolder(self.ConfigFolder)
            ensureFolder(getThemesFolder(self))
            local tbl = {}

            for idx, item in ipairs(THEME_KEYS) do
                tbl[item] = colorToHexUpper(Theme[item])
            end

            return pcall(function()
                writefile(getThemesFolder(self) .. '/' .. param .. '.json', HttpService:JSONEncode(tbl))
            end)
        end

        function Window:LoadTheme(param, param2)
            if Library.ThemePresets[param] then
                return Library:SetTheme(param, param2)
            end

            local content = readTextFile(getThemesFolder(self) .. '/' .. tostring(param) .. '.json')

            if not content then
                return false, 'no theme named ' .. tostring(param)
            end

            local ok, res = pcall(function()
                return HttpService:JSONDecode(content)
            end)

            if not ok or type(res) ~= 'table' then
                return false, 'theme is not valid JSON'
            end

            Library.ThemeName = param
            return Library:SetTheme(res, param2)
        end

        function Window:DeleteTheme(param)
            if not hasFileApi() or type(delfile) ~= 'function' then
                return false, 'file API unavailable'
            end

            local str = getThemesFolder(self) .. '/' .. tostring(param) .. '.json'

            if not isfile(str) then
                return false, 'no theme named ' .. tostring(param)
            end

            delfile(str)

            if self:GetDefaultTheme() == param then
                self:SetDefaultTheme(nil)
            end

            return true
        end

        function Window:ListThemes()
            local tbl = {}

            if type(listfiles) ~= 'function' or type(isfolder) ~= 'function' or not isfolder(getThemesFolder(self)) then
                return tbl
            end

            for idx, item in ipairs(listfiles(getThemesFolder(self))) do
                local val = item:match('([^/\\]+)%.json$')
                if val then
                    table.insert(tbl, val)
                end
            end

            table.sort(tbl)
            return tbl
        end

        function Window:GetDefaultTheme()
