                return false, 'file API unavailable'
            end

            ensureFolder(self.ConfigFolder)
            ensureFolder(getThemesFolder(self))
            local str = getThemesFolder(self) .. '/default.txt'

            if value == nil or value == '' then
                if isfile(str) and type(delfile) == 'function' then
                    pcall(delfile, str)
                end
                return true
            end

            return pcall(writefile, str, tostring(value))
        end

        function Window:_applyDefaultTheme()
            local val = self:GetDefaultTheme()

            if val then
                local ok, res = pcall(self.LoadTheme, self, val, true)
