        function Window:_trimBackground(param)
            return (tostring(param or ''):match('^%s*(.-)%s*$'))
        end

        function Window:_resolveBackground(param)
            param = self:_trimBackground(param)
            local entry = Library.BackgroundPresets[param]

            if entry then
                return entry
            end

            if param:match('^%d+$') then
                return 'rbxassetid://' .. param
            end

            if param:match('^rbxassetid://%d+') or param:match('^rbxasset://') or param:match('^rbxthumb://') or param:match('^https?://www%.roblox%.com/asset') then
                return param
            end

            local cond = hasFileApi() and typeof(getcustomasset) == 'function'

            if param:match('^https?://') then
                if not cond then
                    return nil, 'web images need writefile and getcustomasset'
                end
                local cond2 = param:match('^[^?#]+') or param
                local val = (cond2:match('%.(%w+)$') or 'png'):lower()
                if not Library._imageExtensions[val] then
                    val = 'png'
                end
                local val2 = (cond2:gsub('^https?://', ''):gsub('[^%w]', '_')):sub(-60)
                local str = self:_backgroundFolder() .. '/cache'
                local str2 = str .. '/' .. val2 .. '_' .. #param .. '.' .. val
                if not isfile(str2) then
                    local ok2, res2 = pcall(function()
                        local requestVal = (syn and syn.request) or http_request or request
                        if requestVal then
                            local val4 = requestVal({ Url = param, Method = 'GET' })
                            return val4 and val4.Body
                        end
                        return game:HttpGet(param, true)
                    end)
                    if not ok2 or type(res2) ~= 'string' or #res2 < 128 then
                        return nil, 'could not download the image'
                    end
                    local val3 = res2:sub(1, 64):lower()
                    if val3:find('<!doctype') or val3:find('<html') then
                        return nil, 'that link is a web page, not an image'
                    end
                    ensureFolder(str)
                    if not pcall(writefile, str2, res2) then
                        return nil, 'could not save the image'
                    end
                end
                local ok, res = pcall(getcustomasset, str2)
                if ok and type(res) == 'string' and res ~= '' then
                    return res
                end
                pcall(delfile, str2)
                return nil, 'the downloaded file is not an image'
            end

            if cond then
                for idx, item in ipairs({ self:_backgroundFolder() .. '/' .. param, param }) do
                    if isfile(item) then
                        local ok, res = pcall(getcustomasset, item)
                        if ok and type(res) == 'string' and res ~= '' then
                            return res
                        end
                        return nil, 'could not load ' .. param
                    end
                end
            end

            return nil, 'no image called ' .. param
        end

        function Window:SetBackground(value)
            self._backgroundGeneration += 1
            local backgroundgeneration = self._backgroundGeneration
            local backgroundimage = self._backgroundImage
            value = value ~= false and self:_trimBackground(value) or ''

            if value == '' or value == 'None' then
                self.Background = nil
                tween(backgroundimage, { ImageTransparency = 1 }, 0.25)
                task.delay(0.25, function()
                    if self._backgroundGeneration == backgroundgeneration then
                        backgroundimage.Visible = false
                        backgroundimage.Image = ''
                    end
                end)
                self:SetTransparent(self.Transparent)
                return true
            end

            local val, val2 = self:_resolveBackground(value)

            if self._backgroundGeneration ~= backgroundgeneration or self._destroyed then
                return false, 'replaced by a newer background'
            end

            if not val then
                return false, val2
            end

            self.Background = value
            backgroundimage.Image = val
            backgroundimage.Visible = true
            tween(backgroundimage, { ImageTransparency = self.BackgroundTransparency }, 0.3)
            self:SetTransparent(self.Transparent)
            return true
        end

        function Window:GetBackground()
            return self.Background
        end

        function Window:SetBackgroundTransparency(value)
            self.BackgroundTransparency = math.clamp(tonumber(value) or 0.35, 0, 1)

            if self.Background then
                tween(self._backgroundImage, { ImageTransparency = self.BackgroundTransparency }, 0.15)
            end
        end

        function Window:ListBackgrounds()
            local cloned = table.clone(Library.BackgroundPresetOrder)
            local val = self:_backgroundFolder()

            if type(listfiles) == 'function' and type(isfolder) == 'function' and isfolder(val) then
                local tbl = {}
                for idx, item in ipairs(listfiles(val)) do
                    local val2 = item:match('([^/]+)$')
                    local cond = val2 and val2:match('%.(%w+)$')
                    if cond and Library._imageExtensions[cond:lower()] then
                        table.insert(tbl, val2)
                    end
                end
                table.sort(tbl)
                for idx, item in ipairs(tbl) do
                    table.insert(cloned, item)
                end
            end

            return cloned
        end

