        local function formatDuration(seconds)
            seconds = math.max(math.floor(seconds), 0)
            local num = math.floor(seconds / 86400)
            local num2 = math.floor(seconds / 3600) % 24
            local num3 = math.floor(seconds / 60) % 60
            if num > 0 then
                return string.format('%dd %dh', num, num2)
            elseif num2 > 0 then
                return string.format('%dh %dm', num2, num3)
            elseif num3 > 0 then
                return string.format('%dm %ds', num3, seconds % 60)
            end
            return string.format('%ds', seconds)
        end

        local function shortenJobId(jobId)
