        function Container:_columns()
            if self._columnSet then
                return self._columnSet
            end

            local b_pad = self.List:FindFirstChildOfClass('UIPadding')

            if b_pad then
                b_pad.PaddingBottom = UDim.new(0, 0)
                b_pad:SetAttribute('SpaceB', 0)
            end

            local columns = create('Frame', {
                Name = 'Columns',
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                LayoutOrder = 100000,
                Parent = self.List
            })

            local val = Library._space(create('UIListLayout', {
                FillDirection = Enum.FillDirection.Horizontal,
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 12),
                Parent = columns
            }), 12)

            local function helperFn(param)
                local scrollFrame = create('ScrollingFrame', {
                    Name = param == 1 and 'Left' or 'Right',
                    Size = UDim2.new(0.5, -6, 1, 0),
                    BackgroundTransparency = 1,
                    BorderSizePixel = 0,
                    ScrollBarThickness = 2,
                    ScrollBarImageColor3 = Theme.StrokeHover,
                    ScrollBarImageTransparency = 0.35,
                    ScrollingDirection = Enum.ScrollingDirection.Y,
                    AutomaticCanvasSize = Enum.AutomaticSize.Y,
                    CanvasSize = UDim2.new(),
                    LayoutOrder = param,
                    Active = true,
                    Parent = columns
                })
                Library._space(addPadding(scrollFrame, 6, 6, 4, 24), { 6, 6, 4, 24 })
                Library._space(create('UIListLayout', {
                    SortOrder = Enum.SortOrder.LayoutOrder,
                    Padding = UDim.new(0, 10),
                    Parent = scrollFrame
                }), 10)
                return scrollFrame
            end

            local tbl = {
                Holder = columns,
                Left = helperFn(1),
                Right = helperFn(2),
                Counts = { 0, 0 },
                Stacked = false
            }

            local window = self.Window

            local function helperFn2()
                local num = columns.AbsoluteSize.X / window.Scale.Scale
                if num <= 0 then
                    return
                end
                local cond = num < STACK_BREAKPOINT_WIDTH
                local offset = val.Padding.Offset
                if cond == tbl.Stacked and offset == tbl.Gap then
                    return
                end
                tbl.Stacked = cond
                tbl.Gap = offset
                val.FillDirection = cond and Enum.FillDirection.Vertical or Enum.FillDirection.Horizontal
                if cond then
                    if b_pad then
                        b_pad.PaddingBottom = UDim.new(0, 24)
                        b_pad:SetAttribute('SpaceB', 24)
                    end
                    self.List.ScrollingEnabled = true
                    self.List.ScrollBarThickness = 2
                    self.List.AutomaticCanvasSize = Enum.AutomaticSize.Y
                    columns.AutomaticSize = Enum.AutomaticSize.Y
                    columns.Size = UDim2.new(1, 0, 0, 0)
                    tbl.Left.Size = UDim2.new(1, 0, 0, 0)
                    tbl.Right.Size = UDim2.new(1, 0, 0, 0)
                    tbl.Left.AutomaticSize = Enum.AutomaticSize.Y
                    tbl.Right.AutomaticSize = Enum.AutomaticSize.Y
                    tbl.Left.ScrollingEnabled = false
                    tbl.Right.ScrollingEnabled = false
                    tbl.Left.ScrollBarThickness = 0
                    tbl.Right.ScrollBarThickness = 0
                else
                    if b_pad then
                        b_pad.PaddingBottom = UDim.new(0, 0)
                        b_pad:SetAttribute('SpaceB', 0)
                    end
                    self.List.ScrollingEnabled = false
                    self.List.ScrollBarThickness = 0
                    self.List.AutomaticCanvasSize = Enum.AutomaticSize.None
                    self.List.CanvasSize = UDim2.new()
                    columns.AutomaticSize = Enum.AutomaticSize.None
                    columns.Size = UDim2.fromScale(1, 1)
                    local udim = UDim2.new(0.5, -offset / 2, 1, 0)
                    tbl.Left.Size = udim
                    tbl.Right.Size = udim
                    tbl.Left.AutomaticSize = Enum.AutomaticSize.None
                    tbl.Right.AutomaticSize = Enum.AutomaticSize.None
                    tbl.Left.ScrollingEnabled = true
                    tbl.Right.ScrollingEnabled = true
                    tbl.Left.ScrollBarThickness = 2
                    tbl.Right.ScrollBarThickness = 2
                    tbl.Left.AutomaticCanvasSize = Enum.AutomaticSize.Y
                    tbl.Right.AutomaticCanvasSize = Enum.AutomaticSize.Y
                    tbl.Left.CanvasSize = UDim2.new()
                    tbl.Right.CanvasSize = UDim2.new()
                end
            end

            columns:GetPropertyChangedSignal('AbsoluteSize'):Connect(helperFn2)
            val:GetPropertyChangedSignal('Padding'):Connect(helperFn2)
            task.defer(helperFn2)
            self._columnSet = tbl
            return tbl
        end

