            })

            local switchBtn, switchIcon, switchScale
            local function switchSideAction()
                if flag2 then return end
                currentSide = (currentSide == 1 or currentSide == 'Left') and 2 or 1
                local targetCol = currentSide == 1 and val.Left or val.Right
                val.Counts[currentSide] = (val.Counts[currentSide] or 0) + 1

                if switchIcon then
