                })
                local frame6 = create('Frame', {
                    Size = UDim2.fromOffset(0, 0),
                    BackgroundTransparency = 1,
                    Visible = false,
                    Parent = button
                })
                local frame7 = create('Frame', {
                    Size = UDim2.new(1, 0, 0, 0),
                    AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundTransparency = 1,
                    Visible = false,
                    Parent = frame4
                })
                Library._space(addPadding(frame7, 0, 0, 4, 6), { 0, 0, 4, 6 })
                Library._space(create('UIListLayout', {
                    SortOrder = Enum.SortOrder.LayoutOrder,
                    Padding = UDim.new(0, 0),
                    Parent = frame7
                }), 0)
                local val3 = setmetatable({
                    Name = tbl.Name .. ' \u{203a} ' .. name,
                    Title = name,
                    Window = window,
                    Parent = val,
                    Tabbox = tbl,
                    List = frame7,
                    Frame = frame,
                    _frame = frame,
                    _order = 0,
                    _groupbox = true,
                    _metrics = DENSITY_METRICS.Row,
                    _items = {},
                    _userVisible = false,
                    _button = button,
                    _label = label,
                    _icon = imageLabel,
                    _bar = frame6
                }, Container)

                function val3:IsCollapsed()
                    return tbl.Current ~= val3
                end

                function val3:Expand()
                    tbl:SelectTab(val3)
                end

                function val3:Collapse() end

                function val3:Select()
                    tbl:SelectTab(val3)
                end

                function val3:SetTitle(value)
                    val3.Title = tostring(value)
                    val3.Name = tbl.Name .. ' \u{203a} ' .. val3.Title
                    label.Text = val3.Title
                end

                function val3:Destroy()
                    for idx = #val3._items, 1, -1 do
                        local entry = val3._items[idx]
                        if type(entry.Destroy) == 'function' then
                            entry:Destroy()
                        end
                    end
                    val3._destroyed = true
                    local foundIdx = table.find(tbl.Tabs, val3)
                    if foundIdx then
                        table.remove(tbl.Tabs, foundIdx)
                    end
                    foundIdx = table.find(val._groupboxes, val3)
                    if foundIdx then
                        table.remove(val._groupboxes, foundIdx)
                    end
                    button:Destroy()
                    frame7:Destroy()
                    helperFn2()
                    if tbl.Current == val3 then
                        tbl.Current = nil
                        if tbl.Tabs[1] then
                            tbl:SelectTab(tbl.Tabs[1])
                        end
                    end
                    window._controlsDirty = true
                end

                button.MouseEnter:Connect(function()
                    if tbl.Current ~= val3 then
                        tween(label, { TextColor3 = Theme.Text }, 0.12)
                        if imageLabel then
                            tween(imageLabel, { ImageColor3 = Theme.Text }, 0.12)
                        end
                    end
                end)
                button.MouseLeave:Connect(function()
                    if tbl.Current ~= val3 then
                        tween(label, { TextColor3 = Theme.Muted2 }, 0.18)
                        if imageLabel then
                            tween(imageLabel, { ImageColor3 = Theme.Muted2 }, 0.18)
                        end
                    end
                end)
                button.Activated:Connect(function()
                    tbl:SelectTab(val3)
                end)
                table.insert(tbl.Tabs, val3)
                table.insert(val._groupboxes, val3)
                helperFn2()
                if not tbl.Current then
                    tbl:SelectTab(val3)
                else
                    helperFn3(val3, true)
                end
                return val3
            end

            tbl.CreateTab = tbl.AddTab
            tbl.Tab = tbl.AddTab
            tbl.Side = side

            function tbl:SwitchSide()
                switchTabboxSideAction()
            end

            function tbl:SetSide(target)
                local targetNum = (target == 'Left' or target == 1) and 1 or 2
                if targetNum ~= currentSide then
                    switchTabboxSideAction()
                end
            end

            function tbl:SetTitle(value)
                tbl.Name = tostring(value)
                for idx, tab in ipairs(tbl.Tabs) do
                    tab.Name = tbl.Name .. ' \u{203a} ' .. tab.Title
                end
            end

            function tbl:IsVisible()
                return tbl._userVisible
            end

            function tbl:SetVisible(value)
                value = value and true or false
                if value == tbl._userVisible then
                    return
                end
                tbl._userVisible = value
                if tbl.Current then
                    if not value then
                        helperFn(tbl.Current)
                    end
                    tbl.Current._userVisible = value
                end
                frame.Visible = value
                window._controlsDirty = true
            end

            if not tbl._userVisible then
                frame.Visible = false
            end

            function tbl:Destroy()
