                    tbl.Tabs[idx]:Destroy()
                end
                val2.Counts[side] = math.max(val2.Counts[side] - 1, 0)
                tbl._destroyed = true
                window._controlsDirty = true
                frame:Destroy()
            end

            for idx, item in ipairs(opts.Tabs or {}) do
                tbl:AddTab(item)
            end

            return tbl
        end

        Container.CreateTabbox = Container.Tabbox
        Container.AddTabbox = Container.Tabbox

        function Container:AddLeftTabbox(opts)
            opts = normalizeOpts(opts, { Title = 'Name' })
            opts.Side = 'Left'
            return self:Tabbox(opts)
        end

        function Container:AddRightTabbox(opts)
