            opts.Side = 'Right'
            return self:Tabbox(opts)
        end

        function Container:ButtonRow(param)
            local buttons = type(param) == 'table' and (param.Buttons or param) or {}
            local compact = getMetrics(self).Compact
            local num = isTouch and 34 or 30
            local card = createElementCard(self, 'Frame', num + (compact and 8 or 14), { _noHairline = true })
            local num2 = compact and 14 or 7

            local frame = create('Frame', {
                Position = UDim2.fromOffset(num2, compact and 4 or 7),
                Size = UDim2.new(1, -num2 * 2, 0, num),
                BackgroundTransparency = 1,
                Parent = card
            })

            local num3 = math.max(#buttons, 1)
            local elem = { Buttons = {} }
            local tbl = {}

            for idx, item in ipairs(buttons) do
                if type(item) == 'string' then
                    item = { Name = item }
                end
                local name = item.Name or item.Title or 'Button'
                table.insert(tbl, name)
                local chipBtn, chipBtn2 = createActionChip(frame, name, {
                    Position = UDim2.new((idx - 1) / num3, (idx - 1) * 6 / num3, 0, 0),
                    Size = UDim2.new(1 / num3, -6 * (num3 - 1) / num3, 1, 0)
                }, function()
                    safeCall(item.Callback)
                end)
                chipBtn2.TextSize = 12
                if item.Style == 'Primary' then
                    chipBtn2.FontFace = Fonts.SemiBold
                    tween(chipBtn, { BackgroundColor3 = Theme.Accent, BackgroundTransparency = 0 }, 0)
                    tween(chipBtn2, { TextColor3 = Theme.AccentDark }, 0)
                elseif item.Style == 'Danger' then
                    tween(chipBtn2, { TextColor3 = Theme.Error }, 0)
                end
                elem.Buttons[idx] = { Button = chipBtn, Label = chipBtn2 }
            end

            function elem:SetText(value, param2)
                local entry = elem.Buttons[value]
                if entry then
                    entry.Label.Text = tostring(param2)
                end
            end

            return registerElement(self, {
                Name = table.concat(tbl, ' '),
                Visible = not (type(param) == 'table' and param.Visible == false)
            }, elem, card, 'ButtonRow')
        end

        local function createActionInputRow(container, placeholder, actionIcon, onSubmit)
            local num = isTouch and 34 or 30
            local card = createElementCard(container, 'Frame', num + 8, { _noHairline = true })
            local num2 = getMetrics(container).Compact and 14 or 7
            local textBox
            local chipBtn = actionIcon and createActionChip(card, actionIcon, {
                AnchorPoint = Vector2.new(1, 0),
                Position = UDim2.new(1, -num2, 0, 4),
                Size = UDim2.fromOffset(0, num),
                AutomaticSize = Enum.AutomaticSize.X
            }, function()
                safeCall(onSubmit, textBox.Text)
            end)
            local frame = create('Frame', {
                Position = UDim2.fromOffset(num2, 4),
                Size = UDim2.new(1, -(num2 * 2 + (chipBtn and 70 or 0)), 0, num),
                BackgroundColor3 = Theme.Background,
                BorderSizePixel = 0,
                Parent = card
            })
            addCorner(frame, UDim.new(0, 8))
            local stroke = addStroke(frame, Theme.Stroke, 0, 1)
            textBox = create('TextBox', {
                Position = UDim2.fromOffset(8, 0),
                Size = UDim2.new(1, -16, 1, 0),
                BackgroundTransparency = 1,
                Text = '',
                PlaceholderText = placeholder,
                PlaceholderColor3 = Theme.Muted,
                TextColor3 = Theme.Text,
                TextSize = 13,
                FontFace = Fonts.Regular,
                TextXAlignment = Enum.TextXAlignment.Center,
                TextTruncate = Enum.TextTruncate.AtEnd,
                ClearTextOnFocus = false,
                Parent = frame
            })
            onThemeChange(frame, function()
                frame.BackgroundColor3 = Theme.Background
                stroke.Color = textBox:IsFocused() and Theme.Accent or Theme.Stroke
                textBox.PlaceholderColor3 = Theme.Muted
                textBox.TextColor3 = Theme.Text
            end)
            frame.MouseEnter:Connect(function()
                if not textBox:IsFocused() and not isLastInputTouch() then
                    tween(stroke, { Color = Theme.StrokeHover, Transparency = 0 }, 0.15)
                end
            end)
            frame.MouseLeave:Connect(function()
                if not textBox:IsFocused() then
                    tween(stroke, { Color = Theme.Stroke, Transparency = 0 }, 0.25)
                end
            end)
            textBox.Focused:Connect(function()
                tween(stroke, { Color = Theme.Accent, Transparency = 0 }, 0.15)
            end)
            textBox.FocusLost:Connect(function(enterPressed)
                tween(stroke, { Color = Theme.Stroke, Transparency = 0 }, 0.2)
                if enterPressed and textBox.Text ~= '' then
                    safeCall(onSubmit, textBox.Text)
                end
            end)
            if chipBtn then
                local function helperFn()
                    local num3 = chipBtn.AbsoluteSize.X / container.Window.Scale.Scale
                    frame.Size = UDim2.new(1, -(num2 * 2 + num3 + 6), 0, num)
                end

                chipBtn:GetPropertyChangedSignal('AbsoluteSize'):Connect(helperFn)
                task.defer(helperFn)
            end
            return registerElement(container, { Name = placeholder }, {
                Get = function()
                    return textBox.Text
                end,
                Set = function(selfArg, value)
                    textBox.Text = tostring(value or '')
                end
            }, card, 'ActionInput')
        end

        local function trimString(str)
            return (tostring(str or ''):match('^%s*(.-)%s*$'))
        end

        local function createListBox(container, items, emptyText, visibleRows, onSelect, multi, searchable)
            local num = isTouch and 30 or 24
            local num2 = num * (visibleRows or 5) + 8
            local card = createElementCard(container, 'Frame', num2 + 4, {})
            local num3 = getMetrics(container).Compact and 14 or 7
            local frame = create('Frame', {
                Position = UDim2.fromOffset(num3, 2),
                Size = UDim2.new(1, -num3 * 2, 0, num2),
                BackgroundColor3 = Theme.Background,
                BorderSizePixel = 0,
                ClipsDescendants = true,
                Parent = card
            })
            addCorner(frame, UDim.new(0, 6))
            addStroke(frame)
            local scrollFrame = create('ScrollingFrame', {
                Position = UDim2.fromOffset(4, 4),
                Size = UDim2.new(1, -8, 1, -8),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ScrollBarThickness = 3,
                ScrollBarImageColor3 = Theme.Stroke,
                CanvasSize = UDim2.new(),
                AutomaticCanvasSize = Enum.AutomaticSize.Y,
                Parent = frame
            })
            create('UIListLayout', { SortOrder = Enum.SortOrder.LayoutOrder, Parent = scrollFrame })
            local label = createLabel({
                Size = UDim2.new(1, 0, 0, num),
                Text = 'no configs yet',
                TextColor3 = Theme.Muted,
                TextSize = 13,
                TextXAlignment = Enum.TextXAlignment.Center,
                Parent = frame
            })
            local val, tbl = nil, {}

            local function helperFn(param)
                for key, val2 in pairs(tbl) do
                    local cond = key == val
                    tween(val2.Button, { BackgroundTransparency = cond and 0.82 or 1 }, param and 0 or 0.15)
                    tween(val2.Label, { TextColor3 = cond and Theme.Accent or Theme.Text }, param and 0 or 0.15)
                    val2.Bar.Visible = cond
                    local str = onSelect and onSelect(key) or ''
                    val2.Tags.Text = str
                    val2.Label.Size = UDim2.new(1, -(18 + val2.Tags.TextBounds.X + (str ~= '' and 6 or 0)), 1, 0)
                end
            end

            local function helperFn2(param)
                if val == param then
                    return
                end
                val = param
                helperFn()
                safeCall(multi, param)
            end

            local elem = {}

            function elem:Refresh(param)
                for key, val2 in pairs(tbl) do
                    val2.Button:Destroy()
                end
                tbl = {}
                for idx, item in ipairs(param or {}) do
                    local button = create('TextButton', {
                        Size = UDim2.new(1, -4, 0, num),
                        BackgroundColor3 = Theme.Accent,
                        BackgroundTransparency = 1,
                        Text = '',
                        AutoButtonColor = false,
                        LayoutOrder = idx,
                        Parent = scrollFrame
                    })
                    addCorner(button, UDim.new(0, 4))
                    local frame2 = create('Frame', {
                        Position = UDim2.new(0, 0, 0.5, -6),
                        Size = UDim2.fromOffset(2, 12),
                        BackgroundColor3 = Theme.Accent,
                        BorderSizePixel = 0,
                        Visible = false,
                        Parent = button
                    })
                    local label2 = createLabel({
                        Position = UDim2.fromOffset(10, 0),
                        Size = UDim2.new(1, -18, 1, 0),
                        Text = item,
                        TextSize = 13,
                        TextTruncate = Enum.TextTruncate.AtEnd,
                        Parent = button
                    })
                    local label3 = createLabel({
                        AnchorPoint = Vector2.new(1, 0),
                        Position = UDim2.new(1, -8, 0, 0),
                        Size = UDim2.new(0, 0, 1, 0),
                        AutomaticSize = Enum.AutomaticSize.X,
                        TextColor3 = Theme.Muted,
                        TextSize = 12,
                        TextXAlignment = Enum.TextXAlignment.Right,
                        Parent = button
                    })
                    local num4 = 0
                    button.MouseButton1Click:Connect(function()
                        if val == item and os.clock() - num4 < 0.35 then
                            num4 = 0
                            safeCall(searchable, item)
                            return
                        end
                        num4 = os.clock()
                        helperFn2(item)
                    end)
                    button.MouseEnter:Connect(function()
                        if val ~= item then
                            tween(button, { BackgroundTransparency = 0.93 }, 0.1)
                        end
                    end)
                    button.MouseLeave:Connect(function()
                        if val ~= item then
                            tween(button, { BackgroundTransparency = 1 }, 0.15)
                        end
                    end)
                    tbl[item] = {
                        Button = button,
                        Label = label2,
                        Tags = label3,
                        Bar = frame2
                    }
                end
                if val and not tbl[val] then
                    helperFn2(nil)
                end
                label.Visible = next(tbl) == nil
                helperFn(true)
            end

            function elem:Get()
                return val
            end

            function elem:Set(value)
                helperFn2(value and tbl[value] and value or nil)
            end

            function elem:Repaint()
                helperFn(true)
            end

            elem:Refresh(items)
            elem:Set(emptyText)
            return registerElement(container, { Name = 'Configs' }, elem, card, 'PickList')
        end

        local function ensureManagerGroupbox(target, opts, defaultName, defaultIcon)
            if target._groupbox then
                return target
            end
            local groupbox = target:Groupbox({
                Name = opts.Name or defaultName,
                Icon = opts.Icon or defaultIcon,
                Side = opts.Side
            })
            groupbox._manager = true
            return groupbox
        end

        function Container:ConfigManager(opts)
            opts = normalizeOpts(opts, { Title = 'Name' })
            local groupbox = ensureManagerGroupbox(self, opts, 'Configs', 'folder')
            local window = self.Window
            local tbl = {}
            local listBox, val, dropdown

            local function helperFn(param, param2, param3)
                window:Notify({
                    Title = param2,
                    Content = param3,
                    Type = param and 'Success' or 'Error',
                    Duration = 3
                })
            end

            local toggle

            local function helperFn2()
                if not val then
                    return
                end
                local count = #window:ListConfigs()
                val:Set(('%d saved  \u{b7}  loaded: %s  \u{b7}  auto: %s'):format(count, window.LoadedConfig or 'none', window:GetAutoload() or 'none'))
                listBox:Repaint()
                if toggle then
                    local val6 = listBox:Get()
                    toggle:Set(val6 ~= nil and window:GetAutoload() == val6, true)
                end
            end

            local function helperFn3()
                local val6 = listBox:Get()
                if not val6 then
                    helperFn(false, 'No config selected', 'Pick one from the list first')
                end
                return val6
            end

            local val2 = window:ListConfigs()
            local loadedconfig = window.LoadedConfig or window:GetAutoload()
            local val3

            listBox = createListBox(groupbox, val2, table.find(val2, loadedconfig) and loadedconfig or nil, opts.Rows, function(param)
                local tbl2 = {}
                if param == window.LoadedConfig then
                    table.insert(tbl2, 'loaded')
                end
                if param == window:GetAutoload() then
                    table.insert(tbl2, 'auto')
                end
                return table.concat(tbl2, ' \u{b7} ')
            end, function(param)
                if val3 then
                    val3:Set(param or '')
                end
                helperFn2()
            end, function(param)
                tbl:Load(param)
            end)

            val = groupbox:Label('0 saved')
            groupbox:Label('Config Name:')

            val3 = createActionInputRow(groupbox, opts.Placeholder or 'Type config name here...', nil, function(param)
                tbl:Create(param)
            end)

            groupbox:ButtonRow({
                {
                    Name = 'Save',
                    Callback = function()
                        tbl:Save()
                    end
                },
                {
                    Name = 'Load',
                    Callback = function()
                        tbl:Load()
                    end
                }
            })

            groupbox:ButtonRow({
                {
                    Name = 'Delete',
                    Style = 'Danger',
                    Callback = function()
                        tbl:Delete()
                    end
                },
                {
                    Name = 'Refresh',
                    Callback = function()
                        tbl:Refresh()
                    end
                }
            })

            toggle = groupbox:Toggle({
                Name = 'Auto Load Config',
                Desc = 'Loads the selected config on launch',
                Callback = function(value)
                    local val6 = listBox:Get()
                    if not val6 then
                        helperFn(false, 'No config selected', 'Pick one from the list first')
                    elseif value ~= (window:GetAutoload() == val6) then
                        if value then
                            tbl:SetAutoload(val6)
                        else
                            tbl:ClearAutoload()
                        end
                    end
                    helperFn2()
                end
            })

            groupbox:Divider({ Text = 'more' })

            groupbox:ButtonRow({
                {
                    Name = 'Rename',
                    Callback = function()
                        tbl:Rename(nil, val3:Get())
                    end
                },
                {
                    Name = 'Reset',
                    Style = 'Danger',
                    Callback = function()
                        tbl:Reset()
                    end
                }
            })

            dropdown = groupbox:Dropdown({
                Name = 'Autoload mode',
                Stacked = true,
                Options = { 'All accounts', 'This account' },
                Default = window:GetAutoloadMode() == 'Account' and 'This account' or 'All accounts',
                AllowNone = false,
                Callback = function(value)
                    tbl:SetAutoloadMode(value == 'This account' and 'Account' or 'Global')
                end
            })

            groupbox:Divider({ Text = 'share' })

            groupbox:Button({
                Name = 'Copy code',
                Callback = function()
                    tbl:Export()
                end
            })

            local val4 = createActionInputRow(groupbox, 'paste a config code...', nil, function(param)
                tbl:Import(param)
            end)

            groupbox:Button({
                Name = 'Import code',
                Callback = function()
                    tbl:Import(val4:Get())
                end
            })

            function tbl:Refresh()
                local val6 = window:ListConfigs()
                local val7 = listBox:Get()
                listBox:Refresh(val6, true)
                if val7 and not table.find(val6, val7) then
                    listBox:Set(window.LoadedConfig and table.find(val6, window.LoadedConfig) and window.LoadedConfig or nil, true)
                end
                helperFn2()
            end

            local function helperFn4(param)
                tbl:Refresh()
                listBox:Set(param, true)
            end

            function tbl:Create(param)
                param = trimString(param)
                if param == '' then
                    helperFn(false, 'Name the config', 'Type a name before creating it')
                    return
                end
                if not isValidFileName(param) then
                    helperFn(false, 'Invalid name', 'Names cannot contain \\ / : * ? " < > |')
                    return
                end
                local val6, val7 = window:SaveConfig(param)
                if val6 then
                    window.LoadedConfig = param
                    val3:Set('')
                    helperFn4(param)
                end
                helperFn(val6, val6 and 'Config created' or 'Create failed', val6 and param or tostring(val7))
            end

            function tbl:Save(param)
                local val6 = trimString(val3:Get())
                if not param and val6 ~= '' and val6 ~= listBox:Get() then
                    return tbl:Create(val6)
                end
                param = param or listBox:Get()
                if not param then
                    local val9 = trimString(val3:Get())
                    if val9 == '' then
                        helperFn(false, 'No config selected', 'Pick one from the list or type a name')
                        return
                    end
                    return tbl:Create(val9)
                end
                local val7, val8 = window:SaveConfig(param)
                if val7 then
                    window.LoadedConfig = param
                    helperFn2()
                end
                helperFn(val7, val7 and 'Config saved' or 'Save failed', val7 and param or tostring(val8))
            end

            function tbl:Load(param)
                param = param or helperFn3()
                if not param then
                    return
                end
                local val6, val7 = window:LoadConfig(param)
                helperFn2()
                helperFn(val6, val6 and 'Config loaded' or 'Load failed', val6 and param or tostring(val7))
            end

            function tbl:Delete(param)
                param = param or helperFn3()
                if not param then
                    return
                end
                window:Confirm({
                    Title = 'Delete config',
                    Content = 'Remove ' .. param .. '? This cannot be undone.',
                    Icon = 'trash-2',
                    ConfirmText = 'Delete',
                    Callback = function()
                        local val6, val7 = window:DeleteConfig(param)
                        if val6 then
                            if window:GetAutoload('Account') == param then
                                window:SetAutoload(nil, 'Account')
                            end
                            if window:GetAutoload('Global') == param then
                                window:SetAutoload(nil, 'Global')
                            end
                            listBox:Set(nil, true)
                        end
                        tbl:Refresh()
                        helperFn(val6, val6 and 'Config deleted' or 'Delete failed', val6 and param or tostring(val7))
                    end
                })
            end

            function tbl:Rename(param, param2)
                param = param or helperFn3()
                if not param then
                    return
                end
                param2 = trimString(param2)
                if param2 == '' then
                    helperFn(false, 'Name the config', 'Type the new name in the name box')
                    return
                end
                if not isValidFileName(param2) then
                    helperFn(false, 'Invalid name', 'Names cannot contain \\ / : * ? " < > |')
                    return
                end
                local val6, val7 = window:RenameConfig(param, param2)
                if val6 then
                    val3:Set('')
                    helperFn4(param2)
                end
                helperFn(val6, val6 and 'Config renamed' or 'Rename failed', val6 and (param .. ' -> ' .. param2) or tostring(val7))
            end

            function tbl:Reset()
                window:Confirm({
                    Title = 'Reset settings',
                    Content = [[Put every setting back to its default and delete this script's folder? Saved configs, themes and autoload are removed for good.]],
                    Icon = 'rotate-ccw',
                    ConfirmText = 'Reset',
                    Callback = function()
                        window:ResetConfig()
                        local val6 = window:ClearWorkspace()
                        window:_applyDefaultTheme()
                        listBox:Set(nil, true)
                        tbl:Refresh()
                        dropdown:Set('All accounts', true)
                        helperFn(val6, val6 and 'Settings reset' or 'Reset incomplete', val6 and 'Everything is back to its default' or 'Some files in ' .. window.ConfigFolder .. ' could not be deleted')
                    end
                })
            end

            function tbl:SetAutoload(value)
                value = value or helperFn3()
                if not value then
                    return
                end
                local val6, val7 = window:SetAutoload(value)
                helperFn2()
                helperFn(val6, val6 and 'Autoload set' or 'Autoload failed', val6 and value or tostring(val7))
            end

            function tbl:ClearAutoload()
                local val6 = window:GetAutoload()
                if not val6 then
                    helperFn(false, 'No autoload', 'Nothing is set to autoload')
                    return
                end
                local val7, val8 = window:SetAutoload(nil)
                helperFn2()
                helperFn(val7, val7 and 'Autoload cleared' or 'Clear failed', val7 and val6 or tostring(val8))
            end

            function tbl:ToggleAutoload(param)
