                end
                helperFn(val6 ~= false, val6 ~= false and 'Autoload mode' or 'Mode change failed', val6 ~= false and str or tostring(val7))
            end

            function tbl:Export(param)
                local val6, val7 = window:ExportConfig(param)
                if not val6 then
                    helperFn(false, 'Export failed', tostring(val7))
                    return nil
                end
                window:CopyToClipboard(val6, 'Config code')
                return val6
            end

            function tbl:Import(param)
                param = trimString(param)
                if param == '' then
                    helperFn(false, 'Nothing to import', 'Paste a config code first')
                    return
                end
                local val6, val7 = window:DecodeConfig(param)
                if not val6 then
                    helperFn(false, 'Import failed', 'Invalid config code')
                    return
                end
                local val8 = trimString(val3:Get())
                if val8 == '' then
                    val8 = nil
                    if isValidFileName(val7.Name) then
                        val8 = val7.Name
                        local num = 2
                        while window:ConfigExists(val8) do
                            val8 = ('%s (%d)'):format(val7.Name, num)
                            num += 1
                        end
                    end
                elseif not isValidFileName(val8) then
                    helperFn(false, 'Invalid name', 'Names cannot contain \\ / : * ? " < > |')
                    return
                end

                local function helperFn5()
                    local val9, val10 = window:ImportConfig(param, val8, true)
                    if val9 then
                        val4:Set('')
                        if val8 then
                            val3:Set('')
                            helperFn4(val8)
                        end
                    end
                    helperFn(val9, val9 and 'Config imported' or 'Import failed', val9 and (val8 or 'Applied to current settings') or tostring(val10))
                end

                if val7.Folder and val7.Folder ~= window.ConfigFolder then
                    window:Confirm({
                        Title = 'Different script',
                        Content = ([[This config was made for %s. Import it anyway? Only matching settings are applied.]]):format(val7.Folder),
                        Icon = 'triangle-alert',
                        ConfirmText = 'Import',
                        Callback = helperFn5
                    })
                    return
                end
                helperFn5()
            end

            local val5 = window:OnConfigChanged(function()
                tbl:Refresh()
                if window.LoadedConfig and listBox:Get() == nil then
                    listBox:Set(window.LoadedConfig, true)
                end
            end)

            val._listeners = val._listeners or {}
            table.insert(val._listeners, val5)
            helperFn2()
            return tbl
        end

