        local function getSortedPresetNames()
            local tbl, tbl2 = {}, {}
            for idx, item in ipairs(PRESET_ORDER) do
                if Library.ThemePresets[item] then
                    table.insert(tbl, item)
                    tbl2[item] = true
                end
            end
            local tbl3 = {}
            for key in pairs(Library.ThemePresets) do
                if not tbl2[key] then
                    table.insert(tbl3, key)
                end
            end
            table.sort(tbl3)
            for idx, item in ipairs(tbl3) do
                table.insert(tbl, item)
            end
            return tbl
        end

