                end
                if Library.ThemePresets[param] then
                    helperFn(false, 'Name taken', param .. ' is a built-in preset')
                    return
                end
                local val8, val9 = window:SaveTheme(param)
                tbl:Refresh()
                if val8 then
                    dropdown:Set(param, true)
                    val7:Set('')
                    helperFn2()
