                helperFn(val8, val8 and 'Theme created' or 'Create failed', val8 and param or tostring(val9))
            end

            function tbl:Save(param)
                param = param or helperFn3()
                if not param then
                    return
                end
                local val8, val9 = window:SaveTheme(param)
                helperFn(val8, val8 and 'Theme saved' or 'Save failed', val8 and param or tostring(val9))
            end

            function tbl:Load(param)
                param = param or helperFn3()
                if not param then
                    return
                end
                local val8, val9 = window:LoadTheme(param)
