                    ConfirmText = 'Delete',
                    Callback = function()
                        local val8, val9 = window:DeleteTheme(param)
                        tbl:Refresh()
                        helperFn(val8, val8 and 'Theme deleted' or 'Delete failed', val8 and param or tostring(val9))
                    end
                })
            end

            function tbl:ToggleDefault(param)
                param = param or dropdown:Get() or dropdown2:Get()
                if not param then
                    helperFn(false, 'Nothing selected', 'Pick a theme or a preset first')
                    return
                end
                local cond = window:GetDefaultTheme() == param
                local val8, val9 = window:SetDefaultTheme(not cond and param or nil)
                helperFn2()
                helperFn(val8 ~= false, cond and 'Default cleared' or 'Default theme set', val8 ~= false and param or tostring(val9))
            end

            if opts.Customize ~= false then
                groupbox:Divider()
                local colors = opts.Colors or {
                    { 'Accent', 'Accent' },
                    { 'Accent2', 'Accent 2' },
                    { 'Background', 'Background' },
                    { 'Surface2', 'Surface' },
                    { 'Outline', 'Card Outline' },
                    { 'TabStructure', 'Tab Structure' },
                    { 'Text', 'Text' },
                    { 'Muted', 'Muted text' }
                }
                for idx, item in ipairs(colors) do
                    local entry, entry2 = item[1], item[2] or item[1]
                    local val8, flag = nil, false
                    local val9
                    val9 = groupbox:ColorPicker({
                        Name = entry2,
                        Default = Theme[entry],
                        Callback = function(value)
                            val8 = value
                            if flag then
                                return
                            end
                            flag = true
                            task.delay(0.08, function()
                                flag = false
                                Library:SetTheme({ [entry] = val8 }, true)
                                dropdown2:Set(nil, true)
                            end)
                        end
                    })
                    table.insert(Library._themeListeners, function()
                        if val9.Value ~= Theme[entry] then
                            val9:Set(Theme[entry], true)
                        end
                    end)
                end
            end

            if opts.Flag ~= false then
                local str = type(opts.Flag) == 'string' and opts.Flag or '__Theme'
                local tbl2 = {
                    _type = 'Theme',
                    _searchName = 'Theme',
                    _searchKey = 'theme',
                    _listeners = {}
                }

                function tbl2:Get()
                    local tbl3 = {}
                    for idx, item in ipairs(THEME_KEYS) do
                        tbl3[item] = colorToHexLower(Theme[item])
                    end
                    return {
                        Name = dropdown2:Get() or dropdown:Get(),
                        Colors = tbl3,
                        Dim = if toggle then window._backdropDim == true else nil,
                        Transparent = if slider then (window.Transparency or (window.Transparent and 0.35 or 0)) else nil,
                        DragStyle = dropdown3 and window.DragStyle or nil,
                        IslandStyle = dropdown4 and window.IslandStyle or nil,
                        CornerRadius = slider4 and Library:GetCornerRadius() or nil,
                        UIScale = slider3 and window:GetUIScale() or nil,
                        AdaptiveSize = if toggle2 then window:GetAdaptiveSize() else nil,
                        Density = dropdown6 and Library.Density or nil,
                        Background = dropdown5 and (window.Background or '') or nil,
                        BackgroundTransparency = dropdown5 and window.BackgroundTransparency or nil
                    }
                end

                function tbl2:Set(value)
                    if type(value) ~= 'table' then
                        return
                    end
                    if type(value.Colors) == 'table' then
                        Library:SetTheme(value.Colors)
                    end
                    local name = type(value.Name) == 'string' and value.Name or nil
                    if name and Library.ThemePresets[name] then
                        Library.ThemeName = name
                        dropdown2:Set(name, true)
                        dropdown:Set(nil, true)
                    else
                        if name then
                            Library.ThemeName = name
                        end
                        dropdown2:Set(nil, true)
                        dropdown:Set(name and table.find(window:ListThemes(), name) and name or nil, true)
                    end
                    if toggle and type(value.Dim) == 'boolean' then
                        window:SetDim(value.Dim)
                        toggle:Set(value.Dim, true)
                    end
                    if slider and (type(value.Transparent) == 'number' or type(value.Transparent) == 'boolean') then
                        local num = type(value.Transparent) == 'number' and (value.Transparent <= 1 and math.floor(value.Transparent * 100 + 0.5) or math.floor(value.Transparent + 0.5)) or (value.Transparent and 35 or 0)
                        window:SetTransparent(num / 100)
                        slider:Set(num, true)
                    end
                    if dropdown3 and type(value.DragStyle) == 'string' then
                        dropdown3:Set(window:SetDragStyle(value.DragStyle), true)
                    elseif dropdown3 and type(value.DragSkeleton) == 'boolean' then
                        window:SetDragSkeleton(value.DragSkeleton)
                        dropdown3:Set(window.DragStyle, true)
                    end
                    if dropdown4 and type(value.IslandStyle) == 'string' then
                        dropdown4:Set(window:SetIslandStyle(value.IslandStyle), true)
                    end
                    if slider4 and tonumber(value.CornerRadius) then
                        slider4:Set(Library:SetCornerRadius(value.CornerRadius), true)
                    end
                    if toggle2 and type(value.AdaptiveSize) == 'boolean' then
                        window:SetAdaptiveSize(value.AdaptiveSize)
                        toggle2:Set(value.AdaptiveSize, true)
                    end
                    if slider3 and tonumber(value.UIScale) then
                        window:SetUIScale(tonumber(value.UIScale))
                        slider3:Set(math.floor(window:GetUIScale() * 100 + 0.5), true)
                    end
                    if dropdown6 and type(value.Density) == 'string' then
                        dropdown6:Set(Library:SetDensity(value.Density), true)
                    end
                    if dropdown5 and tonumber(value.BackgroundTransparency) then
                        window:SetBackgroundTransparency(tonumber(value.BackgroundTransparency))
                        slider2:Set(math.floor((1 - window.BackgroundTransparency) * 100 + 0.5), true)
                    end
                    if dropdown5 and type(value.Background) == 'string' and value.Background ~= (window.Background or '') then
                        local background = value.Background
                        dropdown5:Set(fn(background), true)
                        task.spawn(window.SetBackground, window, background)
                    end
                    helperFn2()
                end

                Library.Flags[str] = tbl2
                window:_flagCreated(str, tbl2)
            end

            window._workspaceListeners = window._workspaceListeners or {}

            table.insert(window._workspaceListeners, function()
                dropdown:Set(nil, true)
