            end)

            helperFn2()
            return tbl
        end

        Container.CreateButtonRow = Container.ButtonRow
        Container.CreateConfigManager = Container.ConfigManager
        Container.CreateThemeManager = Container.ThemeManager

        local LABEL_STYLE_HEIGHTS = {
            Plain = 18,
            Row = 20,
            Badge = 24,
            Dot = 20,
            Bar = 34,
            Stat = 44
        }

        local function resolveAccentOrColor(col)
            return Library._color(col) or Theme.Accent
        end

        local function formatStatNumber(num)
            if num == math.floor(num) then
                return tostring(math.floor(num))
            end
            return string.format('%.1f', num)
        end

        local function parseProgressPair(valA, valB)
            if type(valA) == 'number' and type(valB) == 'number' then
                return valA, valB
            end
            if type(valA) == 'string' then
                local val = (valA:gsub(',', ''))
                local val2, val3 = val:match('^%s*(%-?[%d%.]+)%s*/%s*(%-?[%d%.]+)')
                if val2 then
                    return tonumber(val2), tonumber(val3)
                end
            end
            return nil, nil
        end

        function Container:Status(opts)
            opts = normalizeOpts(opts, {
                Title = 'Name',
                Text = 'Value',
                Content = 'Value',
                CurrentValue = 'Value',
                Default = 'Value'
            })

            local style = LABEL_STYLE_HEIGHTS[opts.Style] and opts.Style or 'Plain'
            local compact = getMetrics(self).Compact
            local window = self.Window
            local entry = LABEL_STYLE_HEIGHTS[style]
            local num = 1
            local card, cardStroke = createElementCard(self, 'Frame', entry + num * 2, opts)
            card.BackgroundTransparency = 1
            cardStroke.Transparency = 1
            cardStroke:SetAttribute('Hidden', true)
            local num2 = compact and 14 or 2

            local frame = create('Frame', {
                Position = UDim2.fromOffset(num2, num),
                Size = UDim2.new(1, -num2 * 2, 0, entry),
                BackgroundTransparency = 1,
                Parent = card
            })

            local elem = {
                Value = opts.Value,
                Max = opts.Max,
                Tone = opts.Tone or 'Accent',
                Name = opts.Name or '',
                Color = opts.Color or opts.ValueColor
            }

            local label, label2, frame2, stroke, frame3, frame4, frame5
            local flag = false

            local function helperFn()
                return style == 'Plain' and (elem.Name .. ':') or elem.Name
            end

            if style == 'Plain' then
                card.AutomaticSize = Enum.AutomaticSize.Y
                frame.AutomaticSize = Enum.AutomaticSize.Y
                label = createLabel({
                    Size = UDim2.new(0, 0, 0, entry),
                    AutomaticSize = Enum.AutomaticSize.X,
                    TextSize = 14,
                    FontFace = Fonts.Regular,
                    TextColor3 = Theme.Text,
                    TextTransparency = 0.4,
                    TextTruncate = Enum.TextTruncate.None,
                    TextYAlignment = Enum.TextYAlignment.Top,
                    Parent = frame
                })
                label2 = createLabel({
                    TextSize = 14,
                    TextColor3 = Theme.Text,
                    TextTruncate = Enum.TextTruncate.None,
                    TextYAlignment = Enum.TextYAlignment.Top,
                    Parent = frame
                })
                local cond = opts.Wrap ~= false

                local function helperFn3()
                    local num3 = label.TextBounds.X + 5
                    label2.Position = UDim2.fromOffset(num3, 0)
                    if cond then
                        label2.Size = UDim2.new(1, -num3, 0, entry)
                        label2.AutomaticSize = Enum.AutomaticSize.Y
                    else
                        label2.Size = UDim2.new(0, 0, 0, entry)
                        label2.AutomaticSize = Enum.AutomaticSize.X
                    end
                    label2.TextWrapped = cond
                end

                label:GetPropertyChangedSignal('TextBounds'):Connect(helperFn3)
                helperFn3()

                function elem:SetWrap(value)
                    cond = value ~= false
                    helperFn3()
                end
            elseif style == 'Stat' then
                label = createLabel({
                    Position = UDim2.fromOffset(0, 1),
                    Size = UDim2.new(1, 0, 0, 16),
                    TextSize = 13,
                    TextColor3 = Theme.Text,
                    TextTransparency = 0.4,
                    Parent = frame
                })
                label2 = createLabel({
                    Position = UDim2.fromOffset(0, 18),
                    Size = UDim2.new(1, 0, 0, 24),
                    TextSize = 20,
