                elseif type(value) == 'string' and ({ avatar = true, headshot = true })[value:lower()] then
                    str = 'rbxthumb://type=AvatarHeadShot&id=' .. LocalPlayer.UserId .. '&w=420&h=420'
                else
                    local ok, res, res2 = pcall(window._resolveBackground, window, tostring(value))
                    if ok then
                        str, val3 = res, res2
                    else
                        val3 = tostring(res)
                    end
