                    return false, val3
                end
                imageLabel.ImageTransparency = 1
                imageLabel.Image = str
                task.spawn(function()
                    local num2 = 0
                    while not imageLabel.IsLoaded and num2 < 4 and num == val2 and imageLabel.Parent do
                        num2 += task.wait(0.05)
                    end
                    if num == val2 and imageLabel.Parent then
