            addStroke(frame, Theme.Stroke, 0, 1)

            local scrollFrame = create('ScrollingFrame', {
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ScrollBarThickness = 2,
                ScrollBarImageColor3 = Theme.Accent,
                ScrollBarImageTransparency = 0.4,
                ScrollingDirection = Enum.ScrollingDirection.Y,
                AutomaticCanvasSize = Enum.AutomaticSize.Y,
                CanvasSize = UDim2.new(),
                Parent = frame
            })

            addPadding(scrollFrame, 8, 8, 10, 10)
            create('UIListLayout', {
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 5),
                Parent = scrollFrame
            })

            local label2 = createLabel({
                Size = UDim2.fromScale(1, 1),
                Text = opts.EmptyText or 'Nothing logged yet',
                TextSize = 11,
                FontFace = Fonts.Regular,
                TextColor3 = Theme.Muted,
                TextXAlignment = Enum.TextXAlignment.Center,
                Parent = frame
            })

            local elem = { Entries = {} }
            local tbl = {}
            local num10 = 0

            local function helperFn(param)
                local entry = tbl[param]
                if not entry then
                    return
                end
                local val = Library._rich(param.Text)
                local prefix = string.format('<font color="#%s">\u{203a} </font>', Theme.Accent:ToHex())
                if cond2 and opts.Timestamps then
                    val = string.format('%s<font color="#%s">%s</font>  %s', prefix, Theme.Muted:ToHex(), os.date(opts.TimeFormat or '%H:%M:%S', param.Time), val)
                else
                    val = prefix .. val
                end
                entry.Text = val
                entry.TextColor3 = Library._color(param.Color) or Theme.Muted2 or rgb(174, 178, 187)
            end

            local function helperFn2(param)
                while #elem.Entries > param do
                    local removed = table.remove(elem.Entries, 1)
                    if tbl[removed] then
                        tbl[removed]:Destroy()
                        tbl[removed] = nil
                    end
                end
                label2.Visible = #elem.Entries == 0
            end

            local function helperFn3()
                return scrollFrame.CanvasPosition.Y >= scrollFrame.AbsoluteCanvasSize.Y - scrollFrame.AbsoluteWindowSize.Y - 4
            end

            function elem:Push(param, param2)
                local val = helperFn3()
                num10 += 1
                local tbl2 = {
                    Text = tostring(param == nil and '' or param),
                    Color = param2,
                    Time = os.time()
                }
                table.insert(elem.Entries, tbl2)
                tbl[tbl2] = createLabel({
                    Size = UDim2.new(1, 0, 0, num3),
                    AutomaticSize = Enum.AutomaticSize.Y,
                    TextSize = 11,
                    Font = Enum.Font.Code,
                    TextWrapped = true,
                    TextTruncate = Enum.TextTruncate.None,
                    RichText = true,
                    LayoutOrder = num10,
                    Parent = scrollFrame
                })
                helperFn(tbl2)
                helperFn2(num6)
                if val then
                    task.defer(function()
                        scrollFrame.CanvasPosition = Vector2.new(0, 1e7)
                    end)
                end
                return tbl2
            end

            elem.Add = elem.Push
            elem.Log = elem.Push

            function elem:Clear()
                helperFn2(0)
            end

            function elem:Get()
                local tbl2 = {}
                for idx, item in ipairs(elem.Entries) do
                    tbl2[idx] = {
                        Text = item.Text,
                        Color = item.Color,
                        Time = item.Time
                    }
                end
                return tbl2
            end

            function elem:SetTitle(value)
                if label then
                    label.Text = tostring(value)
                end
            end

            function elem:SetMaxEntries(value)
                num6 = math.max(math.floor(tonumber(value) or num6), 1)
                helperFn2(num6)
            end

            onThemeChange(frame, function()
                for idx, item in ipairs(elem.Entries) do
                    helperFn(item)
                end
            end)

            return registerElement(self, opts, elem, card, 'Log')
        end

