        local function finishOutTransition(state)
            if state.OutFrame then
                state.OutFrame.Parent = state.Area
                state.OutFrame.Visible = false
                state.OutFrame = nil
            end
            state.Out.Visible = false
        end

        local function finishInTransition(state)
            if state.InFrame then
                state.InFrame.Parent = state.Area
                state.InFrame.Position = UDim2.fromOffset(0, 0)
                state.InFrame = nil
            end
            state.In.Visible = false
        end

        function Container:_setupSubTabs()
            local page = self._page
            local topY = TOPBAR_HEIGHT + 6
            local subtabs = create('Frame', {
                Name = 'SubTabs',
