            })

            local num = topY + 32 + 6

            local subpages = create('Frame', {
                Name = 'SubPages',
                Position = UDim2.fromOffset(0, num),
                Size = UDim2.new(1, 0, 1, -num),
                BackgroundTransparency = 1,
                ClipsDescendants = true,
                Parent = page
            })

            local tbl = {
                Strip = subtabs,
                Row = frame2,
                Highlight = frame,
                Area = subpages,
                Out = create('CanvasGroup', {
                    Size = UDim2.fromScale(1, 1),
                    BackgroundTransparency = 1,
