            self._sub = tbl
            self._subTabs = {}
            self.List.Visible = false
            self:_refreshEmpty()

            frame2:GetPropertyChangedSignal('AbsoluteSize'):Connect(function()
                if self.CurrentSubTab and not tbl.Moving then
                    self:_placeSubHighlight(self.CurrentSubTab, true)
                end
            end)
        end

        function Container:_placeSubHighlight(param, param2)
            local sub = self._sub
            local scale = self.Window.Scale.Scale
            local button = param._button
            local num = button.AbsoluteSize.X / scale

            if num <= 0 then
                return
            end

            local num2 = (button.AbsolutePosition.X - sub.Row.AbsolutePosition.X) / scale

            local tbl = {
                Position = UDim2.fromOffset(num2, 0),
                Size = UDim2.fromOffset(num, 26)
            }

            if param2 or not sub.Highlight.Visible then
                sub.Highlight.Visible = true
                sub.Highlight.Position = tbl.Position
                sub.Highlight.Size = tbl.Size
            else
                sub.Moving = true
                tween(sub.Highlight, tbl, 0.28, Enum.EasingStyle.Quint)
                task.delay(0.29, function()
                    sub.Moving = false
                end)
            end

            if sub.Strip:IsA('ScrollingFrame') then
                local num3 = sub.Strip.AbsoluteSize.X / scale
                local x = sub.Strip.CanvasPosition.X
                if num2 < x then
                    tween(sub.Strip, { CanvasPosition = Vector2.new(math.max(num2 - 8, 0), 0) }, 0.3, Enum.EasingStyle.Quint)
                elseif num2 + num > x + num3 then
                    tween(sub.Strip, { CanvasPosition = Vector2.new(num2 + num - num3 + 8, 0) }, 0.3, Enum.EasingStyle.Quint)
                end
            end
        end

        function Container:SubTab(opts, param)
            if self._groupbox or self._isSubTab then
                return self.Parent:SubTab(opts, param)
            end

            opts = normalizeOpts(opts, { Title = 'Name', Description = 'Desc' })

            if param ~= nil and opts.Icon == nil then
                opts.Icon = param
            end

            if not self._subTabs then
                self:_setupSubTabs()
            end

            local sub = self._sub
            local num = #self._subTabs + 1

            local val = setmetatable({
                Name = opts.Name or ('Page ' .. num),
                Window = self.Window,
