                Text = val.Name,
                TextSize = 12,
                FontFace = Fonts.Medium,
                TextColor3 = Theme.Muted2,
                TextTruncate = Enum.TextTruncate.None,
                LayoutOrder = 2,
                Parent = button
            })

            val._button = button

            button.MouseEnter:Connect(function()
                if self.CurrentSubTab ~= val then
                    tween(val._label, { TextColor3 = Theme.Text }, 0.12)
                    if val._iconImage then
                        tweenIconColor(val._iconImage, Theme.Text, true, 0.12)
                        tween(val._iconImage, { ImageTransparency = 0 }, 0.12)
                    end
                end
            end)

            button.MouseLeave:Connect(function()
                if self.CurrentSubTab ~= val then
                    tween(val._label, { TextColor3 = Theme.Muted2 }, 0.18)
                    if val._iconImage then
                        tweenIconColor(val._iconImage, Theme.Muted2, false, 0.18)
                        tween(val._iconImage, { ImageTransparency = 0.25 }, 0.18)
                    end
                end
            end)

            button.MouseButton1Click:Connect(function()
                self:SelectSubTab(val)
            end)

            table.insert(self._subTabs, val)

            if num == 1 then
                self:SelectSubTab(val, true)
            end

            return val
        end

        Container.CreateSubTab = Container.SubTab
        Container.AddSubTab = Container.SubTab

        function Container:SelectSubTab(param, param2)
            if type(param) ~= 'table' then
                for idx, item in ipairs(self._subTabs or {}) do
                    if item.Name == param or idx == param then
                        param = item
                        break
                    end
                end
            end

            if type(param) ~= 'table' or not self._sub then
                return
            end

            local currentsubtab = self.CurrentSubTab

            if currentsubtab == param then
                return
            end

            self.Window:_resetSearch()
            self.Window:_closePopups()
            self.CurrentSubTab = param
            local sub = self._sub
            finishOutTransition(sub)
            finishInTransition(sub)
            sub.Generation += 1
            local generation = sub.Generation
            local num = param2 and 0 or 0.2

            if currentsubtab then
                tween(currentsubtab._button, { BackgroundTransparency = 1 }, num)
                tween(currentsubtab._label, { TextColor3 = Theme.Muted2 }, num)
                if currentsubtab._iconImage then
                    tweenIconColor(currentsubtab._iconImage, Theme.Muted2, false, num)
                    tween(currentsubtab._iconImage, { ImageTransparency = 0.25 }, num)
                end
            end

            tween(param._button, { BackgroundTransparency = 1 }, num)
            tween(param._label, { TextColor3 = Theme.Text }, num)

            if param._iconImage then
                tweenIconColor(param._iconImage, Theme.Accent, true, num)
                tween(param._iconImage, { ImageTransparency = 0 }, num)
            end

            self:_placeSubHighlight(param, param2)

            if param2 or not currentsubtab then
                if currentsubtab then
                    currentsubtab._frame.Visible = false
                end
                param._frame.Visible = true
                return
            end

            local num2 = param._index > currentsubtab._index and 1 or -1
            sub.OutFrame = currentsubtab._frame
            currentsubtab._frame.Parent = sub.Out
            sub.Out.GroupTransparency = 0
            sub.Out.Position = UDim2.fromOffset(0, 0)
            sub.Out.Visible = true

            tween(sub.Out, {
                GroupTransparency = 1,
                Position = UDim2.fromOffset(-num2 * 28, 0)
            }, 0.2)

            sub.InFrame = param._frame
            param._frame.Visible = true
            param._frame.Parent = sub.In
            sub.In.GroupTransparency = 1
            sub.In.Position = UDim2.fromOffset(num2 * 28, 0)
            sub.In.Visible = true
            tween(sub.In, { GroupTransparency = 0, Position = UDim2.fromOffset(0, 0) }, 0.34, Enum.EasingStyle.Quint)

            task.delay(0.2, function()
                if sub.Generation == generation then
                    finishOutTransition(sub)
                end
            end)

            task.delay(0.34, function()
                if sub.Generation == generation then
                    finishInTransition(sub)
                end
            end)
        end

