        function Window:_searchResults(param)
            local tbl = {}

            local function helperFn(param2, param3)
                if type(param2) ~= 'string' or param2 == '' then
                    return
                end
                local str = string.find(string.lower(param2), param, 1, true)
                if not str then
                    return
                end
                param3.Name = param2
                param3.At = str
                param3.Rank = str == 1 and 0 or (string.find(string.sub(param2, str - 1, str - 1), '[%s%p]') and 1 or 2)
                param3.Order = #tbl + 1
                table.insert(tbl, param3)
            end

            local function helperFn2(param2)
                return not param2._destroyed and param2._type ~= 'Section' and param2._type ~= 'Divider' and (param2._isShown == nil or param2:_isShown())
            end

            for idx, tab in ipairs(self.Tabs) do
                helperFn(tab.Name, {
                    Kind = 'Tab',
                    Tab = tab,
                    Icon = tab._iconName
                })
                for idx2, item in ipairs(tab._subTabs or { tab }) do
                    local cond = item._isSubTab and item or nil
                    local name = tab.Name
                    if cond then
                        helperFn(cond.Name, {
                            Kind = 'Page',
                            Tab = tab,
                            Sub = cond,
                            Path = tab.Name
                        })
                        name = tab.Name .. '  \u{203a}  ' .. cond.Name
                    end
                    if not item._noSearch then
                        for idx3, item2 in ipairs(item._items or {}) do
                            if helperFn2(item2) then
                                helperFn(item2._searchName, {
                                    Kind = item2._type,
                                    Tab = tab,
                                    Sub = cond,
                                    Target = item2,
                                    Path = name
                                })
                            end
                        end
                        for idx3, item2 in ipairs(item._groupboxes or {}) do
                            if item2._userVisible ~= false then
                                helperFn(item2.Name, {
                                    Kind = 'Groupbox',
                                    Tab = tab,
                                    Sub = cond,
                                    Target = item2,
                                    Path = name
                                })
                                local str = name .. '  \u{203a}  ' .. item2.Name
                                for idx4, item3 in ipairs(item2._items) do
                                    if helperFn2(item3) then
                                        helperFn(item3._searchName, {
                                            Kind = item3._type,
                                            Tab = tab,
                                            Sub = cond,
                                            Target = item3,
                                            Group = item2,
                                            Path = str
                                        })
                                    end
                                end
                            end
                        end
                    end
                end
            end

            table.sort(tbl, function(param2, param3)
                if param2.Rank ~= param3.Rank then
                    return param2.Rank < param3.Rank
                end
                return param2.Order < param3.Order
            end)

            return tbl
        end

        function Window:_flash(param, param2)
            for idx, item in ipairs({ 'SearchFlash', 'SearchGlow' }) do
                local val = param:FindFirstChild(item)
                if val then
                    val:Destroy()
                end
            end

            param2 = param2 or 8
            local accent = Theme.Accent
            local lerped = accent:Lerp(Color3.new(1, 1, 1), 0.65)

            local searchglow = create('Frame', {
                Name = 'SearchGlow',
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                ZIndex = 10,
                Parent = param
            })

            addCorner(searchglow, UDim.new(0, param2))

            local uiStroke = create('UIStroke', {
                Color = accent,
                Thickness = 1,
                Transparency = 1,
                ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                Parent = searchglow
            })

            local searchflash = create('Frame', {
                Name = 'SearchFlash',
                Size = UDim2.fromScale(1, 1),
                BackgroundColor3 = accent,
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ZIndex = 10,
                Parent = param
            })

            addCorner(searchflash, UDim.new(0, param2))

            local uiGradient = create('UIGradient', {
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 0.7),
                    NumberSequenceKeypoint.new(0.4, 0.55),
                    NumberSequenceKeypoint.new(0.5, 0),
                    NumberSequenceKeypoint.new(0.6, 0.55),
                    NumberSequenceKeypoint.new(1, 0.7)
                }),
                Rotation = 18,
                Offset = Vector2.new(-1, 0),
                Parent = searchflash
            })

            local uiStroke2 = create('UIStroke', {
                Color = Color3.new(1, 1, 1),
                Thickness = 1.6,
                Transparency = 1,
                ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
                Parent = searchflash
            })

            local uiGradient2 = create('UIGradient', {
                Color = ColorSequence.new({
                    ColorSequenceKeypoint.new(0, accent),
                    ColorSequenceKeypoint.new(0.5, lerped),
                    ColorSequenceKeypoint.new(1, accent)
                }),
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 0.45),
                    NumberSequenceKeypoint.new(0.5, 0),
                    NumberSequenceKeypoint.new(1, 0.45)
                }),
                Parent = uiStroke2
            })

            local ok = pcall(function()
                uiStroke.BorderStrokePosition = Enum.BorderStrokePosition.Inner
                uiStroke2.BorderStrokePosition = Enum.BorderStrokePosition.Inner
            end)

            local num = ok and 6 or 3

            if not ok then
                searchglow.Position = UDim2.fromOffset(num + 1, num + 1)
                searchglow.Size = UDim2.new(1, -(num + 1) * 2, 1, -(num + 1) * 2)
                searchflash.Position = UDim2.fromOffset(2, 2)
                searchflash.Size = UDim2.new(1, -4, 1, -4)
            end

            local uiScale

            if not param:FindFirstChildOfClass('UIScale') then
                uiScale = create('UIScale', { Scale = 0.975, Parent = param })
                tween(uiScale, { Scale = 1 }, 0.4, Enum.EasingStyle.Quint)
            end

            tween(searchflash, { BackgroundTransparency = 0.8 }, 0.2, Enum.EasingStyle.Quad)
            tween(uiStroke2, { Transparency = 0 }, 0.2, Enum.EasingStyle.Quad)
            tween(uiStroke, { Thickness = num, Transparency = 0.72 }, 0.35, Enum.EasingStyle.Quint)
            tween(uiGradient, { Offset = Vector2.new(1, 0) }, 0.8, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut)
            tween(uiGradient2, { Rotation = 540 }, 2.2, Enum.EasingStyle.Quad)

            task.spawn(function()
                task.wait(0.75)
                tween(searchflash, { BackgroundTransparency = 0.9 }, 0.35, Enum.EasingStyle.Sine)
                tween(uiStroke, { Thickness = num / 2, Transparency = 0.85 }, 0.35, Enum.EasingStyle.Sine)
                task.wait(0.35)
                tween(searchflash, { BackgroundTransparency = 0.84 }, 0.3, Enum.EasingStyle.Sine)
                tween(uiStroke, { Thickness = num * 0.85, Transparency = 0.76 }, 0.3, Enum.EasingStyle.Sine)
                task.wait(0.4)
                tween(searchflash, { BackgroundTransparency = 1 }, 0.55, Enum.EasingStyle.Quad)
                tween(uiStroke2, { Transparency = 1 }, 0.65, Enum.EasingStyle.Quad)
                tween(uiStroke, { Thickness = num, Transparency = 1 }, 0.65, Enum.EasingStyle.Quad)
                task.wait(0.7)
                searchflash:Destroy()
                searchglow:Destroy()
                if uiScale then
                    uiScale:Destroy()
                end
            end)
        end

        function Window:_revealResult(param)
            local tab, sub, target, group = param.Tab, param.Sub, param.Target, param.Group

            if self.CurrentTab ~= tab then
                self:SelectTab(tab)
            end

            if sub then
                tab:SelectSubTab(sub)
            end

            if not target then
                local button = sub and sub._button or tab._button
                task.delay(0.1, function()
                    if button.Parent then
                        self:_flash(button, sub and 8 or 10)
                    end
                end)
                return
            end

            local cond = group ~= nil and group:IsCollapsed()

            if cond then
                group:Expand()
            end

            local list = (sub or tab).List

            task.spawn(function()
                task.wait()
                task.wait()
                if cond then
                    task.wait(0.3)
                end
                local frame = target._frame
                if self._destroyed or target._destroyed or not frame or not frame.Parent or not list then
                    return
                end
                local scale = self.Scale.Scale
                local num = (frame.AbsolutePosition.Y - list.AbsolutePosition.Y) / scale + list.CanvasPosition.Y
                local num2 = frame.AbsoluteSize.Y / scale
                local num3 = list.AbsoluteWindowSize.Y / scale
                local num4 = math.max(list.AbsoluteCanvasSize.Y / scale - num3, 0)
                local num5 = math.clamp(num + num2 / 2 - num3 / 2, 0, num4)
                if math.abs(num5 - list.CanvasPosition.Y) > 2 then
                    tween(list, { CanvasPosition = Vector2.new(0, num5) }, 0.45, Enum.EasingStyle.Quint)
                    task.wait(0.25)
                end
                if frame.Parent then
                    self:_flash(frame, target._groupbox and 10 or 8)
                end
            end)
        end

        function Window:_resetSearch()
            if self.SearchBox and self.SearchBox.Text ~= '' then
                self.SearchBox.Text = ''
            end
        end

        function Window:_fitTitle(param)
            if not param then return end
            local rightReserved = (self.SearchBox and ((self._searchWidth or SEARCH_BOX_WIDTH) + 60) or 50)
            if param._headerRow then
                param._headerRow.Size = UDim2.new(1, -(16 + rightReserved), 0, 48)
            elseif param._title then
                local num2 = (param._titleX or 16) + rightReserved
                param._title.Size = UDim2.new(1, -num2, 0, 24)
