            })

            local isHovered = false
            local isFocused = false
            local hoverCount = 0

            local function updateSearchVisuals(duration)
                duration = duration or 0.2
                local strokeColor = (isFocused and Theme.Accent) or (isHovered and (Theme.StrokeHover or rgb(65, 70, 82))) or (Theme.Stroke or rgb(40, 44, 52))
                local strokeTrans = (isFocused or isHovered) and 0 or 0.35
                local bgColor = (isFocused or isHovered) and (Theme.Surface3 or rgb(35, 39, 46)) or (Theme.Surface2 or rgb(27, 30, 35))
                local iconColor = (isFocused and Theme.Accent) or (isHovered and Theme.Text) or Theme.Muted
                local iconTargetScale = isFocused and 1.15 or (isHovered and 1.12 or 1.0)
                local placeholderColor = isHovered and (Theme.Muted2 or rgb(180, 185, 195)) or Theme.Muted
                local targetWidth = isFocused and (SEARCH_BOX_WIDTH + 40) or (isHovered and (SEARCH_BOX_WIDTH + 14) or SEARCH_BOX_WIDTH)

                if duration == 0 then
                    stroke.Color = strokeColor
                    stroke.Transparency = strokeTrans
                    frame2.BackgroundColor3 = bgColor
                    iconImg.ImageColor3 = iconColor
                    iconScale.Scale = iconTargetScale
                    textBox.PlaceholderColor3 = placeholderColor
                    param.Size = UDim2.fromOffset(targetWidth, 30)
                else
                    tween(stroke, { Color = strokeColor, Transparency = strokeTrans }, duration)
                    tween(frame2, { BackgroundColor3 = bgColor }, duration)
                    tween(iconImg, { ImageColor3 = iconColor }, duration)
                    tween(iconScale, { Scale = iconTargetScale }, duration, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
                    tween(textBox, { PlaceholderColor3 = placeholderColor }, duration)
