            })

            addCorner(frame4, UDim.new(0, 10))
            local stroke2 = addStroke(frame4, Theme.Stroke, 1)
            createTopHighlight(frame4)

            local scrollFrame = create('ScrollingFrame', {
                Position = UDim2.fromOffset(6, 6),
                Size = UDim2.new(1, -12, 1, -12),
