            local tbl = {}
            local tbl2 = {}
            local num3 = 1
            local flag = false
            local num4 = 0
            local vec = Vector2.new(300, 0)
            local val = nil
            local fn

            local function helperFn()
                local scale = self.Scale.Scale
                local absoluteposition = self.Body.AbsolutePosition
                local num5 = self.Body.AbsoluteSize.X / scale
                local num6 = (frame.AbsolutePosition.X + frame.AbsoluteSize.X * 0.5 - absoluteposition.X) / scale
                local num7 = (frame.AbsolutePosition.Y + frame.AbsoluteSize.Y - absoluteposition.Y) / scale + 6
                local halfW = vec.X * 0.5
                num6 = math.clamp(num6, halfW + 8, math.max(num5 - halfW - 8, halfW + 8))
                frame3.Position = UDim2.fromOffset(num6, num7)
            end

            local function helperFn2()
                local scale = self.Scale.Scale
                local num5 = self.Body.AbsoluteSize / scale
                local num6 = (frame.AbsolutePosition.Y + frame.AbsoluteSize.Y - self.Body.AbsolutePosition.Y) / scale + 6
                local num7 = math.max(#tbl, 1)
                local num8 = math.min(num7, num2) * (num + 2) - 2 + 12
                num8 = math.max(math.min(num8, num5.Y - num6 - 12), num + 12)
                local num9 = math.min(math.max(frame.AbsoluteSize.X / scale, 300), math.max(num5.X - 16, 160))
                vec = Vector2.new(num9, num8)
            end

            local function helperFn3()
                for idx, item in ipairs(tbl) do
                    local cond = idx == num3
                    tween(item.Button, { BackgroundTransparency = cond and 0.35 or 1 }, 0.12)
                    tweenIconColor(item.Icon, cond and Theme.Accent or Theme.Muted, cond, 0.12)
                end
            end

            local function helperFn4()
                local num5 = (num3 - 1) * (num + 2)
                local num6 = scrollFrame.AbsoluteWindowSize.Y / self.Scale.Scale
                local y = scrollFrame.CanvasPosition.Y
                if num5 < y then
                    y = num5
                elseif num5 + num > y + num6 then
                    y = num5 + num - num6
                else
                    return
                end
                scrollFrame.CanvasPosition = Vector2.new(0, math.max(y, 0))
            end

            local function helperFn5(param2)
                if param2 == flag then
                    return
                end
                flag = param2
                num4 += 1
                local val2 = num4
                if param2 then
                    if self._closePopup and self._closePopup ~= fn then
                        self._closePopup()
                    end
                    self._closePopup = fn
                    helperFn()
                    frame3.Size = UDim2.fromOffset(vec.X, 0)
                    frame3.Visible = true
                    tween(frame3, { Size = UDim2.fromOffset(vec.X, vec.Y) }, 0.26, Enum.EasingStyle.Quint)
                    tween(stroke2, { Transparency = 0 }, 0.12)
                    tween(imageLabel, { ImageTransparency = 0.55 }, 0.26)
                    if not val then
                        val = self:_listen('Render', helperFn)
                    end
                else
                    if self._closePopup == fn then
                        self._closePopup = nil
                    end
                    tween(frame3, { Size = UDim2.fromOffset(vec.X, 0) }, 0.18, Enum.EasingStyle.Quint)
                    tween(imageLabel, { ImageTransparency = 1 }, 0.14)
                    task.delay(0.19, function()
                        if num4 == val2 and not flag then
                            frame3.Visible = false
                            stroke2.Transparency = 1
                            if val then
                                val()
                                val = nil
                            end
                        end
                    end)
                end
            end

            fn = function()
                helperFn5(false)
            end

            local function helperFn6(param2)
                if not param2 then
                    return
                end
                helperFn5(false)
                textBox.Text = ''
                if textBox:IsFocused() then
                    textBox:ReleaseFocus()
                end
                self:_revealResult(param2)
            end

            local function helperFn7(param2)
                return (string.gsub(string.gsub(string.gsub(param2, '&', '&amp;'), '<', '&lt;'), '>', '&gt;'))
            end

            local function helperFn8(param2)
                for idx, item in ipairs(tbl) do
                    item.Button:Destroy()
                end
                table.clear(tbl)
                tbl2 = self:_searchResults(param2)
                num3 = 1
                local val2 = colorToHexLower(Theme.Accent)
                for idx, item in ipairs(tbl2) do
                    if idx > 50 then
                        break
                    end
                    local button = create('TextButton', {
                        Size = UDim2.new(1, 0, 0, num),
                        BackgroundColor3 = Theme.Surface3,
                        BackgroundTransparency = 1,
                        Text = '',
                        AutoButtonColor = false,
                        LayoutOrder = idx,
                        Parent = scrollFrame
                    })
                    addCorner(button, UDim.new(0, 7))
                    local frame5 = create('Frame', {
                        Position = UDim2.fromOffset(10, 0),
                        Size = UDim2.new(1, -20, 1, 0),
                        BackgroundTransparency = 1,
                        ClipsDescendants = true,
                        Parent = button
                    })
                    create('UIListLayout', {
                        FillDirection = Enum.FillDirection.Horizontal,
                        VerticalAlignment = Enum.VerticalAlignment.Center,
                        SortOrder = Enum.SortOrder.LayoutOrder,
                        Padding = UDim.new(0, 5),
                        Parent = frame5
                    })
                    local num5 = 0
                    local val3 = nil

                    local function helperFn11(param3)
                        if not param3 then
                            return
                        end
                        num5 += 1
                        local imageLabel2 = create('ImageLabel', {
                            Size = UDim2.fromOffset(14, 14),
                            BackgroundTransparency = 1,
                            ImageColor3 = Theme.Muted,
                            ScaleType = Enum.ScaleType.Fit,
                            LayoutOrder = num5,
                            Parent = frame5
                        })
                        applyIcon(imageLabel2, param3)
                        val3 = val3 or imageLabel2
                    end

                    local function helperFn12(param3, param4, param5)
                        num5 += 1
                        return createLabel({
                            Size = UDim2.new(0, 0, 1, 0),
                            AutomaticSize = Enum.AutomaticSize.X,
                            Text = param3,
                            RichText = param5 == true,
                            TextSize = 13,
                            FontFace = param4 and Fonts.Medium or Fonts.Regular,
                            TextColor3 = param4 or Theme.Muted,
                            TextTruncate = Enum.TextTruncate.None,
                            LayoutOrder = num5,
                            Parent = frame5
                        })
                    end

                    local function helperFn13()
                        helperFn12('>')
                    end

                    local tab, sub, group = item.Tab, item.Sub, item.Group
                    local cond = item.Kind == 'Tab'
                    local cond2 = item.Kind == 'Page'
                    local cond3 = item.Kind == 'Groupbox'
                    helperFn11(tab._iconName or 'layout-grid')
                    if not cond then
                        helperFn12(tab.Name)
                        if sub then
                            helperFn13()
                            helperFn11(sub._iconName or 'layers')
                            if not cond2 then
                                helperFn12(sub.Name)
                            end
                        end
                        if group and not cond3 then
                            helperFn13()
                            helperFn12(group.Name)
                        end
                        if not cond2 then
                            helperFn13()
                        end
                    end
                    local name = item.Name
                    local num6 = item.At + #param2
                    local str = helperFn7(string.sub(name, 1, item.At - 1)) .. '<b>' .. helperFn7(string.sub(name, item.At, num6 - 1)) .. '</b>' .. helperFn7(string.sub(name, num6))
                    helperFn12(str, Theme.Accent, true)
                    local val4 = val3
                    local canActivate = makeTapGuard(button, function()
                        return scrollFrame
                    end)
                    button.MouseEnter:Connect(function()
                        if not isLastInputTouch() then
                            num3 = idx
                            helperFn3()
                        end
                    end)
                    button.MouseButton1Click:Connect(function()
                        if canActivate() then
                            helperFn6(item)
                        end
                    end)
                    table.insert(tbl, { Button = button, Icon = val4 })
                end
                label.Visible = #tbl == 0
                scrollFrame.CanvasSize = UDim2.fromOffset(0, math.max(#tbl, 1) * (num + 2) - 2)
                scrollFrame.CanvasPosition = Vector2.zero
                helperFn3()
                helperFn2()
                if flag then
