                elseif param2.KeyCode == Enum.KeyCode.Escape then
                    helperFn5(false)
                elseif isPrimaryPress(param2) then
                    local mousePos = getMousePos()
                    if not isPointInGui(mousePos, frame3) and not isPointInGui(mousePos, frame) then
                        helperFn5(false)
                    end
                end
            end)

            local function helperFn10()
                if SEARCH_BOX_WIDTH ~= self._searchWidth then
                    self._searchWidth = SEARCH_BOX_WIDTH
                    for idx, tab in ipairs(self.Tabs) do
                        self:_fitTitle(tab)
