        function Window:_trackName(param, param2)
            table.insert(self._identity.Names, { Label = param, Kind = param2 })
            self:_renderIdentity()
        end

        function Window:_trackAvatar(param, param2)
            table.insert(self._identity.Avatars, { Image = param, Placeholder = param2 })
            self:_renderIdentity(true)
        end

        local function computePlayerInitials(singleChar)
            local raw = tostring(LocalPlayer.DisplayName or LocalPlayer.Name or 'U')
            local words = {}
            for w in string.gmatch(raw, '[%w]+') do
                table.insert(words, w)
            end
            if singleChar then
                return string.upper(string.sub(words[1] or raw, 1, 1))
            end
            if #words >= 2 then
                return string.upper(string.sub(words[1], 1, 1) .. string.sub(words[2], 1, 1))
            end
            local one = words[1] or raw
            return string.upper(string.sub(one, 1, math.min(2, #one)))
        end

        function Window:_renderIdentity(param)
            for idx, item in ipairs(self._identity.Names) do
                if item.Kind == 'User' then
                    item.Label.Text = self._hideName and '@hidden' or ('@' .. LocalPlayer.Name)
                else
                    item.Label.Text = self._hideName and '••••••••••••' or LocalPlayer.DisplayName
                end
            end

            local num = param and 0 or 0.2

            for idx, item in ipairs(self._identity.Avatars) do
                tween(item.Image, { ImageTransparency = self._hideAvatar and 1 or 0 }, num)
                tween(item.Placeholder, { ImageTransparency = self._hideAvatar and 0.2 or 1 }, num)
            end

            if self._identityCallbacks then
                for idx, fn in ipairs(self._identityCallbacks) do
                    pcall(fn, param)
                end
            end
        end

        function Window:SetHideName(value)
            self._hideName = value == true
            self:_renderIdentity()
        end

        function Window:SetHideAvatar(value)
            self._hideAvatar = value == true
            self:_renderIdentity()
        end

        local function createAvatarCircle(userId, parent, props, strokeCol, strokeTrans, strokeThick)
            local frame = create('Frame', {
                BackgroundColor3 = Theme.Surface3,
                BorderSizePixel = 0,
                Parent = parent
            })
            for key, val in pairs(props) do
                frame[key] = val
            end
            addCorner(frame, UDim.new(1, 0))
            addStroke(frame, strokeCol or Theme.Stroke, strokeTrans or 0, strokeThick or 1)
            local imageLabel = create('ImageLabel', {
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                Image = 'rbxthumb://type=AvatarHeadShot&id=' .. tostring(LocalPlayer.UserId) .. '&w=150&h=150',
                Parent = frame
            })
            addCorner(imageLabel, UDim.new(1, 0))
            local imageLabel2 = create('ImageLabel', {
                AnchorPoint = Vector2.new(0.5, 0.5),
                Position = UDim2.fromScale(0.5, 0.5),
                Size = UDim2.fromScale(0.45, 0.45),
                BackgroundTransparency = 1,
                ImageColor3 = Theme.Muted,
                ImageTransparency = 1,
                ScaleType = Enum.ScaleType.Fit,
                Parent = frame
            })
            applyIcon(imageLabel2, 'user')
            userId:_trackAvatar(imageLabel, imageLabel2)
            return frame
        end

