        function Window:Rejoin()
            self:Notify({
                Title = 'Rejoining',
                Content = 'Teleporting back into this server',
                Icon = 'refresh-cw',
                Duration = 3
            })

            task.spawn(function()
                local ok, res = pcall(function()
                    if #Players:GetPlayers() <= 1 or game.JobId == '' then
                        TeleportService:Teleport(game.PlaceId, LocalPlayer)
                    else
                        TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
                    end
                end)
                if not ok then
                    self:Notify({
                        Title = 'Rejoin failed',
                        Content = tostring(res),
                        Type = 'Error',
                        Duration = 4
                    })
                end
            end)
        end

        local function hopServer(win, sortOrder, pickRandom, actionLabel)
            task.spawn(function()
                local servers = fetchPublicServers(sortOrder)
                if not servers then
                    win:Notify({
                        Title = actionLabel .. ' failed',
                        Content = 'Could not load the server list',
                        Type = 'Error',
                        Duration = 4
                    })
                    return
                end
                local tbl = {}
                for idx, item in ipairs(servers) do
                    if type(item) == 'table' and item.id ~= game.JobId then
                        local num, num2 = tonumber(item.playing), tonumber(item.maxPlayers)
                        if num and num2 and num < num2 then
                            table.insert(tbl, item)
                        end
                    end
                end
                local cond = #tbl > 0 and pickRandom(tbl) or nil
                if not cond then
                    win:Notify({
                        Title = actionLabel .. ' failed',
                        Content = 'No other open server found',
                        Type = 'Warning',
                        Duration = 4
                    })
                    return
                end
                win:Notify({
                    Title = actionLabel,
                    Content = string.format('Joining a server with %d/%d players', cond.playing, cond.maxPlayers),
                    Icon = 'server',
                    Duration = 3
                })
                local ok, res = pcall(function()
                    TeleportService:TeleportToPlaceInstance(game.PlaceId, cond.id, LocalPlayer)
                end)
                if not ok then
                    win:Notify({
                        Title = actionLabel .. ' failed',
                        Content = tostring(res),
                        Type = 'Error',
                        Duration = 4
                    })
                end
            end)
        end

        function Window:ServerHop()
            hopServer(self, 'Desc', function(param)
                return param[math.random(1, #param)]
            end, 'Server hop')
        end

        function Window:JoinLowestServer()
            hopServer(self, 'Asc', function(param)
                table.sort(param, function(param2, param3)
                    return param2.playing < param3.playing
                end)
                return param[1]
            end, 'Lowest server')
        end

