                Parent = frame
            })

            local frame2 = create('Frame', {
                Position = UDim2.fromOffset(0, 44),
                Size = UDim2.new(1, 0, 0, 28),
                BackgroundTransparency = 1,
                ClipsDescendants = true,
                Parent = frame
            })

            local frame3 = create('Frame', {
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                Parent = frame2
            })

            create('UIListLayout', {
                FillDirection = Enum.FillDirection.Horizontal,
                VerticalAlignment = Enum.VerticalAlignment.Bottom,
                SortOrder = Enum.SortOrder.LayoutOrder,
                Padding = UDim.new(0, 2),
                Parent = frame3
            })

            local isPing = param6 == 'ms'
            local num = 32
            local tbl, tbl2 = {}, {}

            for idx = 1, num do
                local bar = create('Frame', {
                    Size = UDim2.new(1 / num, -2, 0.35, 0),
                    BackgroundColor3 = isPing and Theme.Success or Theme.Accent,
                    BackgroundTransparency = idx == num and 0 or (0.75 - ((idx - 1) / num) * 0.45),
                    BorderSizePixel = 0,
                    LayoutOrder = idx,
                    Parent = frame3
                })
                addCorner(bar, UDim.new(0, 2))
                tbl[idx] = bar
            end

            local lastSample = 0

            local function helperFn(param7)
                local mutedHex = '#' .. Theme.Muted:ToHex()
                label2.Text = ('<b>%d</b><font size="12" color="%s"> %s</font>'):format(param7, mutedHex, param6 or '')
            end

            local function helperFn2(param7, param8)
                lastSample = param7
                helperFn(param7)
                if #tbl2 == 0 then
                    local base = param7 > 0 and param7 or (isPing and 42 or 60)
                    for k = 1, num - 1 do
                        local wave = math.floor(math.sin(k * 0.55) * math.max(base * 0.06, 2) + 0.5)
                        table.insert(tbl2, math.max(1, base + wave))
                    end
                end
                table.insert(tbl2, param7 > 0 and param7 or tbl2[#tbl2] or 1)
                if #tbl2 > num then
                    table.remove(tbl2, 1)
                end
                local num2, huge, num3 = param5 or 1, math.huge, 0
                for idx, item in ipairs(tbl2) do
                    num2 = math.max(num2, item)
                    huge = math.min(huge, item)
                    num3 += item
                end
                local txtHex = Theme.Text:ToHex()
                label.Text = ([[min <font color="#%s"><b>%d</b></font> ]] .. '\u{b7}' .. [[ avg <font color="#%s"><b>%d</b></font> ]] .. '\u{b7}' .. [[ max <font color="#%s"><b>%d</b></font>]]):format(txtHex, huge, txtHex, math.floor(num3 / #tbl2 + 0.5), txtHex, math.max(table.unpack(tbl2)))
                local barCol = isPing and Theme.Success or Theme.Accent
                local scaleMax = math.max(num2 * 1.35, 1)
                for idx, item in ipairs(tbl) do
                    local entry = tbl2[idx]
                    local frac = entry and math.clamp(entry / scaleMax, 0.16, 0.92) or 0.16
                    local trans = idx == num and 0 or (0.74 - ((idx - 1) / num) * 0.44)
                    tween(item, {
                        Size = UDim2.new(1 / num, -2, frac, 0),
                        BackgroundColor3 = barCol,
                        BackgroundTransparency = trans
                    }, 0.28, Enum.EasingStyle.Quint)
                end
            end

            onThemeChange(frame, function()
                helperFn(lastSample)
                local barCol = isPing and Theme.Success or Theme.Accent
                for idx, item in ipairs(tbl) do
                    item.BackgroundColor3 = barCol
                end
            end)

            return label2, helperFn2
        end

