        function Window:_featureGroups()
            local tbl, tbl2 = {}, {}

            for idx, tab in ipairs(self.Tabs) do
                if tab ~= self.Home and tab._userVisible ~= false then
                    local tbl4 = {
                        Name = tab.Name,
                        Icon = tab._iconName,
                        Items = {}
                    }
                    for idx2, item in ipairs(tab._subTabs or { tab }) do
                        local cond = item._isSubTab and item or nil

                        local function helperFn2(param, param2, param3, param4)
                            if type(param) ~= 'string' or param == '' then
                                return
                            end
                            local tbl5 = {
                                Name = param,
                                Kind = param2._type == 'ButtonRow' and 'Button' or param2._type,
                                Path = param4,
                                Result = {
                                    Tab = tab,
                                    Sub = cond,
                                    Target = param2,
                                    Group = param3
                                }
                            }
                            table.insert(tbl4.Items, tbl5)
                            tbl2[string.lower(param)] = tbl2[string.lower(param)] or tbl5
                        end

                        local function helperFn3(param, param2, param3)
                            if param._destroyed or not self._featureKinds[param._type] or (param._isShown and not param:_isShown()) then
                                return
                            end
                            if param._type == 'ButtonRow' and param.Buttons then
                                for idx3, item2 in ipairs(param.Buttons) do
                                    helperFn2(item2.Label.Text, param, param2, param3)
                                end
                            else
                                helperFn2(param._searchName, param, param2, param3)
                            end
                        end

                        if not item._noSearch then
                            for idx3, item2 in ipairs(item._items or {}) do
                                helperFn3(item2, nil, cond and cond.Name or nil)
                            end
                            for idx3, item2 in ipairs(item._groupboxes or {}) do
                                if item2._userVisible ~= false and not item2._manager then
                                    for idx4, item3 in ipairs(item2._items) do
                                        helperFn3(item3, item2, cond and (cond.Name .. '  \u{203a}  ' .. item2.Name) or item2.Name)
                                    end
                                end
                            end
                        end
                    end
                    if #tbl4.Items > 0 then
                        table.insert(tbl, tbl4)
                    end
                end
            end

            local features = self._features

            if type(features) ~= 'table' then
                return tbl
            end

            local function helperFn(param)
                if type(param) ~= 'table' then
                    param = { Name = param }
                end
                local str = tostring(param.Name or param.Title or param[1] or '')
                local entry = tbl2[string.lower(str)]
                return {
                    Name = str,
                    Desc = param.Desc or param.Description,
                    Tag = param.Tag,
                    Icon = param.Icon,
                    Kind = entry and entry.Kind,
                    Path = entry and entry.Path,
                    Result = entry and entry.Result,
                    Callback = param.Callback
                }
            end

            local tbl3, val = {}, nil

            for idx, item in ipairs(features) do
                if type(item) == 'table' and type(item.Items) == 'table' then
                    local tbl4 = {
                        Name = tostring(item.Name or item.Title or 'Features'),
                        Icon = item.Icon,
                        Items = {}
                    }
                    for idx2, item2 in ipairs(item.Items) do
                        table.insert(tbl4.Items, helperFn(item2))
                    end
                    table.insert(tbl3, tbl4)
                else
                    if not val then
                        val = { Name = self._featuresTitle or 'Features', Items = {} }
                        table.insert(tbl3, val)
                    end
                    table.insert(val.Items, helperFn(item))
                end
            end

            return tbl3
        end

