        function Window:_homeStats(param, param2, param3, param4)
            local stats = param2.Stats or { 'Players', 'Execs', 'Session', 'FPS', 'Ping' }
            local val = self:_homeCard(param, param3)

            local frame = create('Frame', {
                Size = UDim2.new(1, 0, 0, 76),
                BackgroundTransparency = 1,
                LayoutOrder = 1,
                Parent = val
            })

            create('UIGridLayout', {
                CellPadding = UDim2.fromOffset(28, 0),
                CellSize = UDim2.new(0.5, -14, 0, 76),
                SortOrder = Enum.SortOrder.LayoutOrder,
                Parent = frame
            })

            local spacerTop = create('Frame', {
                Size = UDim2.new(1, 0, 0, 10),
                BackgroundTransparency = 1,
                LayoutOrder = 2,
                Parent = val
            })

            local frame2 = create('Frame', {
                Size = UDim2.new(1, 0, 0, 1),
                BackgroundColor3 = Theme.Stroke,
                BorderSizePixel = 0,
                LayoutOrder = 3,
                Parent = val
            })

            local frame3 = create('Frame', {
                Size = UDim2.new(1, 0, 0, 0),
                AutomaticSize = Enum.AutomaticSize.Y,
                BackgroundTransparency = 1,
                LayoutOrder = 4,
                Parent = val
            })

            addPadding(frame3, 0, 0, 10, 0)

            local gridLayout = create('UIGridLayout', {
                CellPadding = UDim2.fromOffset(0, 6),
                CellSize = UDim2.new(0.3333, 0, 0, 20),
                SortOrder = Enum.SortOrder.LayoutOrder,
                Parent = frame3
            })

            local totalFigs = 0
            for idx, item in ipairs(stats) do
                if STAT_DEFINITIONS[item] and item ~= 'FPS' and item ~= 'Ping' then
                    totalFigs += 1
                end
            end

            local tbl, tbl2 = {}, {}
            local num, num2 = 0, 0

            for idx, item in ipairs(stats) do
                local entry = STAT_DEFINITIONS[item]
                if entry and not tbl[item] then
                    if item == 'FPS' or item == 'Ping' then
                        num += 1
                        tbl[item], tbl2[item] = self:_homeGraph(frame, idx, entry[1], entry[2], item == 'FPS' and 60 or 100, item == 'FPS' and 'fps' or 'ms')
                    else
                        num2 += 1
                        tbl[item] = self:_homeFigure(frame3, idx, entry[2], num2, totalFigs)
                    end
                end
            end

            frame.Visible = num > 0
            frame3.Visible = num2 > 0
            frame2.Visible = num > 0 and num2 > 0
            spacerTop.Visible = frame2.Visible

            if num == 0 then
                addPadding(frame3, 0, 0, 0, 0)
            end

            local function helperFn()
                local num4 = frame3.AbsoluteSize.X / self.Scale.Scale
                local num5 = math.clamp(num2, 1, num4 >= 440 and 5 or 3)
