                local targetScale = (self.CurrentTab ~= val and not isLastInputTouch()) and 1.02 or 1.0
                tween(uiScale, { Scale = targetScale }, 0.15, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
            end)

            local canActivate = makeTapGuard(button, function()
                return self.TabList
            end)

            button.MouseButton1Click:Connect(function()
                helperFn()
                if canActivate() then
                    self:SelectTab(val)
                end
            end)

            val._stroke = stroke
            self:_fitTitle(val)

            if not self._introDone then
