            local function helperFn5(param6, param7)
                if param6.Shown == param7 then
                    return
                end
                param6.Shown = param7
                param6.Generation += 1
                local num = param6.Home + (param4 and UDim2.fromOffset(0, param6.Direction * 6) or UDim2.fromOffset(param6.Direction * 6, 0))
                local num2 = param7 and 0 or 1
                if param7 then
                    param6.Fade.Visible = true
                    param6.Chip.Visible = true
                    param6.Chip.Position = num
                    tween(param6.Chip, { Position = param6.Home, BackgroundTransparency = 0.08 }, 0.3, Enum.EasingStyle.Quint)
                else
                    tween(param6.Chip, { Position = num, BackgroundTransparency = 1 }, 0.2, Enum.EasingStyle.Quint)
                    local generation = param6.Generation
                    task.delay(0.21, function()
                        if param6.Generation == generation then
                            param6.Fade.Visible = false
                            param6.Chip.Visible = false
                        end
                    end)
                end
                tween(param6.Fade, { BackgroundTransparency = num2 }, 0.2)
                tween(param6.Stroke, { Transparency = num2 }, 0.2)
                tween(param6.Arrow, { [param6.ArrowFade] = num2 }, 0.2)
                tween(param6.Count, { TextTransparency = num2 }, 0.2)
            end

            local function helperFn6()
                local val = helperFn2(param2.AbsoluteWindowSize)
                local num = (helperFn2(param2.AbsoluteCanvasSize) - val) / helperFn3()
                local val2 = helperFn2(param2.CanvasPosition)
                local val3 = helperFn2(param2.AbsolutePosition)
                local num2, num3 = 0, 0
                for idx, child in ipairs(param3:GetChildren()) do
                    if child:IsA('GuiObject') and child.Visible and helperFn2(child.AbsoluteSize) > 0 then
                        local num4 = helperFn2(child.AbsolutePosition) + helperFn2(child.AbsoluteSize) / 2 - val3
                        if num4 < 0 then
                            num2 += 1
                        elseif num4 > val then
                            num3 += 1
                        end
                    end
                end
                for key, val4 in pairs(tbl) do
                    local cond = key < 0 and num2 or num3
                    val4.Count.Text = tostring(cond)
                    val4.Count.Visible = cond > 0
                    helperFn5(val4, num > 1 and (key < 0 and val2 > 1 or key > 0 and val2 < num - 1))
