        function Window:_scrollTabIntoView(param)
            local tablist = self.TabList
            local scale = self.Scale.Scale
            local num = (param._button.AbsolutePosition.Y - tablist.AbsolutePosition.Y) / scale + tablist.CanvasPosition.Y
            local num2 = num + param._button.AbsoluteSize.Y / scale
            local num3 = tablist.AbsoluteWindowSize.Y / scale
            local y = tablist.CanvasPosition.Y

            if num - 8 < y then
                y = num - 8
            elseif num2 + 8 > y + num3 then
                y = num2 + 8 - num3
            else
                return
            end

            tween(tablist, { CanvasPosition = Vector2.new(0, math.max(0, y)) }, 0.35, Enum.EasingStyle.Quint)
        end

        function Window:_closePopups()
            if self._closePopup then
                self._closePopup()
            end
        end

        function Window:_popoutLayer()
            if self._popLayer then
                return self._popLayer
            end

            local popouts = create('Frame', {
                Name = 'PopOuts',
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                ZIndex = 20,
                Parent = self.Gui
            })

            local uiScale = create('UIScale', { Parent = popouts })
            self._popLayer = popouts
            self._popPanels = {}

            self:_listen('Render', function()
                local num = math.max(self.Scale.Scale, 0.05)
                if math.abs(uiScale.Scale - num) > 1e-4 then
                    uiScale.Scale = num
                    popouts.Size = UDim2.fromScale(1 / num, 1 / num)
                end
                popouts.Visible = self.Open == true and not self._destroyed
            end)

            return popouts
        end

        function Window:_popupHost(param)
            local poplayer = self._popLayer

            if poplayer and param and param:IsDescendantOf(poplayer) then
                return poplayer
            end

            return self.Body
        end

        function Window:_overPopout(param)
            local poplayer = self._popLayer

            if not poplayer or not poplayer.Visible then
                return false
            end

            for idx, item in ipairs(self._popPanels) do
                if item.Parent and item.Visible and isPointInGui(param, item) then
                    return true
                end
            end

            return false
        end

        function Window:_fade(param, param2)
            local fader, body = self._fader, self.Body
            self._fadeGeneration = (self._fadeGeneration or 0) + 1
            local fadegeneration = self._fadeGeneration

            if body.Parent ~= fader then
                fader.GroupTransparency = self._bodyAlpha
                body.Parent = fader
            end

            fader.Visible = true
            self._bodyAlpha = param
            tween(fader, { GroupTransparency = param }, param2)

            task.delay(param2 + 0.03, function()
                if self._fadeGeneration == fadegeneration and param <= 0 and not self._destroyed then
                    body.Parent = self.Root
                    fader.Visible = false
                end
            end)
        end

        function Window:SelectTab(param)
            if type(param) == 'string' then
                for _, tab in ipairs(self.Tabs or {}) do
                    if tab.Name == param then
                        param = tab
                        break
                    end
                end
            elseif type(param) == 'number' then
                param = self.Tabs[param]
            end
            if not param then return end
            if self.CurrentTab == param then
                return
            end

            local currenttab = self.CurrentTab
            if type(currenttab) == 'number' then
                currenttab = self.Tabs[currenttab]
            end
            self:_resetSearch()
            self:_closePopups()
            self.CurrentTab = param
            self:_settleTransition()
            local num = (self._transitionGeneration or 0) + 1
            self._transitionGeneration = num

            if currenttab then
                tween(currenttab._button, { BackgroundTransparency = 1 }, 0.2)
                tween(currenttab._label, { TextColor3 = Theme.Muted }, 0.2)
                if currenttab._icon then
                    tweenIconColor(currenttab._icon, Theme.Muted, false, 0.2)
                end
                local outlayer = self._outLayer
                if currenttab._page and outlayer then
                    currenttab._page.Parent = outlayer
                    self._outPage = currenttab._page
                    outlayer.GroupTransparency = 0
                    outlayer.Position = UDim2.fromOffset(0, 0)
                    outlayer.Visible = true
                    tween(outlayer, { GroupTransparency = 1, Position = UDim2.fromOffset(0, -6) }, 0.2, Enum.EasingStyle.Quint)
                    task.delay(0.18, function()
                        if self._transitionGeneration == num then
                            self:_settleOut()
                        end
                    end)
                end
            end

            self:_hideRailTip()
            -- Chitato 1:1 active tab: button stays transparent over indicator, label & icon use Theme.Text
            tween(param._button, { BackgroundTransparency = 1 }, 0.2)
            tween(param._label, { TextColor3 = Theme.Text }, 0.2)
            if param._icon then
                tweenIconColor(param._icon, Theme.Text, true, 0.2)
            end

            -- Update Global TopBar Icon and Title
            if self._topBarIcon then
                applyIcon(self._topBarIcon, param._iconName or 'layout-grid')
            end
            if self._topBarTitle then
                self._topBarTitle.Text = param.Name
            end
            -- Align SubTabs highlight if tab has subtabs
            if param._sub and param.CurrentSubTab then
                task.defer(function()
                    if param._placeSubHighlight and param.CurrentSubTab then
                        param:_placeSubHighlight(param.CurrentSubTab, true)
                    end
                end)
            end

            self:_placeIndicator(param)
            self:_scrollTabIntoView(param)
            local page = param._page
            if page then
                page.Position = UDim2.fromOffset(0, 0)
                page.Visible = true
                page.Parent = self._inLayer
                self._inPage = page
                animateCanvasFadeIn(self._inLayer)
            end

            task.delay(0.32, function()
                if self._transitionGeneration == num then
                    self:_settleIn()
                end
            end)
        end

        function Window:_settleOut()
            if self._destroyed then return end
            local outpage = self._outPage

            if outpage and self.Content and self.Content.Parent then
                pcall(function()
                    outpage.Parent = self.Content
                    outpage.Visible = false
                end)
                self._outPage = nil
            end

            if self._outLayer then
                self._outLayer.Visible = false
            end
        end

        function Window:_settleIn()
            if self._destroyed then return end
            local inpage = self._inPage

            if inpage and self.Content and self.Content.Parent then
                pcall(function()
                    inpage.Parent = self.Content
                    inpage.Position = UDim2.fromOffset(0, 0)
                end)
                self._inPage = nil
            end

            if self._inLayer then
                self._inLayer.Visible = false
            end
        end

        function Window:_settleTransition()
            self:_settleOut()
            self:_settleIn()
        end

        function Window:_buildBackdrop(param)
            local backdrop = create('Frame', {
                Name = 'Backdrop',
                Size = UDim2.fromScale(1, 1),
                BackgroundTransparency = 1,
                Visible = false,
                ZIndex = 0,
                Parent = self.Gui
            })

            local frame = create('Frame', {
                Size = UDim2.fromScale(1, 1),
                BackgroundColor3 = Color3.new(0, 0, 0),
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                ZIndex = 0,
                Parent = backdrop
            })

            create('UIGradient', {
                Rotation = 90,
                Transparency = NumberSequence.new({
                    NumberSequenceKeypoint.new(0, 0),
                    NumberSequenceKeypoint.new(0.5, 0.3),
                    NumberSequenceKeypoint.new(1, 0)
                }),
                Parent = frame
            })

            self._backdrop = backdrop
            self._backdropTintFrame = frame
            self._backdropFade = 0
            self._backdropShown = false
            self._backdropEnabled = param.Enabled ~= false
            self._backdropTint = math.clamp(tonumber(param.Tint) or 0.45, 0, 1)
            self._backdropDim = param.Dim ~= false
            self._dimLevel = self._backdropDim and 1 or 0

            table.insert(self._frameSteps, function(param2)
                self:_stepBackdrop(param2)
            end)
        end

        function Window:_stepBackdrop(param)
            local num = self._backdropShown and 1 or 0
            local backdropfade = self._backdropFade

            if backdropfade == num and num == 0 then
                return
            end

            if backdropfade < num then
                backdropfade = math.min(backdropfade + param / 0.45, num)
            elseif backdropfade > num then
                backdropfade = math.max(backdropfade - param / 0.25, num)
            end

            self._backdropFade = backdropfade

            if backdropfade <= 0 then
                self._backdrop.Visible = false
                return
            end

            local num2 = 1 - (1 - backdropfade) ^ 3
            local dimlevel = self._dimLevel

            if self._backdropDim then
                dimlevel = math.min(dimlevel + param / 0.3, 1)
            else
                dimlevel = math.max(dimlevel - param / 0.3, 0)
            end

            self._dimLevel = dimlevel
            self._backdropTintFrame.BackgroundTransparency = 1 - self._backdropTint * num2 * dimlevel
        end

        function Window:_refreshBackdrop(param)
            if not self._backdrop then
                return
            end

            local isFalse = self._backdropEnabled and self._introDone and self.Open and not self.Minimized and not self._destroyed

            if isFalse and not self._backdropShown then
                self._backdrop.Visible = true
            end

            self._backdropShown = isFalse == true
        end

        function Window:SetBackdrop(value)
            if not self._backdrop then
                self:_buildBackdrop({ Enabled = value ~= false })
            end

            self._backdropEnabled = value ~= false
            self:_refreshBackdrop(true)
        end

        function Window:SetBackdropTint(value)
            if not self._backdrop then
                self:_buildBackdrop({ Tint = value })
            end

            self._backdropTint = math.clamp(tonumber(value) or 0.45, 0, 1)
        end

        function Window:SetDim(value)
            if not self._backdrop then
                self:_buildBackdrop({ Dim = value ~= false })
            end

            self._backdropDim = value ~= false
            self:_refreshBackdrop(true)
        end

