            local val2, val3, val4 = createIslandGhost(self, num, absolutesize, Library._radius(16))
            val2.BackgroundTransparency = num2
            val3.Transparency = num2
            tween(val2, { BackgroundTransparency = 0 }, 0.11, Enum.EasingStyle.Quad)
            tween(val3, { Transparency = 0 }, 0.11, Enum.EasingStyle.Quad)
            tween(self.Scale, { Scale = (self._fitScale or 1) * 0.985 }, 0.11, Enum.EasingStyle.Quad)
            tween(self.Shadow, { ImageTransparency = 1 }, 0.2)
            val.Visible = true
            val.GroupTransparency = 1

            task.delay(0.11, function()
                if self._minimizeGeneration ~= minimizegeneration or self._destroyed then
