                    tween(self._miniScale, { Scale = 1 }, 0.3, Enum.EasingStyle.Quint)
                    tween(val, { GroupTransparency = 0 }, 0.18, Enum.EasingStyle.Quad)
                    fadeOutIslandGhost(self, val2, val3, 0.2)
                    if self.IslandStyle == 'Always Show' then
