            if opts == nil then
                opts = not self.Open
            end

            if opts == self.Open then
                return
            end

            self.Open = opts
            self:_refreshToggleButton()
            self:_refreshBackdrop(opts)
            updateZoomSinkState()
            self._minimizeGeneration = (self._minimizeGeneration or 0) + 1
            local minimizegeneration = self._minimizeGeneration
            local gui = self.Gui
            local fitscale = self._fitScale or 1
            local num = Vector2.new(self.Root.Size.X.Offset, self.Root.Size.Y.Offset) * fitscale
