                local absolutesize2 = absolutesize or self.Root.AbsoluteSize
                local val, val2, val3 = createIslandGhost(self, num5, absolutesize2, Library._radius(16))
                val.BackgroundTransparency = backgroundtransparency or 1
                val2.Transparency = backgroundtransparency or 1
                tween(val, { BackgroundTransparency = 0 }, 0.08, Enum.EasingStyle.Quad)
                tween(val2, { Transparency = 0 }, 0.08, Enum.EasingStyle.Quad)
                tween(self.Shadow, { ImageTransparency = 1 }, 0.16)
