            task.delay(duration, helperFn)
            button.MouseButton1Click:Connect(helperFn)
            table.insert(self._toasts, helperFn)

            while #self._toasts > self.MaxNotifications do
                local removed = table.remove(self._toasts, 1)
                removed()
            end

            return { Dismiss = helperFn }
