        function Window:Destroy()
            if self._destroyed then
                return
            end

            self._destroyed = true

            for idx, win in ipairs(Library.Windows) do
                if win == self then
                    table.remove(Library.Windows, idx)
                    break
                end
            end
            updateZoomSinkState()

            for idx, item in ipairs(self._connections) do
                pcall(function()
                    item:Disconnect()
                end)
            end

            self._connections = {}

            self._inputListeners = {
                Began = {},
                Changed = {},
                Ended = {},
                Render = {}
            }

            self._frameSteps = {}

            if self._pendingFlags then
                self._pendingFlags = {}
            end

            for key, val2 in pairs(Library.Flags) do
                if val2._window == self and val2._type == 'Toggle' and val2.Value == true then
                    task.spawn(pcall, val2.Set, val2, false)
                end
            end

            local val = Library._registry()

            if val and val[self._registryKey] == self then
                val[self._registryKey] = nil
            end

            local gui = self.Gui
            local flag = false

            local function helperFn()
                if flag then
                    return
                end
                flag = true
                if not pcall(gui.Destroy, gui) then
                    pcall(function()
                        gui.Enabled = false
                    end)
                end
            end

            local ok, res = pcall(function()
                if self._dialog then
                    self._dialog.Close()
                end
                self:_closePopups()
                local fitscale = self._fitScale or 1
                tween(self.Scale, { Scale = fitscale * 0.92 }, 0.22, Enum.EasingStyle.Quint)
                self:_fade(1, 0.2)
                tween(self.BodyStroke, { Transparency = 1 }, 0.12)
                tween(self.Shadow, { ImageTransparency = 1 }, 0.2)
                if self.MiniBar and self.MiniBar.Visible then
                    tween(self.MiniBar, { GroupTransparency = 1 }, 0.18)
                end
                if self._backdrop then
                    tween(self._backdropTintFrame, { BackgroundTransparency = 1 }, 0.2)
                end
                for idx, item in ipairs({ self.ToggleButton, self.OpenButton }) do
                    if typeof(item) == 'Instance' and item:IsA('GuiObject') then
                        tween(item, { Size = UDim2.fromOffset(0, 0) }, 0.2, Enum.EasingStyle.Quint)
                    end
                end
            end)

            if not ok then
                warn([[[IggyUiFork] unload animation failed, removing the window directly: ]] .. tostring(res))
                helperFn()
                return
            end

            task.delay(0.24, helperFn)
        end

        Window.Unload = Window.Destroy

        function Library:Destroy()
            for idx = #Library.Windows, 1, -1 do
                local win = Library.Windows[idx]
                if win then
                    win:Destroy()
                end
            end
            updateZoomSinkState()
        end

        Library.Unload = Library.Destroy
        local getThreadIdentityFn = getthreadidentity or getidentity or get_thread_identity or (syn and syn.get_thread_identity)
        local setThreadIdentityFn = setthreadidentity or setidentity or set_thread_identity or (syn and syn.set_thread_identity)
        local initialThreadIdentity = nil

        if getThreadIdentityFn then
            local ok, res = pcall(getThreadIdentityFn)
            if ok and type(res) == 'number' then
                initialThreadIdentity = res
            end
        end

        local function needsIdentityElevation()
            local win = Library.Windows[#Library.Windows]
            local gui = win and win.Gui
            if typeof(gui) ~= 'Instance' then
                return false
            end
            return not pcall(function()
                return gui.Name
            end)
        end

        local heartbeatTaskQueue = {}

        RunService.Heartbeat:Connect(function()
            if #heartbeatTaskQueue == 0 then
                return
            end
            local val = heartbeatTaskQueue
            heartbeatTaskQueue = {}
            for idx, item in ipairs(val) do
                item()
            end
        end)

        local function runOnHeartbeat(fn, ...)
            local packed = table.pack(...)
            local val = nil
            local flag = false
            table.insert(heartbeatTaskQueue, function()
                if not flag then
                    val = table.pack(pcall(fn, table.unpack(packed, 1, packed.n)))
                end
            end)
            local num = os.clock() + 5
            while val == nil do
                if os.clock() > num then
                    flag = true
                    error('[IggyUiFork] trusted call timed out', 0)
                end
                task.wait()
            end
            if not val[1] then
                error(val[2], 0)
            end
            return table.unpack(val, 2, val.n)
        end

        local wrappedTablesCache = setmetatable({}, { __mode = 'k' })
        local wrapReturnedTables

        local function wrapMethodWithIdentity(fn)
            return function(...)
                if needsIdentityElevation() then
                    if setThreadIdentityFn then
                        pcall(setThreadIdentityFn, initialThreadIdentity or 8)
                    end
                    if needsIdentityElevation() then
                        return wrapReturnedTables(runOnHeartbeat(fn, ...))
                    end
                end
                return wrapReturnedTables(fn(...))
            end
        end

        function wrapReturnedTables(...)
            for idx = 1, select('#', ...) do
                local val = select(idx, ...)
                if type(val) == 'table' and not wrappedTablesCache[val] then
                    local val2 = getmetatable(val)
                    if val2 ~= Window and val2 ~= Container then
                        wrappedTablesCache[val] = true
                        for key, val3 in pairs(val) do
                            if type(key) == 'string' and type(val3) == 'function' and key:sub(1, 1) ~= '_' then
                                val[key] = wrapMethodWithIdentity(val3)
                            elseif type(key) == 'number' and type(val3) == 'table' then
                                wrapReturnedTables(val3)
                            end
                        end
                    end
                end
            end

            return ...
        end

        for idx, item in ipairs({ Library, Window, Container }) do
            for key, val in pairs(item) do
                if type(key) == 'string' and type(val) == 'function' and key:sub(1, 1) ~= '_' then
                    item[key] = wrapMethodWithIdentity(val)
                end
            end
        end

        pcall(function()
            local env = getgenv and getgenv() or shared
            if type(env) == 'table' then
                env.IggyUiFork = Library
                env.AwaUI = Library
            end
        end)

        return Library
    end)()
    return uiModule
end

return createBundledUI()
